pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size <= post_residual {
            // reward proportional to how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot fit here: penalize leaving large awkward gaps
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize creating dead space below the minimum item size (unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer bins with residual below mean (tighter bins get filled first),
    // keeping emptier bins flexible for larger future items.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Mild penalty for opening a new bin when existing bins fit well.
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if many bins are open and fragmented, new bin can be fine
        score -= (open_bins_count as f64).min(20.0);
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "reusable"
    // residue classes (multiples of small denominators) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Dead-space penalty: tiny leftovers that few future items can use.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Sweet-spot leftovers: common small item sizes fit here.
    if pr >= 10 && pr <= 30 {
        score -= 12.0;
    }
    // Exact fit is perfect.
    if pr == 0 {
        score -= 60.0;
    }

    // Modulo-class reward: leftover divisible by 10 aligns with typical item
    // granularity, making the residual more "usable".
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    // Integer-division harmonic: leftover in the same decade class as the
    // next item's size suggests a good follow-up fit.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 10.0;
            // Extra reward if leftover is within one small step of next item.
            let gap = pr - next_item_size;
            if gap <= 10 {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this bin's leftover anyway; mild penalty
            // proportional to how far off we are.
            score += (next_item_size - pr) as f64 * 0.15;
        }
        // Harmonic pairing: post_residual + next item leaves a multiple-of-10
        // class residual again.
        if next_item_size <= pr && (pr - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when existing
    // bins are fragmented or nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.45 * cap + 0.25 * mean_residual - 6.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 15.0; // can't happen for empty bin, but keeps class logic
        }
    }

    // Tie-break toward filling fuller bins: residual fraction weighting.
    score += 0.05 * (bin_residual as f64 / cap) * 10.0;

    // Mean-residual coupling: when open bins are on average roomy, prefer
    // compacting into tighter ones (penalize bins above mean residual).
    if bin_residual as f64 > mean_residual {
        score += 0.10 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small gaps that nothing can fit are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 40.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Last chance: only this bin can fit the item; strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // Pressure from many open bins: discourage spreading across bins
    // when already many are open; encourage using existing space.
    score += 3.0 * open_bins_count as f64;

    // Prefer bins whose residual is below the mean (pack the fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if the next item would fit into this bin's post_residual,
    // reward keeping this residual; if it would not fit anywhere else either,
    // slight penalty for leaving a residual the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when no open bin fits well (large residual waste avoided).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, reduced late in the stream
        // (fewer future items to benefit from consolidation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // new bin has room for the lookahead item too
        }
        if fitting_bins_count == 1 {
            score += 80.0; // never open a new bin when one open bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    // Gaps below the minimum possible item size (1) are impossible, but gaps
    // smaller than a "typical" item (say < 20) are likely dead space.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }
    // Perfect fit: strongly reward zero residual.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Coupling: dead space penalty scales with how many bins are open
    // (more open bins => more pressure to keep bins tight).
    let open_pressure = open_bins_count as f64;
    if post_residual > 0 && post_residual < 20 {
        score += open_pressure * 2.5;
    }

    // Lookahead: if the next item fits exactly into post_residual,
    // reward leaving that gap; otherwise penalize gaps close to next size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless dead space is egregious).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: neutral-to-slightly-positive baseline so it is only
    // chosen when open bins have bad fits.
    if bin_residual == bin_capacity {
        score += 15.0 + open_pressure * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (tighter bins) when post_residual is small.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Progression: late in stream, tighten more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.1 + 0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact fits (dead space zero).
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a perfect chain placement -- reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves some slack: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: the leftover is likely dead space.
            // Penalize more if leftover is small (unusable) relative to item range.
            let leftover = post_residual as f64;
            if leftover < 10.0 {
                score += 60.0;
            } else {
                score += 0.5 * leftover;
            }
        }
    } else {
        // Last item: pure tightness packing.
        score -= 100.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: prefer bins whose residual is below the mean
    // (filling fuller bins first keeps many partially-filled bins available).
    score += 0.6 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.3 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate: opening a fresh bin is only attractive early in the
    // stream or when the current fit is very poor. Otherwise penalize it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Penalize new bins more as stream progresses; allow it for large items
        // or when many open bins already exist (spread load).
        score += 90.0 * progress - 25.0 * fit_quality - 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Threshold tuned around smallest item (1..100).
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            60.0 // unusable tiny gap
        } else if post_residual < 20 {
            25.0 // only fits very small items
        } else {
            0.0
        };
        score += dead;
    }

    // Reward near-perfect fits (waste <= 5).
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // gap too small for the upcoming item: dead space
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    if bin_residual == bin_capacity {
        // Opening new bins is costly; penalize when decent alternatives exist.
        if fitting_bins_count > 0 {
            score += 30.0 + 5.0 * open_bins_count as f64;
        } else {
            score = -100.0; // must open a bin
        }
        // Late in stream, prefer filling existing bins even more.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 20.0;
        }
    }

    // Open-bin pressure: with many open bins, favor consolidating into
    // tighter (smaller-residual) bins to close them out sooner.
    score += (open_bins_count as f64) * (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Archetype #167: strict dead-space avoidance + open-bin pressure.
    let mut score = 0.0;

    // Dead-space penalty: small leftovers (<10, min item size) are pure waste.
    // Penalize non-linearly as post_residual shrinks into the "dead zone".
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 + (10 - post_residual) as f64 * 6.0; // tiny gap = worst outcome
        } else if post_residual < 20 {
            score += 12.0 + (20 - post_residual) as f64 * 2.0; // risky gap
        } else {
            // Usable leftover: mild reward proportional to how well it's filled.
            score += post_residual as f64 * 0.35;
        }
    } else {
        score -= 25.0; // perfect fit: strongly favored
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Open-bin pressure: prefer spreading across existing bins, but
    // counterbalance so a new bin is only opened when fits are poor.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish baseline; open a new bin only
    // when placing here would create dead space or the fit is very loose.
    if bin_residual == bin_capacity {
        score = 55.0 - fill * 0.0; // fixed anchor; dead-space terms above won't apply (post_residual = C - item)
        // Allow new bin to win when current-bin placement is wasteful:
        if post_residual < 10 {
            score -= 10.0; // prefer fresh bin over creating a dead gap
        }
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item is large and this placement strands it, slight penalty.
    if next_item_size > post_residual && next_item_size > bin_capacity / 2 && post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mean-residual coupling: when open bins are already loose, discourage
    // adding more slack; when they're tight, tolerate slack.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Late-stream consolidation: near the end, favor filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible
    // future item are effectively wasted capacity.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Strong reward for exact / near-exact fits.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Non-linear tightness reward: favor bins whose residual is consumed
    // proportionally well.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins when the
    // stream is still long.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    // to keep a pool of large residuals available.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Lookahead: bonus if the next item can still fit in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 15.0 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let desperation = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        score += 70.0 - desperation - 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 + norm_pr * progress * 20.0
                 + (1.0 - norm_pr) * (1.0 - norm_pr) * progress * 30.0;
    score += coupling;

    // Reward tight fits (small post residual), more strongly later in stream
    score -= (1.0 - norm_pr) * (1.0 - progress) * 10.0;

    // Penalize bins with residual far from mean residual (fragmentation)
    score += ((pr - mean_residual) / cap).abs() * 8.0;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: bonus if next item fits well in post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: mildly discourage unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress - 2.0 * open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: exact fits are perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residues are dead space.
    // Penalize residues in "dead" classes (1..=9) which few items can reuse.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 3.0 } else { 0.0 };
        score += dead * (post_residual as f64).powf(0.5);
    }

    // Modulo-10 harmonic classes: residues that are multiples of 10 are more
    // reusable (item sizes often cluster on decade boundaries).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: reward when next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Fraction of post_residual consumed by the next item.
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * frac;
        } else {
            // Next item cannot use this residue: mild penalty scaled by waste.
            score += 2.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless the item
    // is huge relative to mean residual (a fresh bin is genuinely needed).
    if bin_residual == bin_capacity {
