    // Base: residual after placement, but with non-linear dead-space penalty.
    let pr = post_residual as f64;
    score += pr;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (min item size 1, but practically < ~15) are waste.
    if post_residual > 0 {
        let dead_threshold = 12.0 + 0.15 * mean_residual;
        if pr < dead_threshold {
            // Quadratic penalty for unusable slivers.
            score += 3.0 * (dead_threshold - pr) / dead_threshold * (1.0 + pr / dead_threshold);
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if pr <= 5.0 {
        score -= 10.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless fit is excellent.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when current bins have poor fit.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish, penalize when open bins exist with room.
        score = bin_capacity as f64 * 0.9 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: new bin is correct
        }
        // Lookahead: if next item is small, an empty bin is flexible.
        if next_item_size > 0 && (next_item_size as f64) < 0.25 * bin_capacity as f64 {
            score -= 5.0;
        }
    } else {
        // Lookahead synergy: prefer bins whose post_residual accommodates next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 4.0;
            } else if post_residual > 0 && post_residual < next_item_size {
                score += 2.0 * (next_item_size - post_residual) as f64 / 20.0;
            }
        }
        // Prefer filling bins with larger residuals when mean residual is high (fragmentation risk).
        if (bin_residual as f64) > mean_residual {
            score -= 1.5;
        } else {
            score += 1.0;
        }
    }

    // Tiny deterministic tie-breaker favoring tighter fits.
    score += 0.001 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // Reward a tight-but-feasible leftover relative to next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space: post_residual too small for next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 40.0 * (waste / 50.0).min(2.0);
        }
    }

    // Reward using bins with low residual (tight packing) relative to mean residual.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 25.0 * (res - mean_residual) / mean_residual;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins could fit, unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 - 30.0 * progress;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // New bin can host item + next item: mild bonus.
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose residual is barely larger than the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large leftover space wasted on a big item (dead space creation).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // nearly perfect fit bonus
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to wasted potential.
        score += 2.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = (fitting_bins_count == 0) as i32;
        // Base penalty; reduced when no open bin fits or many bins already open with low mean residual.
        let mut new_bin_penalty = 20.0;
        if poor_fits == 1 {
            new_bin_penalty -= 12.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            new_bin_penalty -= 6.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        new_bin_penalty += 8.0 * progress;
        score += new_bin_penalty;
    }

    // Global state: prefer bins with below-average residual (keep big holes for big future items).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer filling more crowded bins to reduce bin count pressure.
    score -= 0.3 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;

    // Polynomial interaction: penalize large residuals early, reward late
    score += prn * (0.5 - progress) * 20.0;
    score -= prn * prn * (1.0 - prog_sq) * 15.0;
    score += prn * prog_cu * 25.0;

    // Smooth dead-space penalty: quadratic in post_residual, damped by progress
    let dead = if pr > 0.0 { (cap - pr) / cap } else { 0.0 };
    score += (1.0 - dead) * (1.0 - dead) * 10.0 * (0.3 + 0.7 * progress);

    // Lookahead coupling: smooth reward if next item fits remaining space
    if next_item_size > 0 {
        let fits = (next_item_size as f64) <= pr;
        let tight = (next_item_size as f64 - pr).abs() / cap;
        if fits {
            score -= 12.0 * (1.0 - tight) * (1.0 - 0.5 * progress);
        } else {
            score += 8.0 * tight * (1.0 - prog_sq);
        }
    }

    // Last-chance bin: smooth penalty for wasting it on a bad fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = prn;
        score -= 18.0 * (1.0 - waste) * (1.0 - waste);
    }

    // New-bin candidate: mild bias against opening bins late in the stream
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mean residual alignment: prefer bins close to mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: residues divisible by common item
    // granularities (10, 20, 25, 50) are more reusable than odd scraps.
    let r = post_residual;
    let class_bonus: f64 = if r % 50 == 0 {
        60.0
    } else if r % 25 == 0 {
        40.0
    } else if r % 20 == 0 {
        35.0
    } else if r % 10 == 0 {
        25.0
    } else if r % 5 == 0 {
        10.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Exact lookahead match: next item exactly fills the post residual.
    if next_item_size == r {
        score -= 400.0;
    } else if next_item_size > 0 && next_item_size <= r {
        // Next item fits but leaves a new residue; prefer small leftover.
        let next_post = r - next_item_size;
        score -= 30.0 + (next_post as f64) * 0.3;
        if next_post % 10 == 0 {
            score -= 15.0;
        }
    } else if next_item_size > r {
        // Dead-end residue for the lookahead item.
        score += 50.0 + (r as f64) * 0.2;
    }

    // Small residuals that are unusable for the minimum item size (1..100
    // interface) are pure dead space; but under the 10..80 regime penalize
    // residues below 10 strongly.
    if r < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well, i.e.
    // when this item leaves a large, well-aligned residual elsewhere OR
    // the stream is early and future flexibility matters.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early in the stream: fresh bins keep flexibility cheap.
        let flexibility = (1.0 - progress) * 40.0;
        // Penalize opening new bins when many are open and mean residual
        // is large (fragmentation signal).
        let fragmentation = open_bins_count as f64 * 2.0 + mean_residual * 0.5;
        score = 100.0 - flexibility + fragmentation;
        // If the item is large relative to capacity, a fresh bin is natural.
        if item_size >= 60 {
            score -= 40.0;
        }
        // Never open a new bin for a perfect-fit opportunity elsewhere.
        if fitting_bins_count >= 1 && post_residual <= 10 {
            score += 200.0;
        }
    }

    // Prefer packing into bins whose residual is already small (tightening),
    // scaled by how many bins compete.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any post_residual that can never be filled
    // by the smallest possible item is pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit bonus (post_residual == 0 handled below)
    }
    if post_residual == 0 {
        score -= 50.0; // reward perfect closure strongly
    }

    // Gaps that cannot fit the lookahead item are likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize small unusable gaps proportionally to how far below the
    // typical item size they fall.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when there are already many open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a new bin costly unless the current
    // fit is terrible (large dead space). New bin has post_residual = C - item.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.3;
        // But allow a new bin late in the stream if open bins are messy.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps residuals balanced, avoiding many tiny-gap bins).
    score += (mean_residual - bin_residual as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0; // near-guaranteed future tight fit
    }
    // Near-match bonus: next item leaves only a tiny sliver.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 300.0 - slack * 10.0;
        } else {
            // next item fits but leaves room; mild reward scaled by slack
            score -= 200.0 / (1.0 + slack / 20.0);
        }
    }
    // Next item cannot fit here: penalize small dead space more than large.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64;
    }

    // Reward bins tighter than the mean residual (better consolidation).
    let res = post_residual as f64;
    score -= (mean_residual - res) * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Early in stream: keep bins balanced (mild); late: pack tight aggressively.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if progress < 0.3 {
        score += (res - mean_residual).abs() * 0.5;
    } else {
        score -= (bin_capacity as f64 - res) * 0.3;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 60.0 };
        score += 250.0 + desperation + (open_bins_count as f64) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 12 {
        score += 10.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 9.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 6.0 * fill * (1.0 + open_bins_count as f64 / 20.0);

    // Time-horizon term: early in the stream, be more conservative about
    // fragmenting bins; late in the stream, just pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Compare against global mean residual: bins far below mean residual
    // (i.e., emptier than average) are less attractive.
    score += 0.08 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: opening a fresh bin is acceptable only
    // when the fit into open bins would be very poor (high post_residual).
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual.max(15.0) {
            score -= 4.0; // poor fits elsewhere -> new bin is fine
        } else {
            score += 18.0; // decent fits exist -> discourage new bin
        }
    }

    // Mild non-linear coupling: penalize medium dead zones quadratically.
    let pr = post_residual as f64;
    score += 0.004 * pr * pr * (1.0 - fit_ratio.min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * (1.0 + 2.0 * p2 + 1.5 * p3);
    score += 30.0 * coupling;

    // Penalize large dead space relative to mean residual smoothly
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev.abs();

    // Reward tight fits (small post_residual) with smooth quadratic bonus
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - 0.5 * progress);

    // Lookahead: reward bins whose post_residual can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            score += 12.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: smooth reward scaled by scarcity of fitting bins
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.3 * progress);
    } else if fitting_bins_count > 2 {
        score += 4.0 * ((fitting_bins_count - 2) as f64).ln();
    }

    // Mild penalty for many open bins, smoothly increasing with progress
    score += 1.5 * (open_bins_count as f64) * progress * 0.1;

    // New-bin candidate: penalize slightly unless post_residual would be very tight
    if bin_residual == bin_capacity {
        score += 8.0 - 10.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals divisible by large divisors are "harmonic" and reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Perfect harmonic classes: post_residual divisible by common item granularities
    let mut harmony = 0.0f64;
    for d in [5u32, 10, 20, 25, 50] {
        if pr % d == 0 && pr > 0 {
            harmony += 12.0 / d as f64;
        }
    }
    score -= harmony;

    // Dead-space penalty: tiny residuals that almost nothing can fit.
    if pr > 0 && pr < 10 {
        score += 45.0;
    } else if pr < 20 {
        score += 12.0;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0; // perfect follow-up fit
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // reward tight follow-up, penalize wasteful ones
            score -= 30.0 * (1.0 - slack / cap);
            // harmonic bonus if post_residual - next is again harmonic
            let npr = pr - next_item_size;
            if npr % 10 == 0 { score -= 8.0; }
        } else {
            // next item won't fit here; penalize more if this residual is stranded
            score += 10.0 + prf * 0.15;
        }
    }

    // Last-chance bin: only fitting bin — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless
    // no good existing option exists (existing bins get tightness rewards).
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Tightness reward: filling a bin nearly full is good.
    let fill = 1.0 - prf / cap;
    score -= 15.0 * fill * fill;

    // Prefer bins below mean residual (keeps residual variance low).
    score += 0.05 * (prf - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: unusable tiny gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // If the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 180.0;
        } else if post_residual - next_item_size < 10 {
            score -= 40.0;
        }
    }
    // If next item cannot fit in this post-residual, penalize slightly unless gap is large.
    if next_item_size > post_residual {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few open bins, tolerate new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.6 + 0.4 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: opening a new bin should only win when the item
    // would leave a bad gap in every open bin, or few bins are open.
    if bin_residual == bin_capacity {
        score += 60.0 + pressure * 2.0;
        if post_residual == bin_capacity {
            // fallthrough: base already handles
        }
    }

    // Slight preference for tight fits relative to bin residual.
    score -= 30.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Mean-residual coupling: if this bin is tighter than average, prefer it.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize creating dead space the next item cannot use.
        score += 0.6 * (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
    }

    // Perfect fits get a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Compare post_residual against mean residual: prefer bins tightened below average.
    score += 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in the stream, be more willing to open new bins (keep residuals large).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 8.0 * progress;
    }

    // Penalize very small post residuals only mildly when many bins are open.
    if post_residual > 0 && post_residual < 10 && open_bins_count > 4 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space: small post_residual that is still unusable is fine,
    // but medium post_residual (wasted potential) is bad.
    if post_residual > 0 {
        let waste = (post_residual as f64 / bin_capacity as f64).powf(1.5);
        score += 12.0 * waste;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to leftover gap.
            score += 3.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in stream, prefer opening new bins less (consolidate);
    // late in stream, prefer tight packing of existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    // Many open bins with high mean residual: encourage consolidating into
    // bins whose residual is above mean (drain the fragmented ones).
    if (bin_residual as f64) > mean_residual {
        score -= 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    } else {
        score += 2.0 * ((mean_residual - bin_residual as f64) / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this empty bin has large residual and item is large or few fittings).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin when item is large relative to capacity or fits are scarce.
        score = 40.0 * item_frac * pressure + 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // Reserve pairing potential: slight bonus for fresh bin.
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses
    score -= (norm_post * norm_post) * (1.0 + 3.0 * progress) * 20.0;

    // Penalize large leftover dead space non-linearly
    score += (norm_post * norm_post * norm_post) * 30.0 * (0.5 + progress);

    // Last-chance bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= (1.0 - slack) * (5.0 + 10.0 * progress);
    }

    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // Deviation from mean residual: prefer bins with residuals near the mean (balanced use)
    let dev = post_residual as f64 - mean_residual;
    score += (dev * dev) / (bin_capacity as f64) * 0.05;

    // Slight bias toward opening new bins for large items when few bins fit
    score += norm_item * (fitting_bins_count as f64) * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let post_frac = post_residual as f64 / cap;

    // Harmonic class of the post residual: classify leftover space into
    // usable "slots". Leftovers that exactly match common item sizes or
    // their sums are valuable; odd leftovers are dead space.
    let pr = post_residual;
    // Reward exact-fit classes: post residual in {0} is perfect.
    if pr == 0 {
        score -= 50.0;
    } else {
        // Modulo arithmetic on post_residual: class-4 and class-5 residuals
        // (multiples of 10/20) tend to be reusable since items are
        // frequently multiples of 10.
        let m10 = pr % 10;
        if m10 == 0 {
            // residual is a "round" leftover: reusable by future items
            score -= (pr as f64) * 0.30;
        } else {
            // dead space penalty grows with distance to nearest round class
            let dist = m10.min(10 - m10);
            score += dist as f64 * 1.5;
        }

        // Integer division thresholds: residual >= 80 is a "big slot"
        // (can hold any item), residual < 10 is nearly dead.
        if pr >= 80 {
            score -= 8.0;
        } else if pr < 10 {
            score += 6.0;
        }

        // Harmonic fraction classes of capacity: 1/2, 1/3, 1/4 thresholds
        if post_frac > 0.5 {
            score -= 3.0; // still half-empty: flexible
        } else if post_frac > 1.0 / 3.0 {
            score -= 1.0;
        } else if post_frac < 0.05 {
            score += 4.0; // sliver: nearly dead space
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next item fits: bonus proportional to how well it fills
            let fill = next_item_size as f64 / pr as f64;
            score -= 10.0 * fill;
            // harmonic class match: both round numbers
            if next_item_size % 10 == 0 && pr % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual; penalize large residuals
            // that the lookahead wastes
            score += (pr.saturating_sub(0)) as f64 * 0.05;
            if pr >= next_item_size - 5 && pr < next_item_size {
                score += 5.0; // painfully-close miss
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_frac < 0.08 {
            score += 10.0; // but not if it creates a sliver
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the current item is large or few bins fit.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // Empty-bin baseline: slightly worse than a good fit, better than a bad one.
        score = cap * 0.55 - item_frac * 10.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if item_size >= 60 {
            score -= 6.0; // big items start fresh bins happily
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 4.0; // room for pairing in the fresh bin
        }
        // Late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 3.0 + open_bins_count as f64 * 0.5;
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual
    // (fills the emptier bins first, keeping tight bins tight).
    let res_frac = bin_residual as f64 / cap;
    if res_frac < mean_residual / cap {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 9 {
        score += 120.0 + (10 - post_residual.min(10)) as f64 * 15.0;
    }

    // Reward tight fits: the smaller post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    } else {
        // Last item: just minimize waste, close bins aggressively.
        score += post_residual as f64 * 0.5;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.5 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin's residual is far below average, it's a good filler.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 35.0 + 3.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0; // item can't fit anything else anyway handled by fitting count
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 150.0 + 0.5 * next_item_size as f64;
        } else {
            // dead space relative to next item
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
        // chain fit: would next item then still leave usable space?
        if post_residual >= next_item_size && post_residual - next_item_size >= 10 {
            score -= 40.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        score += 50.0 + 0.8 * (open_bins_count as f64);
        // allow new bin if item is large and next item is large too (pairing strategy)
        if item_size >= 50 && next_item_size >= 50 {
            score -= 120.0;
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 30.0 * progress * (open_bins_count as f64).log2().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear term.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: penalize if placing here leaves no room for the next item,
    // but this bin could have held it; reward if next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 6.0;
        }
        // Reward chain fits: current and next both fit snugly.
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 10.0;
        }
    }

    // Time horizon: early in the stream, be more conservative about opening
    // new bins (favor existing bins); late in stream, tightness matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // When many bins are open with slack, discourage spreading items thinly;
    // when mean residual is high, filling an existing bin is cheap.
    if bin_residual != bin_capacity {
        if (mean_residual - bin_residual as f64).abs() < 5.0 {
            score -= 3.0; // this bin is near-average, keep distribution balanced
        }
        if mean_residual > 40.0 {
            score -= 2.0; // plenty of slack overall, prefer existing bins
        }
    } else {
        // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly,
        // but relax the penalty when few bins are open early on.
        score += 15.0 - 10.0 * (1.0 - progress);
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 5.0; // new bin would be roomier than average open bins
        }
    }

    // Slight preference for bins with residual close to item size (best-fit style).
    score += 0.05 * ((bin_residual - item_size) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual (waste), with non-linear polynomial amplification.
    let x = post / cap; // normalized post residual in [0,1]
    let mut score = post * (1.0 + 2.0 * x * x);

    // Smooth stream-progress coupling: waste becomes more costly later in the stream.
    score *= 1.0 + 1.5 * progress * x;

    // Reward tight fits (small post residual) with a super-linear discount.
    score -= 40.0 * (1.0 - x).powi(3);

    // Lookahead coupling: penalize post residuals that neither fit nor nearly fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Next item fits: reward proportional to how snugly it fits.
            score -= 15.0 * (1.0 - (post - nxt) / cap);
        } else {
            // Dead space w.r.t. next item: quadratic penalty scaled by gap.
            let gap = (nxt - post) / cap;
            score += 25.0 * gap * gap * cap;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates smoothly from the mean
    // (keep bin states homogeneous, avoid stragglers) via a smooth quadratic term.
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // (smoothly scaled by item's share of capacity).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * (item / cap);
    }

    // Mild preference for consolidating into fewer bins (avoid opening new bins early).
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into residue classes
    // modulo 10 (typical item granularity). Small residues in the same class as future
    // item sizes are "reusable", large residues above the max item size are dead weight.
    let residue_class = post_residual % 10;
    let class_bucket = post_residual / 10; // integer-division threshold bucket

    // Dead space penalty: leftover that no item (min size 1..100 unknown) can plausibly use.
    // Penalize superlinearly for residues in awkward classes (1, 2, 3 -> hard to fill).
    let awkward = matches!(residue_class, 1 | 2 | 3);
    if awkward {
        score += residue_class as f64 * 1.5;
    }

    // Perfect-fit reward: post_residual exactly 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        // Tiny leftover is nearly a perfect fit; reward proportionally.
        score -= 10.0 - post_residual as f64;
    } else if post_residual > 80 {
        // Large leftover is fine (bin barely used) — mild reward so a fresh-ish bin wins
        // over cramming into a nearly-full bin.
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Reward when the leftover leaves a good harmonic class for the next item.
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 8.0;
            } else {
                score += gap as f64 * 0.2;
            }
        } else {
            // Next item cannot use this bin's leftover; penalize if we also consumed
            // a scarce fitting option.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins are
    // badly fragmented. Compare against mean residual of open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin; reduced when open bins are nearly full on average.
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 12.0 - 10.0 * fragmentation;
        // Early in the stream, new bins are cheap (plenty of future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 5.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below the mean
    // (tighter bins get filled first, keeping looser bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // barely usable, risky
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit, zero waste
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (post_residual as f64 + item_size as f64 + 1.0);
    score -= 25.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 55.0 + 4.0 * open_bins_count as f64;
        // But if mean residual is large and fragmented, opening fresh is fine.
        if mean_residual > 45.0 {
            score -= 40.0;
        }
    }

    // Open-bin pressure: many open bins -> favor filling existing ones.
    score += 0.8 * open_bins_count as f64;

    // Lookahead: if next item fits in post_residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // blocks the next item
    }

    // Late in stream, prioritize consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits here: mild reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize large unusable leftovers.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Reward bins whose residual is small relative to mean residual (tight bins).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great
    // 2-step pairing (e.g., next item pairs perfectly with the current item).
    if bin_residual == bin_capacity {
        let mut penalty = 150.0;
        if next_item_size > 0 && (next_item_size + item_size) as f64 >= bin_capacity as f64 * 0.95 {
            penalty = 20.0; // near-perfect pairing justifies a fresh bin
        }
        score += penalty;
    }

    // Mild late-stream pressure to consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (open_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), with diminishing returns.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize large dead space nonlinearly (unusable gaps).
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-perfect fill bonus
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // awkward gap zone
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_fit = (post_residual - next_item_size) as f64;
        score -= 9.0 * (1.0 - slack_fit / cap);
    } else if next_item_size > 0 {
        // post_residual can't host next item: penalize proportionally to waste.
        score += 4.0 + 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when fits are poor or plentiful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 30.0 - 10.0 * progress - 2.0 * crowding;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
    }

    // Prefer fuller bins relative to fleet mean residual.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild time-decay pressure toward consolidation late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    // Fragmentation penalty scaled by fleet size.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: penalize wasted space, with non-linear shaping over progress.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Smooth polynomial coupling: small residuals are good early, but
    // very small residuals become increasingly valuable as stream progresses.
    let poly = x * x * (1.0 - progress) + x * x * x * progress;
    score += 30.0 * poly;

    // Reward tight fits (small post_residual) increasingly with progress.
    score -= (1.0 - x).powf(2.0 + 2.0 * progress) * (10.0 + 20.0 * progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead: if next item would fit exactly in post_residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) as f64 / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 5.0;
        }
    }

    // Penalize opening new bins when many bins are already open and mean residual is high.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (5.0 + 0.3 * open_bins_count as f64 + 0.1 * mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into dead-space bands.
    // Residuals that form "harmonic" complements (0, 25, 50, 75, 100) are reusable;
    // tiny residuals (1..10) are dead space and heavily penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score += 45.0; // unusable sliver
    } else if pr <= 10 {
        score += 25.0;
    } else if pr <= 20 {
        score += 8.0;
    } else if pr <= 30 {
        score -= 10.0; // fits medium items
    } else if pr <= 50 {
        score -= 15.0; // half-bin class, very reusable
    } else {
        score -= 5.0;
    }

    // Harmonic complement check: does next_item_size exactly match the leftover class?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // guaranteed perfect follow-up
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack <= 10 {
                score -= 22.0; // near-perfect chain
            } else if slack <= 30 {
                score -= 8.0;
            } else {
                score += 3.0; // next item leaves large gap anyway
            }
        } else {
            // next item cannot use this residual: residual value drops if it's small
            if pr < next_item_size && pr < 25 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 3 {
        score += 4.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate logic: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        // penalize new bin mildly; relax penalty when bins are full-ish
        let penalty = 55.0 - 25.0 * crowded - 10.0 * progress;
        // if the item is large, a fresh bin is fine
        if item_size >= 60 {
            score -= 10.0;
        }
        score += penalty.max(5.0);
    } else {
        // Favor fuller bins: tighter fit ratio bonus
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 12.0 * fill;
    }

    // Slight preference for bins below mean residual (balance waste evenly)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the smallest
    // plausible future item are nearly worthless — penalize them heavily.
    let min_item = 10.0f64;
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += 25.0 + (min_item - post_residual as f64) * 3.0;
    }

    // Reward tight fits: the smaller the leftover fraction of capacity, the better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // If the next item fits exactly in the post residual, this placement is excellent.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // Penalize if the next item cannot fit into post_residual but could have fit
    // into a larger leftover (dead space blocking the lookahead item).
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 6.0;
        if post_residual as f64 >= min_item {
            score -= 4.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (discourage new bins and discourage spreading across many bins).
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate (empty bin): make it moderately attractive only when
    // existing fits are bad; otherwise it should lose to decent fits.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.1 * open_bins_count as f64;
        if post_residual as f64 >= min_item {
            score -= 2.0;
        }
    }

    // Prefer bins whose residual is below the mean (fill the emptiest-trending bins
    // less; prefer bins already tighter than average).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    // Late in the stream, be more aggressive about avoiding dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fills this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item fits into post-residual: strongly reward tight chains.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // Reward decreases as leftover slack grows (dead space penalty).
        score -= 25.0 * (1.0 - slack / cap);
    }
    // Next item cannot fit here: mild penalty proportional to unusable residual.
    else if next_item_size > 0 {
        score += 8.0;
    }

    // Penalize residuals that are too small to ever be useful (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when the current item leaves a large,
    // flexible residual and open bins are mostly full.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        let mean_pressure = if cap > 0.0 { mean_residual / cap } else { 0.0 };
        // Reward new bin when item is small-ish and open bins are nearly full.
        score -= 20.0 * fill_ratio * (1.0 - mean_pressure);
        // But discourage opening bins early in the stream or when many are open.
        score += 3.0 * (open_bins_count as f64);
        // If next item would perfectly pair with the empty bin, encourage it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0;
        }
    }

    // Mild normalization: prefer filling bins relative to mean residual state.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for filling a bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post-residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize awkward dead space: residuals that can't hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can fit the next item,
    // penalize if the next item exactly matches the post-residual (chain bonus).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            // Post-residual too small for next item: potential dead space.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // open bins are fragmented (high mean residual) or many bins are open.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score -= fragmentation * 0.5 + pressure * 5.0;
        // Early in the stream, prefer opening bins (more freedom later).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 20.0;
    } else {
        // Penalize placing into bins whose residual deviates badly from mean
        // (keeps a portfolio of useful residual sizes).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Mild penalty for accumulating too many open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // later in the stream, tight fits matter more; early on, keep flexibility.
    let coupling = norm_pr * (1.0 - norm_pr); // peaks at half-empty
    score += 20.0 * coupling * (0.5 - progress) * 2.0;

    // Reward filling bins well as stream progresses (quadratic in progress)
    score -= (item / cap) * (1.0 + progress * progress) * 10.0;

    // Penalize post-residual that cannot fit the next item (dead space), smoothly
    if next > 0.0 {
        let gap = (next - pr).max(0.0) / cap;
        score += 15.0 * gap * gap * cap * (1.0 + progress);
        // Bonus if post-residual exactly accommodates next item
        let snug = (pr - next).abs() / cap;
        score -= 8.0 * (1.0 - snug.min(1.0)) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.3 * open_bins_count as f64 * (0.5 + progress);

    // Pull toward mean residual state: prefer bins whose residual is near average
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: keep it neutral-to-slightly-penalized unless residuals are tight
    if bin_residual == bin_capacity {
        score = 30.0 + 40.0 * progress - 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;

    // --- Harmonic class of post_residual (mod-10 residue classes) ---
    // Residuals that are multiples of 10 are "harmonic" with the item-size
    // universe (1..100): they remain perfectly reusable by small items.
    let residue = post_residual % 10;
    if residue == 0 && post_residual > 0 {
        score -= 8.0; // perfectly harmonic residual
    } else if residue <= 2 {
        score -= 3.0; // near-harmonic, nearly dead space is tiny
    } else if residue >= 8 {
        score -= 4.0; // close to next harmonic level, one small item fixes it
    } else {
        // mid-class residues create awkward dead zones: penalize
        score += (residue as f64 - 5.0).abs() * 1.5;
    }

    // --- Integer-division thresholds on post_residual ---
    let q = post_residual / 10; // number of full "decades" left
    if q == 0 {
        score += 12.0; // residual < 10: bin is essentially dead
    } else if q == 1 {
        score -= 2.0; // one small item slot remains: still useful
    }

    // --- Tight-fit reward ---
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // --- Lookahead coupling (k=2): reward bins that also host next item ---
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - slack * 0.35; // perfect chain fit gets the full bonus
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 6.0; // chained fit also lands on a harmonic class
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot follow here; if next item is large, this bin's
        // leftover is more likely wasted
        if next_item_size > 50 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // --- Mean-residual coupling: prefer bins whose residual tracks the mean
    // (keeps the bin pool homogeneous and flexible) ---
    score -= (mean_residual - pr) * 0.2;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the potential of existing space; make it
        // lose against any decent fit, but let it win late in the stream or
        // when the item is huge (poor fit everywhere anyway).
        score += 6.0 + 25.0 * t + (item_size as f64) * 0.1;
        if open_bins_count == 0 {
            score -= 100.0; // nothing open: always take the fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest conceivable follow-up item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver -> strong penalty
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements where the next item exactly fills the leftover gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    // Penalize if the leftover gap is slightly too small for the next item
    // (near-miss creates dead space for the known future demand).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Tight-fit bonus: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins early,
    // encourage consolidation when many bins are already open.
    score += 0.5 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate handling: only open a new bin if the item is large
    // or existing bins fit poorly (their residuals deviate from item size).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a fresh bin.
        score += 25.0;
        // If many bins fit, opening a new one is wasteful.
        score += 8.0 * (fitting_bins_count as f64).min(5.0);
        // If the mean residual is small relative to the item, existing bins
        // are poor hosts -> opening a new bin becomes more attractive.
        if (item_size as f64) > mean_residual + 5.0 {
            score -= 35.0;
        }
        // Large items prefer fresh bins (avoid fragmentation).
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Mild stream-position coupling: as the stream progresses, prefer
    // keeping dead space low even more strictly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect chain placement).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for near-exact match; decays quadratically.
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64)).powi(6);
        // Extra bonus if next item fits exactly into the leftover space.
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Penalize leftovers the next item cannot use (dead space risk).
            score += 0.15 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    }

    // Penalize post_residual that is small but unusable (dead space trap):
    // leftovers below the minimum item size (1..100 domain) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: placing into a bin whose residual is
    // far below average (tight bin) is good; spreading into fat bins is bad.
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly discouraged unless
    // the item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        score += 5.0 - 0.05 * item_size as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many open bins, discourage opening yet another.
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear term.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize bins that are much emptier than average (bad target for a big item).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would leave this bin nearly dead, mild penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.05 * post_residual as f64;
    }

    // New-bin candidate handling: empty bin should only win when the item is large
    // or no open bin offers a decent fit. Penalize opening new bins early, and
    // penalize more when many bins are already open.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
        let time_pressure = 10.0 * (1.0 - progress);
        score += waste * 0.35 + open_pressure + time_pressure;
        // Large items benefit from a fresh bin.
        if item_size >= 50 {
            score -= 20.0;
        }
        // If next item is small, a fresh bin is less attractive (keep it for big items).
        if next_item_size > 0 && next_item_size <= 20 {
            score += 8.0;
        }
    }

    // Global pressure: with many open bins, discourage spreading items thin.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;

    // Base: normalized post residual
    let mut score = norm_pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 1.5 * progress) - norm_pr * progress * (1.0 - progress) * 0.8;
    score += poly;

    // Reward tight fits more aggressively as the stream progresses (smooth coupling)
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item * (0.6 + 0.9 * progress);

    // Lookahead: penalize leaving residual that matches next item poorly
    if next > 0.0 {
        let match_term = (norm_pr - next / cap).abs();
        score += 0.35 * match_term * (1.0 - progress);
        score -= 0.25 * (1.0 - match_term) * next * progress;
    }

    // Last-chance bin bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.5 + 0.5 * progress;
    }

    // Mild penalty for opening new bins when many bins are open late in stream
    if bin_residual == bin_capacity {
        score += 0.3 * (1.0 - progress) + 0.001 * open_bins_count as f64;
    }

    // Mean residual divergence penalty (smooth quadratic)
    score += 0.15 * (norm_pr - mean_residual / cap) * (norm_pr - mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted

    // Perfect fit: eliminate score entirely.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small post_residual classes (<= 1/8 capacity is prime real estate).
        if post_residual <= bin_capacity / 8 {
            score -= 60.0;
        } else if post_residual <= bin_capacity / 4 {
            score -= 25.0;
        } else if post_residual <= bin_capacity / 2 {
            score += 10.0;
        } else {
            score += 30.0;
        }

        // Modulo classes: residuals that are "nice" multiples align with common item sizes.
        let r = post_residual;
        if r % 10 == 0 {
            score -= 8.0; // divisible by 10: likely reusable by future items
        } else if r % 5 == 0 {
            score -= 4.0;
        } else {
            score += 3.0; // awkward residue class
        }

        // Harmonic pairing: if the lookahead item fits exactly in the post residual,
        // this bin becomes a two-item harmonic cell — strongly reward.
        if next_item_size > 0 && next_item_size == r {
            score -= 200.0;
        } else if next_item_size > 0 && next_item_size <= r {
            score -= 15.0 + (r - next_item_size) as f64 * 0.5;
        }

        // Dead-space quadratic penalty on wasted fraction (convex in waste).
        score += frac * frac * 40.0;

        // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
        // unless the fit is terrible.
        if fitting_bins_count == 1 {
            score -= 45.0;
        }

        // New-bin candidate: penalize mildly so we prefer good existing fits,
        // but allow opening when existing fits are bad (score already high).
        if bin_residual == bin_capacity {
            score += 20.0 + mean_residual * 0.3;
        }

        // Early stream: be slightly conservative with open bins to keep flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 {
            score += 6.0;
        }

        // Crowding: when many bins are open, prefer tightening existing ones.
        if open_bins_count > 4 {
            score -= (open_bins_count.min(20) as f64) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual below the smallest item (1..100 interface, use a soft floor ~10)
    // is essentially wasted capacity.
    let small_gap_floor: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < small_gap_floor {
        score += (small_gap_floor - pr) * 6.0; // dead-space penalty
    }

    // Reward tight fits (post_residual near zero but still usable).
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if pr <= 20.0 {
        score -= 8.0; // compact residual, likely reusable by small items
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins over opening new ones.
    let pressure = open_bins_count as f64;
    if bin_residual != bin_capacity {
        // Existing bin: reward more when bin count is high.
        score -= pressure * 0.5;
    } else {
        // New-bin candidate: penalize proportionally to open bin count,
        // but relax pressure late in the stream or when fits are scarce.
        let mut new_bin_penalty = 12.0 + pressure * 1.2;
        if fitting_bins_count <= 1 {
            new_bin_penalty *= 0.35; // last chance: keep the option alive
        }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty *= 1.0 - 0.4 * progress;
        score += new_bin_penalty;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: the residual risks becoming dead space.
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (filling the emptiest-ish bins keeps mean residual low and tidy).
    let r = bin_residual as f64;
    if r < mean_residual {
        score -= (mean_residual - r) * 0.1;
    } else {
        score += (r - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0; // strong reward for exact lookahead match
        } else if post_residual >= next_item_size {
            // next item still fits: mild reward, closer match is better
            score -= 25.0 - (diff as f64).min(25.0);
        } else {
            // next item cannot fit: penalize unusable dead space
            let waste = post_residual as f64;
            score += waste * 0.5;
        }
    } else {
        // last item: just minimize waste
        score -= 20.0;
    }

    // Penalize bins far below mean residual (they will close soon anyway,
    // prefer to fill them); reward placing into already-dirty bins.
    let res = post_residual as f64;
    if res < mean_residual {
        score += (mean_residual - res) * 0.15;
    } else {
        score -= (res - mean_residual) * 0.05;
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a new bin; reduced when stream is early
        // or many bins open (marginal cost lower), raised late.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + 40.0 * progress - 5.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score += 30.0; // next item needs a fresh bin anyway
        }
    }

    // Tight fits (small post_residual) are good placements generally.
    if post_residual <= 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear tightness reward: quadratic in fill ratio.
        let fill = item_size as f64 / bin_residual as f64;
        score -= 60.0 * fill * fill;

        // Penalize small dead space only if a future item could use it.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // dead space unusable by lookahead
        } else if next_item_size > 0 && post_residual == next_item_size {
            score -= 150.0; // perfect two-item chain
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate: penalize opening a bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64 * 10.0);
        score += 40.0 + 30.0 * (1.0 - crowding) - 20.0 / (1.0 + pressure);
        // If nothing fits well elsewhere, new bin becomes relatively attractive.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && mean_residual < next_item_size as f64 {
            score -= 60.0; // future big item: better to start fresh
        }
    }

    // Mild global waste pressure: prefer bins with residual below mean (consolidate).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Late-stream consolidation: reuse open bins more aggressively near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: post_residual weighted by stream progress
    // (later in stream => tighter packing matters more)
    score += norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Reward tight fits: low post_residual relative to item size gets discount
    let tightness = norm_item / (norm_item + norm_pr + 1e-6);
    score -= tightness * tightness * item_size as f64 * 0.5;

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // mild reward proportional to how well next item uses remaining space
        score -= 10.0 * (next_item_size as f64 / cap) * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize dead space
        score += 5.0 + 10.0 * norm_pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Penalize opening a new bin when plenty of bins with slack exist
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * open_bins_count as f64 * (1.0 - progress);
        // but new bin is fine if all open residuals are tiny compared to item
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        // prefer bins with residual close to mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    // Smooth non-linear interaction of progress and residual
    score += (1.0 - progress) * norm_pr * norm_pr * cap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction classes (dead space becomes progressively worse).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Integer-division harmonic classes on post_residual (mod arithmetic).
    let class = post_residual / (bin_capacity / 10); // classes of size 10
    match class {
        0 => score -= 30.0,               // post_residual < 10: perfect closure
        1 => score -= 18.0,               // tiny leftover, near-closed bin
        2 => score -= 8.0,                // small leftover
        3 => score -= 0.0,                // neutral
        4 => score += 6.0,                // half-empty bin: usable but risky
        5 => score += 10.0,
        _ => score += 4.0,                // large leftover: bin stays flexible
    }

    // Modulo-4 harmonic coupling between post_residual and next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 25.0; // next item exactly fills this bin
        } else if gap > 0 && gap <= 5 {
            score -= 12.0;
        } else if gap < 0 && (-gap) <= 5 {
            score += 15.0; // next item just misses: near-wasted residual
        }
        // Harmonic residue: does next item land in the same mod class?
        let m = 7usize;
        let same_class = (post_residual as usize % m) == (next_item_size as usize % m)
            && next_item_size <= post_residual;
        if same_class {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.5 * (item_size as f64);
    }

    // New-bin candidate: penalize unless current residuals are all bad.
    if bin_residual == bin_capacity {
        let avg_dead = mean_residual / cap;
        let pressure = (step_index as f64) / (total_items.max(1) as f64);
        // Opening a new bin is attractive when open bins are fragmented
        // (low mean residual relative to what this item needs) or late stream.
        let fragmentation = (mean_residual - item_size as f64) / cap;
        score = cap * 0.9
            + 40.0 * (1.0 - pressure)
            - 30.0 * fragmentation.max(0.0)
            + 10.0 * (open_bins_count as f64).sqrt().ln().max(0.0);
        // If item exactly matches a harmonic class boundary, prefer existing bin.
        if item_size % 10 == 0 {
            score += 15.0;
        }
        let _ = avg_dead;
    }

    // Slight preference for tighter fits overall (small post_residual wins).
    score += 0.3 * (1.0 - frac) * 0.0; // keep base linear term dominant
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // (below the minimum plausible item size of 1..20) are heavily penalized.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit: near-zero residual is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward leaving residual that can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64 * 0.3);
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual cannot host the next item: mild penalty proportional to waste.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Tight fit relative to bin_residual: filling most of the bin is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean-residual coupling: bins whose residual is far below the mean
    // (already fragmented) are less attractive targets.
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.8;
    }

    // New-bin candidate handling: opening a fresh bin is attractive when the
    // stream is early or when existing bins are crowded, but penalized by
    // open-bin pressure so we don't proliferate bins.
    if bin_residual == bin_capacity {
        score = 100.0 - (item_size as f64 * 0.4);
        if open_bins_count > 0 {
            score += open_bins_count as f64 * 3.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins that are filled exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits into
    // the post residual (chained packing), scaled by how tight the chain is.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect 2-step chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use leftover space: penalize wasted residual
            score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Penalize creating large dead space relative to mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only bin that can fit, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin, especially early in the
    // stream or when many bins are already open. Only attractive for large items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 150.0 + 50.0 * (open_bins_count as f64) + 100.0 * (1.0 - progress);
        let item_rel = item_size as f64 / bin_capacity as f64;
        score += new_bin_penalty * (1.0 - 0.8 * item_rel);
    }

    // Slight preference for tighter fits among open bins.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 40.0 * fit_ratio;
    } else if fit_ratio > 0.7 {
        score -= 20.0 * fit_ratio;
    }

    // Penalize creating unusable dead space (residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: penalize if the next item cannot fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely into this bin: reward.
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else if next_item_size <= bin_residual {
            // Next item could have fit before this placement: mild penalty.
            score += 8.0;
        }
        // Bonus if post residual exactly accommodates the next item (perfect chain).
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.05 * consolidation * (open_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future amortizes them); late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus progress-dependent penalty.
        score = bin_capacity as f64 * 0.9 + 60.0 * progress;
        // Late in the stream, opening a new bin is expensive.
        if progress > 0.8 {
            score += 50.0 * (progress - 0.8);
        }
        // Early stream with roomy future: cheaper to open a bin.
        if progress < 0.3 {
            score -= 20.0;
        }
        // If no open bin fits well, opening is more attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else if progress > 0.8 {
        // Late stream: strongly prefer filling existing bins.
        score -= 10.0 + 20.0 * (progress - 0.8);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress) - 22.0 * tightness * tightness * (0.5 + progress);

    // Reward near-perfect fills more aggressively late in the stream.
    if pr == 0.0 {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize leaving residuals that no plausible future item can use.
    let nx = next_item_size as f64;
    if nx > 0.0 && pr > 0.0 && pr < nx {
        score += 12.0 + 10.0 * progress;
    } else if nx > 0.0 && pr >= nx {
        // Reward bins that can also fit the lookahead item (smooth coupling).
        score -= 6.0 * (nx / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild pressure against spreading across many bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // Slight bias toward filling existing bins over opening new ones as stream progresses.
    if bin_residual == bin_capacity {
        score += 8.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are "reusable classes" and get rewarded.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -50.0 // perfect fit: strongly reward
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -7.0
    } else if pr % 10 == 0 {
        -5.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize small dead space that nothing (min size 1, but typical small items)
    // can use: very tiny residuals are wasteful unless they're exactly 0.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward heavily.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 10.0 + 0.2 * (pr as f64) - 0.1 * slack;
    } else if next_item_size > 0 && next_item_size > pr {
        // Next item won't fit here; penalize proportional to the overshoot class.
        let over = (next_item_size - pr) as f64;
        score += 0.05 * over;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should win only when no open bin
    // offers a decent fit. Give the empty bin a baseline penalty that shrinks
    // as the stream progresses (early on, opening bins is cheap and useful).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = (item_size as f64) / (bin_capacity as f64);
        // Opening a new bin is penalized more when many bins exist and item is small.
        score += 25.0
            + 10.0 * (1.0 - progress)
            + 20.0 * (1.0 - fit_quality)
            + 0.5 * open_bins_count as f64;
        // But if existing bins would leave terrible residuals (near-full fit is bad),
        // the empty-bin penalty is reduced via mean_residual pressure.
        score -= 0.05 * mean_residual;
    }

    // Mild pressure to keep mean residual low: prefer bins tighter than average.
    score += 0.1 * ((post_residual as f64) - mean_residual);

    // Integer-division threshold: bins whose residual after placement falls into
    // the "large leftover" class (> half capacity) are less urgent to fill now.
    if pr > bin_capacity / 2 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste -> heavy penalty proportional to their uselessness.
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * 40.0;

    // Penalize gaps that are too small for the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Reward using a bin whose residual was already small (tight packing).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over spreading out; scale penalty on new bins via residual term naturally,
    // but add pressure term to discourage opening new bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.1;
    }

    // Mild alignment with mean residual: prefer bins below mean residual
    // (they are the fullest).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Exact-fit reward: item perfectly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead coupling:
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect match: leftover space exactly fits the next item -> strong reward.
        if post_residual as u32 == next_item_size {
            score -= 400.0;
        }
        // Leftover can at least hold the next item: keep residual usable.
        if (post_residual as f64) >= nxt {
            // Reward proportional to how tightly the next item matches the leftover.
            score -= 150.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            // Dead space: leftover too small for the next item -> penalize proportionally.
            score += 60.0 * (1.0 - post_residual as f64 / nxt.max(1.0));
        }
    }

    // Relative-to-mean-residual term: prefer bins tighter than average.
    score += 1.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: penalize opening a new bin mildly, but allow it
    // when existing residuals are all poor fits for this item (post_residual very
    // small relative to the next item's needs) or late in the stream.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 120.0;
        // If the next item is large and this item leaves a good chunk, new bin is fine.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            new_bin_penalty -= 40.0;
        }
        // Early stream: prefer consolidating; late stream: new bins are cheap to open.
        new_bin_penalty *= (1.0 - 0.5 * progress);
        score += new_bin_penalty;
    } else {
        // Mild preference for filling already-open bins tighter than the average.
        score += 0.05 * (1.0 - progress) * (post_residual as f64 - mean_residual).abs();
    }

    // Penalize creating tiny unusable slivers (< 10, assuming min item size floor).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (item_size as f64) * 0.9;

    // Penalize large dead space quadratically to discourage wasting capacity
    score += fit_ratio * fit_ratio * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        let la_fit = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - la_fit / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use leftover; leftover is more likely dead space
        score += fit_ratio * 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    // and mean residual is low (existing bins are well packed already).
    if bin_residual == bin_capacity {
        score += 55.0 + (open_bins_count as f64) * 1.5;
        if mean_residual < 20.0 {
            score += 15.0;
        }
        // But if no open bin fits well (this call would otherwise win anyway),
        // relax penalty late in stream when many bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count > 3 && mean_residual > 30.0 && progress > 0.2 {
            score -= 30.0;
        }
    }

    // Mild preference for bins below mean residual (spread usage evenly)
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Time horizon: early in stream, be conservative (favor tight packing);
    // late in stream, prefer closing out bins (favor bins with small residuals).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: minimize post residual (tight fit preferred)
    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress:
    // early in stream, tolerate loose fits; late, demand tightness.
    let progress_weight = 0.5 + 2.5 * t * t * (3.0 - 2.0 * t); // smoothstep-like ramp
    score += progress_weight * (x * x * (1.0 - x)) * cap;

    // Penalize large residuals non-linearly (dead space grows quadratically)
    score += 0.35 * x * x * cap;

    // Reward near-exact fits with a smooth bump centered at x ~ 0
    score -= 12.0 * (-(pr as f64) / 8.0).powi(2) * -1.0 * (-pr as f64 / 8.0_f64.copysign(1.0)).exp().signum() * (-pr as f64 / 8.0).exp();

    // Lookahead: if next item fits the post-residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / cap).exp();
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - t);
    }

    // Slight preference for filling bins when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual - post_residual) as f64 * 0.02;

    // Mean residual context: penalize bins far below mean residual (wasteful choice)
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: keep it neutral-ish but slightly penalized so real fits win,
    // unless existing fits are terrible (large x late in stream).
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.5 * t) + 0.4 * x * x * cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Harmonic class of post_residual: quarters of capacity.
    let q = (post_residual * 4) / bin_capacity; // 0..3 integer class
    let quarter_bonus = match q {
        0 => 60.0,                    // dead space < 25% capacity is fine
        1 => 10.0,                    // mildly wasteful
        2 => -5.0,                    // half-full residual reusable
        _ => -20.0,                   // large residual, very reusable
    };
    score -= quarter_bonus;

    // Perfect/near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 3 {
        score -= 120.0;
    }

    // Harmonic coupling: does next_item_size fit exactly into post_residual classes?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // next item fits here: reward, more if it fills a harmonic class
            let nq = (next_item_size * 4) / bin_capacity;
            let fill_bonus = match nq {
                0 => 25.0,
                1 => 15.0,
                2 => 30.0,
                _ => 40.0,
            };
            score -= fill_bonus;
            if (post_residual - next_item_size) <= 3 {
                score -= 80.0; // chain of near-perfect fits
            }
        } else {
            // next item cannot use this residual: penalize keeping it open
            score += 15.0 + 0.2 * (nxt - pr);
        }
    } else {
        // last item: prefer tightest fit
        score -= 50.0;
    }

    // Integer-division threshold on residual thirds.
    let third = post_residual / (bin_capacity / 3).max(1);
    if third == 0 {
        score += 5.0; // tiny unusable sliver
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: baseline cost, adjusted by stream progress and load.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 0.3 * mean_residual + 10.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // opening fresh bin helps large upcoming items
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for bins below mean residual (balance spreading).
    score += 0.1 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (unusable by typical items) are heavily penalized.
    // A residual gap is "dead" if it is nonzero but smaller than the minimum plausible item size.
    let dead_zone_threshold = 12.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_zone_threshold {
        score += 60.0 + (dead_zone_threshold - post_residual as f64) * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 80.0;
    } else {
        // Larger usable gaps: mild reward proportional to gap size so big residuals stay attractive,
        // but with diminishing returns to avoid hoarding space in one bin.
        score -= (post_residual as f64).sqrt() * 2.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 50.0; // next item fills this bin perfectly
        } else if (slack as f64) < dead_zone_threshold {
            score += 25.0; // next item would create dead space here
        } else {
            score -= 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate and spread usage).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 30.0 + bin_pressure * 8.0;
    } else {
        score -= bin_pressure * 2.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean, it is a "cramped" bin;
    // filling cramped bins first keeps large residuals available for large future items.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with superlinear penalty on dead space.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Aggressive 2-step lookahead: perfect match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        if diff < 1.0 {
            // Exact match: chain fit, strongly reward.
            score -= 45.0 + 0.5 * pr;
        } else if diff < 10.0 {
            // Near match: graded reward proportional to closeness.
            score -= 30.0 * (1.0 - diff / 10.0);
        } else {
            // Post-residual too small for next item: dead space risk.
            if pr < nxt {
                score += 8.0 * (1.0 - pr / nxt);
            } else {
                // Post-residual much larger than next item: moderate waste penalty.
                score += 0.08 * (pr - nxt);
            }
        }
    }

    // Coupling with mean residual: bins far below mean residual are "spongy";
    // prefer filling them to consolidate waste.
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score -= 0.10 * dev;
    } else {
        score += 0.05 * (-dev);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // the best available fit is very loose.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = pr / bin_capacity as f64;
        // New bin is fine early or when item is large (small post_residual).
        score = 30.0 * (1.0 - progress) + 60.0 * tightness * (1.0 - progress) + 15.0 * tightness;
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let diff = (pr - nxt).abs();
            if diff < 5.0 {
                score -= 20.0;
            }
        }
    }

    // Slight preference to use more crowded bins when many are open.
    if open_bins_count > 4 {
        score -= 0.4 * (open_bins_count.min(20) as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward bins whose post-residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Extra reward if post-residual fits next item almost exactly.
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / (bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the fullest (lowest post_residual already does this).
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, be conservative (avoid fragmenting bins);
    // late in the stream, close out bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tight;

    // Global state: if many bins are open relative to progress, prefer filling existing ones.
    if open_bins_count > 1 {
        let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
        score += 3.0 * pressure * (1.0 - tight);
    }

    // Mean residual coupling: penalize bins far below the mean residual (they are outliers);
    // prefer bins whose residual is close to the mean to keep the pool uniform.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: a fresh empty bin should only win when no open bin
    // offers a decent fit. Penalize it proportionally to how much capacity it would waste.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 40.0;
        // If the item is large relative to capacity, a new bin is less wasteful.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // If no other bins fit (this is effectively the only option), reduce the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, opening a fresh bin is cheaper.
        score -= 15.0 * progress;
        // If mean residual across open bins is very low (all bins nearly full),
        // opening a new bin is justified.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // If next item is huge and this item is small, better to keep item with existing bins.
        if next_item_size > bin_capacity / 2 && item_size < bin_capacity / 4 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Polynomial shaping of residual: penalize large residuals increasingly,
    // but the strength of the penalty grows with stream progress.
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += poly * cap * (0.5 + 2.0 * progress) * 0.8;

    // Smooth interaction: small post-residual is good (tight fit); reward quadratically,
    // reward decays as stream progresses (less need to be picky late? actually more).
    let tightness = (item_size as f64 / bin_residual as f64).clamp(0.0, 1.0);
    score -= tightness * tightness * cap * (0.3 + 0.7 * progress);

    // Lookahead coupling: if next item fits the post-residual, reward smoothly.
    if next_item_size > 0 {
        let fits_next = (post_residual as f64 - next_item_size as f64) / cap;
        if fits_next >= 0.0 {
            let smooth = 1.0 - (fits_next * std::f64::consts::PI).cos();
            score -= smooth * 6.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + 0.5 * progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mean residual context: prefer bins whose residual is below mean (tighter bins),
    // smoothly scaled.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 4.0;

    // New-bin candidate: keep it neutral-to-slightly-attractive early, penalize later.
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.4 * progress) + 8.0 * progress;
        if fitting_bins_count >= 1 {
            score += 6.0 + 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual mod capacity-fraction buckets
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth; // 0..=8 class index

    // Reward small post_residual strongly (non-linear)
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Harmonic bonus: post_residual divisible by common item sizes => usable later
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 5.0; }
        // Perfect match with lookahead item
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
            if post_residual == next_item_size { score -= 20.0; }
            // harmonic pairing: post_residual % next_item_size small
            score -= 6.0 * ((post_residual % next_item_size.max(1)) as f64) / (next_item_size as f64);
        } else if next_item_size > post_residual {
            // lookahead cannot use this residual: penalize proportionally
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Dead-space penalty: residual in awkward class (1..quarter) is nearly unusable
    if post_residual > 0 && post_residual < quarter {
        score += 12.0;
        if post_residual < eighth { score += 8.0; }
    }

    // Integer-division threshold on residual classes
    match post_class {
        0 => score -= 10.0,           // empty/zero residual: perfect closure
        1 => score += 6.0,            // tiny unusable sliver
        2 | 3 => score -= 2.0,        // small but sometimes usable
        4 | 5 => score -= 4.0,        // mid residual, good
        6 | 7 => score -= 6.0,        // large residual, very reusable
        _ => {}                       // near-full bin class
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer closing bins tighter (high fill fraction)
    if open_bins_count > 4 {
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * fill;
    }

    // Late in stream: consolidate, penalize leaving large residuals across bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual as f64 * 0.0 == 0.0 && fitting_bins_count <= 1
                && item_size as f64 > 0.6 * bin_capacity as f64);
        if bad_fit {
            score -= 18.0;
        } else {
            score += 10.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps that cannot fit even the smallest plausible item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 45.0 + 2.5 * (10 - post_residual) as f64;
    } else if post_residual < 20 {
        // Gaps 10..19 are only usable by small items; moderate penalty.
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual that exactly matches the lookahead item (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap that can still serve the next item is less dead.
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones
    // (penalize new-bin candidate and discourage spreading).
    let bin_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to number of open bins.
        score += 20.0 + 1.5 * bin_pressure;
    } else {
        score -= 0.5 * bin_pressure;
    }

    // Early in the stream, be slightly more willing to open bins (keep flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins with below-average residual (tighter bins) to keep large gaps open.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strong reward
        if post_residual == next_item_size {
            score -= 25.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item fits: reward proportional to tightness
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted potential
            score += 6.0 + 0.3 * diff;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Penalize creating tiny unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // New-bin candidate: mildly discourage unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        score += 10.0 - 0.2 * mean_residual;
    }

    // Late in stream: consolidate, prefer existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (fitting_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit bonus: reward placements leaving small residuals.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // existing fits are very poor (fit_ratio low) or many bins already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so an open bin with decent fit beats a new bin.
        let mut penalty = 25.0;
        // If the item fits badly everywhere (fit_ratio small) or nothing else
        // fits (fitting_bins_count == 0 means only new-bin candidate), relax penalty.
        if fit_ratio < 0.55 {
            penalty -= 20.0 * (0.55 - fit_ratio);
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            penalty -= (next_item_size as f64 - 50.0) * 0.3;
        }
        // Late in the stream, prefer closing out existing bins.
        penalty += 10.0 * progress;
        score += penalty.max(0.0);
    } else {
        // Penalize leaving residuals that no typical item can use later
        // (dead space below the smallest possible complement).
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
        // Mild reward for keeping mean residual balanced (avoid many near-empty bins).
        if (bin_residual as f64 - mean_residual).abs() < 15.0 {
            score -= 3.0;
        }
        // Lookahead synergy: if next item fits exactly into post_residual, reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 15.0;
        }
        // If next item cannot fit post_residual but this bin was scarce, small bonus.
        if next_item_size > post_residual && fitting_bins_count <= 2 {
            score -= 4.0;
        }
    }

    // Slight global pressure: with many open bins, discourage spreading.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (minimize wasted residual aggressively).
    // Late: residual matters less; favor consolidation.
    let t = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score = score * (1.0 - 0.5 * t) + 0.5 * t * (pr * pr / cap);

    // Penalize post_residual that cannot fit the next item (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (pr - nxt).max(0.0);
        let unusable = if pr < nxt { 1.0 } else { 0.0 };
        score += unusable * (nxt * 0.6) + waste * waste / cap * 0.3;
    }

    // Reward scarce fitting opportunities (last-chance bin).
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Slight bonus for bins tighter than average (good fits).
    let tightness = (mean_residual - bin_residual as f64).max(0.0);
    score -= tightness * 0.15;

    // Mild pressure to open new bins when many bins are open and residual is large.
    score += (open_bins_count as f64).sqrt() * (pr / cap) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Dead-space penalty: residuals in "waste" classes (odd, non-multiples of 10)
    // are hard to fill later, since items are often multiples of 10.
    if pr % 10 == 0 {
        score -= 12.0; // perfectly aligned residual -> very reusable
    } else if pr % 5 == 0 {
        score -= 4.0;
    } else {
        score += (pr % 5) as f64 * 1.5; // odd classes are dead space
    }

    // Integer-division thresholds on post_residual: classify residual size bands.
    let band = pr / 20; // 0..=5
    score -= match band {
        0 => 20.0,               // post_residual < 20: bin nearly closed, great
        1 => 10.0,               // 20..40
        2 => 3.0,                // 40..60
        3 => 0.0,                // 60..80
        _ => -2.0,               // large residual (only for new-bin candidate)
    };

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let nxt = next_item_size as f64;
            // reward proportional to how well next item harmonizes with residual
            let harmony = if (pr - next_item_size) % 10 == 0 { 6.0 } else { 0.0 };
            score -= harmony + (nxt / cap) * 8.0 * (prf / cap);
        } else {
            // next item won't fit here: slight penalty if residual is mid-sized
            if pr >= 20 && pr < 50 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a base opening cost that shrinks
    // as the stream progresses (committing to open bins early is fine; late in the
    // stream prefer consolidating into open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * progress;
        // opening a bin is attractive if open bins are mostly full (low mean residual)
        score += mean_residual * 0.15;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Favor bins whose residual is below the mean (tighter bins fill faster)
        score += ((prf - mean_residual) * 0.08).max(-6.0).min(6.0);
    }

    // Mild pressure to reduce number of open bins when many are open.
    score += open_bins_count as f64 * 0.02;

    // Small tie-breaker: prefer placing larger items into tighter bins.
    score -= (item_size as f64 / cap) * (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let dead_zone = 10.0f64;
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += 40.0 + (dead_zone - post_residual as f64) * 6.0;
    }

    // Non-linear reward for very tight fits (post_residual near zero).
    score -= 25.0 * (-post_residual as f64 / 8.0).exp();

    // Penalize leaving a residual just above a common item size that would
    // otherwise create a future dead gap: encourage either filling fully or
    // leaving a comfortably large residual.
    let r = post_residual as f64;
    if r > 0.0 && r <= 20.0 {
        score += (20.0 - r) * 1.5;
    }

    // If this bin is the only fitting bin, strongly prefer using it over
    // opening a new bin (last-chance bonus).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // and encourage consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure,
        // but relax slightly late in the stream.
        score += 20.0 + pressure * 2.0;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins whose residual is already below the mean (compact bins),
    // spreading usage toward fuller bins.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Lookahead coupling: if the next item could fit exactly into the
    // post_residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; mildly penalize leaving a residual
        // slightly below the next item (near-miss waste).
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 && gap > -10.0 {
            score += (-gap) * 1.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (small post_residual), with a slight quadratic push.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Aggressive 2-step lookahead: reward when the next item exactly fills this bin's residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            // Perfect match for the lookahead item: strong reward.
            score -= 60.0;
        } else if next_item_size as u32 <= post_residual {
            // Next item fits here too: mild reward proportional to match quality.
            score -= 12.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize leaving dead space.
            score += 6.0 * (diff as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: purely minimize post_residual.
        score -= 10.0;
    }

    // Relative to mean residual: bins with less-than-average residual are closer to being closed;
    // prefer filling them, penalize dumping into already-large-residual bins.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else. Penalize the empty-bin candidate by default.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the new bin would leave a residual that exactly matches the next item,
        // opening it is genuinely useful (e.g. paired packing).
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 70.0;
        }
        // Late in the stream, avoid spawning bins with big residuals.
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 3 {
        score += 0.5 * (open_bins_count as f64 - 3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling: tightness reward grows with stream progress.
    let tight = (1.0 - x).powi(3);
    score -= tight * (30.0 + 50.0 * progress);

    // Penalize large dead space superlinearly.
    score += x * x * 20.0;

    // Reward near-exact fits (post_residual small relative to capacity).
    score -= (1.0 - x).powi(6) * 25.0;

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0 + 15.0 * (1.0 - x);
        } else {
            score += 8.0;
        }
    }

    // Mild penalty for spreading across many bins when residuals are large.
    score += (open_bins_count as f64).sqrt() * mean_residual * 0.02;

    // New-bin candidate: prefer it only when residuals elsewhere are large.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.15 * mean_residual - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fits are golden,
    // residues in "useful" harmonic bands are rewarded, awkward slivers penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Integer-division harmonic classes on post_residual (classes of 10).
        let harmonic_class = post_residual / 10; // 0..=9
        match harmonic_class {
            0 => score += 25.0,          // sliver < 10: dead space
            1 => score += 8.0,           // 10..19: only tiny items fit
            2 | 3 => score -= 6.0,       // 20..39: decent medium pocket
            4 | 5 => score -= 12.0,      // 40..59: very reusable
            6 | 7 => score -= 4.0,       // 60..79: large-item pocket
            _ => score += 2.0,           // 80..99: nearly empty bin
        }

        // Modulo-5 arithmetic: residues divisible by 5 align with typical item sizes.
        if post_residual % 5 == 0 {
            score -= 3.0;
        }
        // Odd residues fragment more with even-sized items.
        if post_residual % 2 == 1 {
            score += 2.0;
        }
    }

    // Lookahead coupling: reward leaving exactly room for the next item (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size as f64;
            if slack <= 10.0 {
                score -= 10.0; // next item fits snugly, minimal waste after
            }
        } else {
            // next item cannot follow here; residual is terminal unless tiny items come.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a
    // reasonable fit (residual tight) or stream is early and consolidation pays off.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = (fitting_bins_count == 0) as f64;
        let item_fraction = item_size as f64 / cap;
        // Base penalty keeps new bins from winning trivially.
        score += 15.0;
        // Open a new bin for very large items that would leave tiny slivers elsewhere.
        if item_fraction > 0.6 {
            score -= 10.0;
        }
        // Early stream: opening bins is cheap; late stream: consolidate hard.
        score -= (1.0 - progress) * 12.0;
        // If literally no open bin fits, new bin is the only option.
        score -= poor_fits * 50.0;
        // If many bins fit, discourage proliferation.
        score += (fitting_bins_count as f64) * 4.0;
    }

    // Mean-residual coupling: prefer bins near the mean (keeps fleet balanced),
    // penalize outliers that create fragmented extremes.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference for tighter bins overall (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (nonlinearly).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Penalize residuals in the awkward mid-range (11..30) that rarely fit
    // future items but waste capacity.
    let pr = post_residual as f64;
    if pr >= dead_threshold && pr < 30.0 {
        score += (30.0 - pr) * 0.8;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open bins pressure: penalize opening/spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this placement; if next item would be stranded by a tiny gap,
    // penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (pr - nxt) / 100.0);
        } else if pr > 0.0 && pr < nxt {
            score += 5.0;
        }
    }

    // Mild mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps bin pool balanced), penalize outliers.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.3;

    // Stream progression: early on, be more tolerant of spreading;
    // late in stream, tighten packing to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.5 * progress);

    // New-bin candidate: make it moderately attractive only when it enables
    // a clean start, otherwise keep it unattractive vs. good fits.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match of post_residual with next item is highly desirable
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step fit
        } else if post_residual >= next_item_size {
            // next item can also fit here; reward proportionally to tightness
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover space -> penalize dead space
            score += 10.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: leaving space near the mean keeps flexibility
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize tiny unusable leftovers (fragmentation)
    if pr > 0.0 && pr < 10.0 {
        score += 15.0;
    }

    // Prefer filling existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress; // new-bin candidate penalty
    }

    // Bonus for tight fits (low post_residual relative to capacity)
    score -= 0.2 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual relative to item size)
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= (1.0 - tightness.min(1.0)) * 20.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize bins whose residual is far above the mean (unbalanced usage)
    score += 0.5 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item can use this bin's post-residual, reward it
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Extra reward if next item nearly fills the bin afterward
            let future_waste = post_residual - next_item_size;
            if future_waste < 10 {
                score -= 10.0;
            }
        } else {
            // Dead space the next item cannot use
            score += 8.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless few fitting bins exist
    // or the stream is early and we have room to amortize a fresh bin
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let amortization = 1.0 - progress;
        let pressure = (fitting_bins_count as f64).recip();
        let base = 60.0 - 30.0 * amortization - 35.0 * pressure;
        // If the best possible use of an existing bin is poor (huge post-residual),
        // opening fresh becomes attractive: compare against current waste
        let waste_now = post_residual as f64;
        let new_bin_appeal = base + waste_now * 0.3;
        score = score.max(0.0) + new_bin_appeal - (score.min(0.0));
    }

    // Mild penalty for accumulating many open bins with scattered residuals
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear waste penalty: convex in normalized residual, grows with stream progress.
    let waste = x * x * (1.0 + 2.0 * progress);
    score += 8.0 * waste;

    // Reward tight fits: smooth sigmoid-like coupling on fill ratio.
    let fill = (item_size as f64) / cap;
    let tightness = (fill * std::f64::consts::PI).sin();
    score -= 6.0 * tightness * (1.0 + 0.5 * progress);

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let coupling = (next_item_size as f64) / cap;
        score -= 4.0 * coupling * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize when next item cannot use the residual (dead space risk).
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 3.0 * gap * gap;
    }

    // Last-chance bonus: only bin that fits — strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (balance residual distribution),
    // smoothly interpolated.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 2.0 * dev * dev - 1.0 * dev;

    // New-bin candidate: penalize opening a new bin mildly, scaled by available fitting bins,
    // but allow it late in the stream when residual spread is wide.
    if bin_residual == bin_capacity {
        let spread = (mean_residual / cap).abs();
        score += 5.0 - 3.0 * spread - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;
    // Class index via integer-division thresholds (classes of 10 units = 10% of capacity).
    let post_class = post_residual / 10;

    // Best-fit core: tighter residual (smaller class) is better.
    score -= 0.5 * (10 - post_class.min(10)) as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic coupling: reward when next item matches the post-residual class exactly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Exact harmonic match: next item fills residual to another class boundary.
        let leftover = post_residual - next_item_size;
        if leftover % 10 == 0 {
            score -= 15.0;
        }
        // Penalize leaving a sliver that nothing small can use.
        if leftover > 0 && leftover < 10 {
            score += 20.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here regardless; slight penalty for wasting the slot.
        score += 8.0;
    }

    // Penalize dead space in fraction terms (non-linear: quadratic in wasted fraction).
    score += 30.0 * post_frac * post_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral baseline, adjusted by stream state.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin early when many open bins have large mean residual,
        // otherwise discourage it (pack existing bins).
        score = 60.0 + 0.3 * mean_residual - (step_index as f64 / total_items.max(1) as f64) * 20.0;
        if post_residual == 0 { score -= 100.0; } // unreachable but keeps uniformity
    }

    // Mild penalty for proliferating bins when mean residual is still high.
    if bin_residual != bin_capacity {
        score += 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1) are unusable only when truly zero; but gaps
    // smaller than the lookahead item are semi-dead space.
    if post_residual > 0 && post_residual < 10 {
        // Tiny unusable slivers: heavy penalty.
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 200.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if the post residual is just barely too small for the
    // next item, penalize (creates near-dead space).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 5 {
            score += 30.0;
        }
    }

    // Tight fit reward relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over spreading; with few bins, opening new ones is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bin fits are very poor.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its post_residual is large, which is
        // naturally good; add a mild opening cost that scales with how many
        // bins are already open.
        score += 25.0 + 1.5 * open_bins_count as f64;
        // If no existing bin fits well (high mean residual spread), new bin
        // becomes relatively better via the pressure term above.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Mild preference for bins below mean residual (rebalance toward fuller bins).
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let pr = post_residual as i64;
        let ni = next_item_size as i64;
        if pr == ni {
            // Perfect chain: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if pr > ni {
            // Next item fits after this one; reward closeness of the eventual leftover.
            let two_step_leftover = (pr - ni) as f64;
            score -= 25.0 * (1.0 - two_step_leftover / bin_capacity as f64);
            // Extra bonus if the two-step leftover is small enough to be "dead-space free".
            if two_step_leftover < 10.0 {
                score -= 10.0;
            }
        } else {
            // Next item will NOT fit: post_residual becomes dead space.
            let waste = (ni - pr) as f64;
            score += 0.6 * waste;
        }
    }

    // Prefer bins whose residual is tighter than the mean (compact placement),
    // penalize bins looser than the mean.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: baseline score so it wins only when all open fits are bad.
    if bin_residual == bin_capacity {
        // Fresh bin: post_residual = capacity - item_size, typically large,
        // but subtract a fixed offset so it beats bins that would create dead space.
        score -= 20.0;
        // Slightly prefer new bins early in the stream.
        score -= 5.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the next item could not use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            score -= 8.0; // perfect lookahead pairing
        } else {
            score -= 0.15 * (post_residual as f64).ln() * (next_item_size as f64 / 50.0);
        }
    } else {
        // Last item: minimize waste absolutely.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many fitting bins -> mild penalty for wasting a scarce residual on this bin.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Prefer bins with residuals below the global mean (conserve large residuals).
    score += 0.25 * (mean_residual - bin_residual as f64).max(0.0);

    // Time horizon: early in stream, be conservative with big-residual bins;
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * fit_ratio;
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            0.0
        } else {
            (fitting_bins_count as f64).ln() + 1.0
        };
        let poor_fits = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score = 55.0 + 10.0 * desperation + 20.0 * poor_fits
            - (if fitting_bins_count == 0 { 60.0 } else { 0.0 })
            + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth interaction: tight fits rewarded more as stream advances
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item (smooth logistic-like gate)
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as i32 as f64;
        let gate = 1.0 / (1.0 + (-(pr - next_item_size as f64)) * 0.1);
        score += 8.0 * (1.0 - fits_next) * gate * (0.6 + progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 * (1.0 + 2.0 * progress);
    }

    // Mild penalty for spreading across many bins late in the stream
    score += 0.15 * open_bins_count as f64 * progress * norm_pr;

    // New-bin candidate: neutral-ish baseline, slightly discouraged early
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: value of residual modulo small divisors captures
    // "nice" leftover sizes that other items can still fill.
    let cap = bin_capacity as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Small post-residuals: reward proportionally (tight packing).
    if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 30.0;
    } else if post_residual <= 30 {
        score -= 15.0;
    }

    // Harmonic class of post_residual: residuals that are multiples of
    // common item granularities (10, 20, 25) are reusable.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 12.0;
    }
    if pr % 20 == 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 {
        score -= 6.0;
    }
    // Odd/prime-ish residuals are dead space.
    if pr % 10 != 0 && pr % 5 != 0 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits the post residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; penalize more when gap is small
            // (wasted near-miss) but slightly less if residual is tiny anyway.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins
    // are fragmented or we're early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if mean_residual > 0.0 { mean_residual / cap } else { 0.0 };
        score += 120.0 - 60.0 * fragmentation - 40.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild preference to fill fuller bins (small residual before placement).
    score += 0.1 * (bin_residual as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1) are fine, but "unusable" gaps (below the
    // practical minimum item size) are pure waste — penalize them hard.
    let dead_threshold: f64 = 10.0; // typical minimum item size
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty on wasted fraction of the bin.
    let waste_frac = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * waste_frac * waste_frac;

    // Reward tight fits strongly.
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    score -= 30.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += 3.0 * (open_bins_count as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would NOT fit, mild penalty for creating a stranded gap.
    if next_item_size > post_residual && post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * (open_bins_count as f64);
        // If no existing bin fits well, allow opening (offset some penalty).
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Stream progression: as stream advances, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match bonus: next item fits with small slack left over.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 2.0;
    }
    // Penalize residuals too small for the next item (dead space likely).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0;
    }

    // Tight fits are good: small post_residual (but not zero-dead-space ambiguity).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 100.0; // big item coming soon: fresh bin useful
        }
    }

    // Prefer bins below mean residual (fill emptier bins first keeps flexibility).
    score += (post_residual as f64 - mean_residual) * 1.5;

    // Late in the stream, close out bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 30.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream (0..1).
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement: higher fill -> better.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 60.0;
        } else if next_fit_gap <= 10 {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - next_fit_gap as f64 / bin_capacity as f64);
        }
    }
    // If next item cannot fit in the residual, penalize leaving large dead space,
    // more so late in the stream when closing bins out matters.
    if next_item_size > post_residual {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * dead * (0.5 + progress);
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Prefer bins with lower residual among ties (best-fit flavor), scaled by
    // how tight the fit is relative to the item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Global state coupling: when many bins are open and mean residual is high,
    // encourage consolidating into existing bins rather than opening new ones.
    let consolidation = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    if bin_residual < bin_capacity {
        score -= 8.0 * consolidation;
    }

    // New-bin candidate handling: empty bin (residual == capacity). Opening a
    // new bin is only attractive if no existing bin fits well (large post
    // residual waste) or the stream is early and future flexibility matters.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when fits are poor.
        score += 35.0;
        // Early stream: slightly favor keeping options open.
        score -= 25.0 * (1.0 - progress);
        // If many bins are open with slack, discourage yet another bin.
        score += 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // If the item is large relative to capacity, a fresh bin is more natural.
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Mild time-horizon term: late in the stream, prioritize minimizing
    // immediate residual (greedy best-fit) even more.
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;                       // normalized post residual
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post residual (tight fit).
    let mut score = pr;

    // Non-linear polynomial coupling of residual with stream progress:
    // early in stream, tolerate larger residuals slightly; late in stream,
    // strongly penalize wasted space (dead space matters more at the end).
    let poly = x * x * (1.0 - t) + x * x * x * t;
    score += 60.0 * poly;

    // Smooth interaction: reward filling bins when few fitting bins remain
    // (last-chance bin) using a smooth saturating term instead of piecewise.
    let fit_term = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 25.0 * fit_term * (1.0 - x) * (1.0 + t);

    // Reward bins whose residual is near the next item size (lookahead fit),
    // smoothly, using a quadratic kernel centered at next_item_size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let d = (pr - nx) / cap;
        score -= 15.0 * (1.0 - 4.0 * d * d).max(0.0);
    }

    // Slight penalty when this bin's residual is far above mean residual
    // (keeps bin residuals homogeneous, smooth coupling with progress).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (0.5 + t);

    // Mild penalty for proliferating open bins late in the stream.
    score += 0.5 * (open_bins_count as f64).ln() * (0.5 + t);

    // New-bin candidate: empty bin gets a moderate score so it wins only
    // when no open bin offers a good fit (its pr = cap -> x = 1).
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: integer-division thresholds on capacity fractions.
    // Class 0: post == 0 (perfect fit) -> strong reward.
    // Class 1: post in 1..=10 (tiny dead space, likely reusable by small items).
    // Class 2: post in 11..=25 (moderately wasteful).
    // Class 3: post in 26..=50 (half-empty, still flexible).
    // Class 4: post > 50 (large residual, keep open).
    let class: u32 = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 25 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    match class {
        0 => { score -= 60.0; }
        1 => { score -= 25.0; }
        2 => { score += 18.0; }
        3 => { score -= 6.0; }
        _ => { score -= 12.0; }
    }

    // Modulo-10 harmonic of post_residual: residuals that are multiples of 10
    // align with common item-size granularity -> more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain of perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Harmonic class of the slack after the lookahead placement.
            if slack == 0.0 {
                score -= 40.0;
            } else if slack <= 10.0 {
                score -= 15.0;
            } else if slack <= 25.0 {
                score += 5.0;
            } else {
                score -= 3.0;
            }
        } else {
            // Next item cannot use this residual -> penalize wasting a good residual.
            if post_residual >= 40 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all too fragmented (high mean residual spread with poor fits).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins early (plenty of stream left to fill them),
        // penalize later when bins would go underfilled.
        let new_bin_bias = 40.0 - 70.0 * progress;
        // If item is large relative to capacity, a fresh bin is fine.
        let size_frac = item_size as f64 / cap;
        score = new_bin_bias + (1.0 - size_frac) * 30.0;
        // If many bins are open and mean residual is large, avoid adding more.
        score += (open_bins_count as f64).ln().max(0.0) * 6.0
               + (mean_residual / cap).max(0.0) * 25.0;
    } else {
        // Mild preference for tighter (fuller) bins: penalize bins with large residual.
        score += (bin_residual as f64 / cap) * 5.0;
    }

    // Slight tie-break noise-free harmonic jitter via bin count parity class.
    if (open_bins_count + post_residual as usize) % 2 == 0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below the minimum
    // plausible item size) are the worst outcome -> heavy penalty.
    let dead_threshold = 9.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize leaving a residual that no typical next item can use,
    // especially if the lookahead item won't fit this bin.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0 + 0.15 * post_residual as f64;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Favor bins that can also host the lookahead item.
        score -= 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins,
    // stronger late in the stream.
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when this item would leave
    // a large awkward residual in an existing bin, or few bins fit the item.
    if bin_residual == bin_capacity {
        let awkward = if post_residual >= 1 && post_residual <= 20 { 60.0 } else { 0.0 };
        score += 10.0 + awkward - 4.0 * fitting_bins_count as f64;
    }

    // Slight preference for bins tighter than average (better packing).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly reward tight fits (small post-residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize bins whose residual barely fits the item (wasted large residual on small item).
    let waste = bin_residual as f64 - item_size as f64;
    score += 0.15 * waste;

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leftover after that matters.
            let chain_waste = post_residual as f64 - next_item_size as f64;
            score -= 10.0 - 0.1 * chain_waste;
        } else {
            // Next item won't fit here: mildly penalize leaving a large unusable gap.
            score += 0.1 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Default penalty for opening a new bin; scaled by how many bins already fit.
        let mut penalty = 20.0 + 5.0 * (fitting_bins_count as f64);
        // If the best existing fit would leave a big dead zone, relax the penalty.
        let poor_fit = (bin_residual as f64 - item_size as f64) > 0.0; // meaningless for new bin, use mean residual
        if mean_residual < item_size as f64 {
            penalty -= 15.0; // open bins are too full -> new bin is reasonable
        }
        if poor_fit && fitting_bins_count == 0 {
            penalty = -10.0; // nothing fits anywhere: must open
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 10.0 * progress;
        score += penalty;
    }

    // Crowding: with many open bins, favor filling existing ones (reduce fragmentation).
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio);

    // Global residual pressure: if mean residual is high, prefer bins below mean
    // (drain the emptier bins first to consolidate).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Small bonus for exact fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = post / cap;

    // Base: waste after placement, smoothed with a saturating quadratic so tiny
    // residuals are strongly favored but huge residuals aren't over-punished linearly.
    let mut score = post * (1.0 - 0.5 * fit_frac);

    // Non-linear coupling of waste with stream progress: later in the stream,
    // dead space becomes progressively more costly (bins are sunk cost).
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Perfect / near-perfect fit reward: subtract for leaving almost nothing behind.
    let tightness = (1.0 - fit_frac).max(0.0);
    score -= 12.0 * tightness * tightness * tightness;

    // Coupling with mean residual across open bins: placing into a bin whose
    // residual is below average consolidates space (good), above average
    // fragments space (bad). Smooth signed interaction.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * (1.0 + progress);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin, scaled by how well the item fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * tightness;
    }

    // New-bin candidate (empty bin): penalize mildly so we only open a new bin
    // when no open bin offers a decent fit; penalty decays as stream progresses
    // and open-bin fragmentation grows.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / cap).min(1.0)
        } else {
            0.0
        };
        score += 5.0 + 8.0 * (1.0 - progress) - 6.0 * fragmentation;
    }

    // Lookahead synergy: if the next item could exactly fill this bin's
    // post-residual, reward heavily; if next item can't use the leftover at all,
    // penalize proportionally to leftover size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() <= 1.0 {
            score -= 10.0;
        } else if nxt > post {
            score += 0.02 * post * (1.0 + progress);
        } else {
            let reuse = nxt / post.max(1.0);
            score -= 5.0 * reuse * reuse;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "coarse" residue classes (multiples of large divisors) are more likely
    // to absorb future items, so reward them.
    let cap = bin_capacity as f64;

    // Fractional fill of the bin after placement.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    score -= 12.0 * fill_frac * fill_frac; // reward tight packing quadratically

    // Harmonic (divisibility) classes of post_residual:
    // leftover divisible by 10 is a "harmonic" slot; divisible by 25/50 even better.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 3.0;
            if pr % 50 == 0 {
                score -= 3.0;
            } else if pr % 25 == 0 {
                score -= 2.0;
            }
        }
        // Dead-space penalty: leftovers in awkward small bands (1..10, 11..19)
        // rarely fit future items of size >= 10 in the classic regime, but with
        // unknown distributions small leftovers are risky — penalize smoothly.
        if pr < 10 {
            score += 6.0 * (10 - pr) as f64 / 10.0;
        } else if pr < 20 {
            score += 1.5;
        }
    } else {
        // Perfect closure: strongly reward exact fills.
        score -= 15.0;
    }

    // Integer-division thresholds on next_item_size: does the lookahead item
    // fit into the post residual? If yes, big reward (chained placement).
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0;
            // Extra bonus if post residual is in a harmonic class matching lookahead.
            if pr % 10 == 0 && next_item_size % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // Lookahead won't fit here: penalize proportionally to the overshoot.
            let over = (next_item_size - pr) as f64;
            score += 0.25 * over;
        }
    } else {
        // Last item: prefer closing bins tightly.
        score -= 4.0 * fill_frac;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins
    // are all nearly full or the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        score = 20.0 - 10.0 * pressure.min(1.0);
        // Late in the stream, avoid spawning bins with tiny expected leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 3.0 * progress;
    }

    // Mild penalty for bin proliferation: keep scores of open bins lower when
    // many bins are open (encourage consolidation).
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0);
    }

    // Small harmonic tiebreaker on residual modulo classes to break ties
    // deterministically toward rounder leftovers.
    score -= 0.05 * ((pr % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any item
    // (sizes >= 1, but practically tiny gaps < 8 are near-useless) are heavily penalized.
    if post_residual > 0 && post_residual < 8 {
        score += 60.0;
    } else if post_residual >= 8 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin_residual (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 8 {
            score += 20.0; // would create new dead space for the next item
        } else if post_residual < next_item_size && post_residual < 8 {
            score += 10.0; // dead space confirmed unusable by lookahead
        }
    }

    // Open-bin pressure: discourage spreading across many bins late in the stream,
    // encouraging consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., already well-filled bins) to concentrate fill.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 8.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 8.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 55.0 + 20.0 * progress;
        // But if the item is huge, a fresh bin is actually reasonable.
        if item_size > bin_capacity * 3 / 4 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: residual after placement exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits with a little slack: mild reward proportional to closeness.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack * 0.08);
    }
    // Next item will NOT fit here: penalize leaving a dead residual that is too small
    // for the next item (wasted space from lookahead perspective).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.35;
    }

    // Tight fit now (small post_residual) is generally good, unless lookahead mismatch.
    if post_residual <= 5 {
        score -= 8.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins whose residual is close to the mean (keeps bin population balanced),
    // but avoid placing into bins far above mean residual (large holes).
    let dev = post_residual as f64 - mean_residual;
    score += 0.10 * dev.abs();

    // Early in stream: be slightly more willing to open/use bins flexibly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    // New empty bin candidate: penalize it mildly so it's only chosen when
    // open bins fit poorly (large lookahead mismatch or no good fit).
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if the next item is large and current fits are bad, new bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size && item_size >= 60 {
            score -= 20.0;
        }
    }

    // Slight penalty for many open bins to discourage bin proliferation.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty scaled down
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 2.0 * fit_ratio * fit_ratio * (bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item would exactly fill post-residual, extra reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }

    // Penalize leaving very small dead space that nothing (>=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Time horizon: early in stream, be more conservative about filling bins (favor spreading);
    // late in stream, favor compact packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - fit_ratio);

    // Global state: many open bins with high mean residual -> prefer reusing bins
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score -= 8.0;
    }
    // Few open bins -> slight preference to open new bins for large items
    if open_bins_count <= 2 && item_size > 50 && bin_residual == bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: mild penalty so it's chosen only when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let shape = 1.0 + 0.8 * progress * (1.0 - progress) * 4.0;
    score = norm_pr * cap * shape;
    // Penalize large leftover that no typical item can use (quadratic dead-space term)
    score += 0.35 * norm_pr * norm_pr * cap;
    // Reward tight fits (small post_residual) increasingly as stream progresses
    score -= (1.0 - norm_pr).powi(3) * (12.0 + 20.0 * progress);
    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 25.0 * progress;
    }
    // Lookahead: if next item exactly fills the post-residual, reward heavily
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // post_residual too small for next item: mild penalty scaled by waste
        score += 0.15 * pr * (1.0 - progress);
    }
    // Coupling with mean residual: prefer bins near the mean (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;
    // New-bin candidate: keep neutral baseline, penalize slightly less late in stream
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: how "usable" is the leftover space?
    // Residuals that are multiples of common item sizes (or large enough) are valuable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fill
    } else if pr % 10 == 0 {
        -8.0 // round residual, likely reusable by common sizes
    } else if pr % 5 == 0 {
        -4.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize small dead space that nothing can use (below min item size 1..10 band)
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Fractional capacity coupling: prefer bins whose post_residual fraction
    // matches a "harmonic" bucket (1/4, 1/2, 3/4 of capacity)
    let frac = post_residual as f64 / cap;
    if (frac - 0.25).abs() < 0.03 || (frac - 0.5).abs() < 0.03 || (frac - 0.75).abs() < 0.03 {
        score -= 5.0;
    }

    // Integer-division threshold on post_residual: chunks of 25
    let chunk = pr / 25;
    score -= chunk as f64 * 2.0; // bigger usable chunks are better

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty for wasting this bin's future
            score += 3.0;
        }
        // modulo coupling between next item and post residual
        if pr > 0 && next_item_size % pr.min(50).max(1) == 0 {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only open a new bin when existing fits are terrible
    if bin_residual == bin_capacity {
        let bad_existing = mean_residual < item_size as f64 * 0.6 && fitting_bins_count == 0;
        if bad_existing {
            score -= 10.0;
        } else {
            score += 12.0; // prefer filling existing bins by default
        }
    }

    // Tightness reward: item filling most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 6.0;

    // Stream progression: later in the stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64).abs() * 0.05;

    // Mean residual coupling: penalize adding to bins far from mean (fragmentation)
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Modulo arithmetic on item size class (harmonic classes of items)
    let item_class = item_size / 10;
    let resid_class = pr / 10;
    if item_class == resid_class && pr >= item_size {
        score -= 3.0; // same decade class: natural companion
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are effectively wasted capacity.
    let min_item = 1u32;
    if post_residual < min_item {
        // exact fit: perfect, reward strongly
        score -= 40.0;
    } else if post_residual <= 10 {
        // tiny unusable gap -> heavy penalty
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 35 {
        score += 8.0;
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading across bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.6 + 0.8 * progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier worth closing out.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.4 * dev;
    } else {
        score += 0.2 * (-dev);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item would be blocked by this placement, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 10.0;
        }
    }

    // New-bin candidate: neutral baseline with mild penalty so we only open a
    // new bin when no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins where the item exactly fills the residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits exactly into the post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportionally to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack.min(200.0);
        } else {
            // Next item would NOT fit: penalize leaving a residual smaller than next item.
            let waste = (next_item_size - post_residual) as f64;
            score += waste.min(100.0) * 1.5;
        }
    }

    // Penalize dead space: residuals too small to ever hold a minimum item (assume >=1,
    // but small residuals under ~10 are likely waste for typical distributions).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are already tight;
    // prefer filling tight bins rather than spreading across loose ones.
    score += (mean_residual - bin_residual as f64).abs() * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it if this bin would otherwise leave a big awkward residual.
    if bin_residual == bin_capacity {
        let base_penalty = 120.0;
        // Early in stream, be more willing to open bins (spread risk).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = base_penalty + (1.0 - progress) * 40.0;
        // If next item is large and current item small, opening a fresh bin is fine.
        if next_item_size > item_size * 2 {
            score -= 60.0;
        }
    }

    // Slight preference for bins with more residual used relative to capacity (tight packing).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // Mild penalty per open bin count to encourage consolidation late in the stream.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream: later on, tighten up.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits, more strongly as stream progresses.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * (2.0 + 3.0 * progress);

    // Penalize small dead space that nothing can use (wasted wedge).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress * 0.5);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // Lookahead coupling: if next item fits in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // If next item cannot fit anywhere after this placement, penalize waste.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0 * progress;
    }

    // Prefer bins with residuals below the mean (consolidate small gaps),
    // scaled by how many bins are open.
    let gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += gap * (1.0 + 0.1 * open_bins_count as f64);

    // New-bin candidate: only attractive when current bins are very fragmented
    // or nothing fits well; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64 - 0.5).max(0.0);
        let penalty = 30.0 + 20.0 * (1.0 - progress) - 25.0 * fragmentation;
        score += penalty.max(5.0);
        // Early stream: opening bins is fine (spread load).
        score -= 15.0 * (1.0 - progress);
    }

    // Mild preference for bins whose residual is close to item size.
    let closeness = 1.0 - ((bin_residual as f64 - item_size as f64) / bin_capacity as f64);
    score -= closeness * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual == bin_capacity) && (item_size <= bin_capacity);

    // Base: quadratic penalty on wasted space, weighted by stream progress
    let mut score = pr * (1.0 + 0.015 * pr) * (0.7 + 0.6 * progress);

    // Smooth interaction: tight fits rewarded more as stream progresses
    let tightness = 1.0 - pr / cap; // 1 = perfect fit
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Fragmentation risk: small post-residual that can't hold typical next item
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let unusable = ((nx - pr) / cap).max(0.0).min(1.0);
        score += 8.0 * unusable * (1.0 + progress);
        // Bonus if post_residual exactly accommodates lookahead item
        let gap = (pr - nx).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0 * (1.0 + progress);
    }

    // Many open bins: prefer consolidation (penalize spreading)
    score += 0.4 * open_bins_count as f64 * (pr / cap);

    // Mean-residual coupling: placing into a bin far below mean residual wastes slack
    let dev = (mean_residual - pr) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize mildly early, increasingly late (closing out bins)
    if is_new_bin {
        score += 15.0 * (1.0 - progress) * (1.0 - progress) + 3.0;
        // But if item is large and would leave tiny residual elsewhere, new bin ok
        score -= 10.0 * (it / cap) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: reward post_residuals divisible by common item granularities.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 5.0; }
        else { score += 4.0; }
        // Dead-space penalty: tiny unusable remainders
        if pr < 10 { score += 25.0; }
    } else {
        // Perfect fill is ideal
        score -= 40.0;
    }

    // Quotient-class coupling: post_residual / next_item_size alignment
    if next_item_size > 0 && pr >= next_item_size {
        if pr % next_item_size == 0 { score -= 8.0; }
        else {
            let r = pr % next_item_size;
            if r < 10 { score += 6.0; } // leaves sliver after next item
            else { score -= 3.0; }
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot use this bin's remainder: penalize proportionally
        score += (next_item_size - pr) as f64 * 0.3;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 { score -= 15.0; }

    // Prefer bins below mean residual (tighter packing) early; conserve bins late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 - mean_residual) * (0.15 - 0.1 * progress);

    // New-bin candidate: only attractive when current bin would waste a lot
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score = waste + 10.0;
        if fitting_bins_count <= 1 { score -= 20.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (1..=9) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 3.0 * post_residual as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual was already small (tight packing).
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // If this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Lookahead: post residual can't hold next item but residual could have — penalize.
    if next_item_size > post_residual && next_item_size <= bin_residual && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, favor new bin
    // only when fit is poor; encourage using open bins when few are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.4 * (1.0 - progress);

    // New-bin candidate: keep it attractive only when the item is large relative
    // to mean residual (poor fit elsewhere), otherwise push it down.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) > mean_residual + 5.0;
        if poor_fit {
            score -= 15.0 + 0.2 * open_bins_count as f64;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is excellent
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 40.0 * (1.0 - slack as f64 / bin_capacity as f64);
            if slack == 0 {
                score -= 500.0; // perfect 2-chain
            }
        } else {
            // next item won't fit here; penalize leaving large awkward gaps
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize dead space relative to mean residual (creating worse-than-average gap)
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin good for chaining
        }
    }

    // Late in stream: consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (open_bins_count as f64 / (1.0 + mean_residual / 10.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post-residual non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (-6.0 * tightness).exp();

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // sliver waste
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (-slack / 20.0).exp();
        } else {
            // next item cannot follow here: mild penalty proportional to overflow
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (1.0 - (-over / 30.0).exp());
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing ones.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.4 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: when open bins are slack-rich, prefer the bin
    // whose residual is closest to the item (best-fit style).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: only attractive early in the stream, or when no
    // open bin fits well, or when item is large relative to capacity.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut newbin_score = 40.0 * (1.0 - t);           // cheaper early
        newbin_score += 30.0 * item_frac;                  // big items deserve fresh bins
        if fitting_bins_count == 0 {
            newbin_score -= 100.0;                         // must open a bin
        }
        if post_residual < 15 {
            newbin_score += 20.0;                          // would leave a sliver
        }
        score = newbin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Base: penalize wasted residual, superlinearly
    let mut score = post * (1.0 + 0.8 * post_norm * post_norm);

    // Smooth polynomial coupling with stream progress: late in the stream,
    // tolerate larger residuals less (dead space matters more)
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 30.0 * prog_poly * post_norm;

    // Reward tight fits (small post_residual) with a smooth inverse term
    score -= (cap / (post + 1.0)) * (1.0 - prog_poly) * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item could use this post-residual, reward keeping it open
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let tightness = 1.0 - (post - nxt) / cap;
            score -= 15.0 * tightness * tightness;
        } else {
            score += 5.0 * ((nxt - post) / cap);
        }
    }

    // Mean residual coupling: avoid bins far from the mean residual (smooth penalty)
    let dev = (post - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Mild penalty for proliferating bins early
    score += (open_bins_count as f64) * (1.0 - prog_poly) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: post_residual mod 10 defines
    // "dead-space classes". Residuals that are multiples of 10 (or small
    // residuals likely to be filled by future items) are more reusable.
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => 12.0,
        5 => 6.0,
        1 | 9 => 2.0,
        2 | 8 => 0.0,
        3 | 7 => -2.0,
        _ => -4.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: post_residual bucketed by capacity fraction.
    let quarter = bin_capacity / 4;
    if post_residual < quarter / 2 {
        // Tiny dead space: strongly penalize unless this is the last fitting bin.
        if fitting_bins_count > 1 {
            score += 8.0;
        } else {
            score -= 10.0; // last chance bin, use it even if tight
        }
    } else if post_residual <= quarter {
        score -= 3.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 5.0; // half-filled bins are flexible
    }

    // Lookahead coupling: does next item fit exactly or well in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect follow-up fit
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 10.0; // harmonic chain continues
            } else {
                score -= (slack as f64) * 0.15;
            }
        } else {
            // Next item won't fit here anyway; mild penalty for tight residuals.
            if post_residual < next_item_size / 2 {
                score += 4.0;
            }
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is good when current item leaves a large,
        // awkwardly-classed residual in existing bins or few bins fit.
        let awkward = (post_residual % 10 != 0) as f64 * 6.0;
        score += 20.0 + awkward + (open_bins_count as f64) * 1.5;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // If only this bin fits, never open a new one.
        if fitting_bins_count <= 1 {
            score += 60.0;
        }
    } else {
        // Reward using nearly-full bins (tight packing pressure).
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= fill * 6.0;
        // When many bins fit the item, prefer the tightest (post_residual already
        // does that); when few fit, extra reward to avoid opening bins.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it's an
    // outlier worth filling; if far above, deprioritize slightly.
    let dev = (bin_residual as f64) - mean_residual;
    score -= dev * 0.05;

    // Small global pressure: more open bins => stronger urge to fill existing ones.
    score -= (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Medium gaps that likely cannot fit future items (items >= 10).
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward bins whose residual after placement can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Pressure from number of open bins: discourage spreading when many bins open,
    // but encourage using existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor
    // (large post_residual relative to capacity) or item is huge.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score += 30.0; // base penalty for opening a new bin
        if fit_quality < 0.35 || item_size >= 70 {
            score -= 45.0; // new bin is good when remaining gap would be dead space
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0; // existing bins are nearly full anyway
        }
    }

    // Slight preference for fuller bins (smaller bin_residual) as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (10.0 + 10.0 * progress);

    // Prefer bins below mean residual fullness (relatively full bins).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect match => huge reward; decays with gap.
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).powf(3.0);
    }

    // Penalize dead space that no plausible item (>=1) can use... i.e. very small leftovers are fine,
    // but mid-range leftovers that next item cannot use are wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0; // creates fragmentation relative to lookahead
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for opening new bins early in the stream when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin: baseline at capacity; bonus early, penalty when few bins fit item.
        score -= 15.0 * (1.0 - progress);
        if fitting_bins_count > 3 {
            score += 20.0; // prefer reusing when plenty of options
        }
    }

    // Small tie-break: prefer bins whose residual is an exact multiple relationship with common sizes.
    if post_residual % 10 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a nonlinear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use:
    // residuals below the minimum item size are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect closure is excellent
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item cannot use this bin's remainder; mild penalty for
            // locking space the lookahead would have wanted elsewhere.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate logic: an empty bin should only win when existing bins
    // are poor fits. Penalize opening a new bin when good alternatives exist.
    if bin_residual == bin_capacity {
        let waste_pressure = (bin_capacity - item_size) as f64;
        // Base cost of a fresh bin: its leftover space.
        score = waste_pressure;
        // If few bins fit the item, opening a new bin is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Many open bins with low mean residual -> reuse is cheap; discourage new bin.
        if open_bins_count > 0 && mean_residual < item_size as f64 + 5.0 {
            score += 10.0;
        }
        // Big items leave big holes in fresh bins; slightly discourage.
        score += (item_size as f64) * 0.1;
    }

    // Mild preference for filling bins that are already mostly full,
    // keeping many mid-size residuals available for future items.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * fill_ratio;

    // Spread management: if mean residual across bins is high, prefer placing
    // into below-average-residual bins to consolidate space.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post residual (tight fit), non-linearly scaled
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Smooth polynomial coupling with stream progress: early on, tolerate
    // slack slightly more (bins can be filled later); late, demand tight fits.
    let progress_coupling = 1.0 - 0.5 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Reward tight fits: small post_residual relative to item size
    let tightness = 1.0 - post / (bin_residual.max(1) as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: if next item fits exactly (or well) into post_residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * next_fit * next_fit;
    } else if next_item_size > post_residual {
        // Dead space that next item cannot use: penalize, growing with progress
        score += 8.0 * progress * norm_post;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins
    // are fragmented (high mean residual) or many bins already open.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 8.0)) * progress;
        score = cap * (1.0 - 0.3 * fragmentation - 0.2 * pressure);
        // If it's a last resort (no other fitting bins), new bin must be chosen
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues near "usable" sizes
    // (multiples of small denominators of capacity) are more valuable.
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => -12.0,                       // perfectly harmonic residual
        1 | 9 => -6.0,
        2 | 8 => -3.0,
        3 | 7 => 0.0,
        4 | 6 => 2.0,
        _ => 5.0,                          // 5: half-capacity dead zone
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: small residuals are dead space.
    if post_residual <= 5 {
        score -= 15.0; // near-perfect fill, strongly reward
    } else if post_residual < 10 {
        score -= 8.0;
    } else if post_residual > 60 {
        score += 10.0; // leaving a huge residual wastes the bin
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // this placement is excellent (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let chain_class = (post_residual - next_item_size) % 10;
            if chain_class == 0 { score -= 10.0; } else { score += 3.0; }
        } else {
            // next item won't fit here; residual becomes terminal -> penalize
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Progress-based scaling: early in the stream, be frugal with open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, allow late when mean residual is fragmented.
        score += 30.0 * (1.0 - progress) + 10.0;
        if mean_residual > 40.0 && progress > 0.5 {
            score -= 15.0;
        }
    } else {
        // Reward filling existing bins, more so as stream progresses.
        score -= progress * 10.0;
    }

    // Congestion coupling: many open bins with low mean residual -> consolidate.
    if open_bins_count > 8 && mean_residual < 25.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..100 range, so gaps < ~10 are near-dead)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize small-but-usable gaps that are unlikely to fit typical items.
    if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize if next item cannot fit here (would leave dead-ish space).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across too many bins,
    // but a last-chance bin (fitting_bins_count == 1) gets a discount
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: penalize opening a new bin unless current bin
    // would leave a large unusable gap.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Slight preference for bins tighter than the mean residual (better fit).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Progression: early in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into post_residual: reward proportional closeness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize unusable remainder
        let waste = (next_item_size - post_residual) as f64;
        score += 0.5 * waste;
    }

    // Penalize very small post_residual (unusable dead space)
    if post_residual < 10 {
        score += 40.0;
    }

    // Relative to mean residual: prefer bins already tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is poor
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && post_residual >= item_size + next_item_size {
            score -= 20.0; // fresh bin can host both items
        }
    }

    // Early in stream: be slightly more willing to open bins for flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 12.0 * tightness;

    // Penalize dead space: residuals that no future item (min size 1..100) can plausibly fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // even better: next item nearly fills remaining space
            let chain_tight = next_item_size as f64 / (post_residual.max(1) as f64);
            score -= 10.0 * chain_tight;
        } else {
            // next item won't fit here: slight penalty for wasting capacity reservation
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins where this item is a better relative fit
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins, more so with many open bins
        // and when mean residual suggests existing bins have room
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score += 20.0 + 6.0 * crowding + 10.0 * (mean_residual / bin_capacity as f64);
        // late in the stream, opening new bins is even worse
        score += 15.0 * progress;
        // but if mean residual is tiny, existing bins are nearly full: soften penalty
        score -= 12.0 * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));
    } else {
        // Fitting into an existing bin is generally good
        score -= 4.0;
        // reward keeping mean residual balanced: avoid creating extreme residuals
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Early stream: slightly prefer larger residual bins for flexibility
    let early_bias = 1.0 - progress;
    score += 3.0 * early_bias * (post_residual as f64 / bin_capacity as f64);

    // Prefer fuller bins overall (best-fit flavor scaled)
    score += 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]
    let it = item_size as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post-residual with stream progress:
    // early on, prefer tight fills (low post residual); later, weight dead space more heavily.
    let w = 1.0 + 2.0 * progress * progress;
    score += w * 40.0 * pr * pr;

    // Reward near-perfect fits with a smooth quartic trough around pr = 0.
    score -= 25.0 * (1.0 - pr).powi(4) * (0.5 + 0.5 * progress);

    // Penalize residuals that cannot fit the lookahead item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - post).max(0.0) / cap;
        score += 18.0 * gap * gap;
        // Reward residual that comfortably fits the next item (smooth coupling).
        let slack = (post - nxt).max(0.0) / cap;
        score -= 10.0 * slack * (1.0 - slack) * (1.0 - progress);
    }

    // Last-chance bin: smooth bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr);
    }

    // Mild penalty when this bin's residual deviates from the mean residual (fragmentation control).
    score += 0.05 * (post - mean_residual).abs();

    // Slight preference for consolidating into fewer bins as stream progresses.
    score += 0.01 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
