pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no item can use are heavily penalized.
    // Treat post_residual < 10 (minimum plausible item size) as pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Marginal gaps: only usable by very small items; penalize moderately.
        score += 12.0;
    } else {
        // Usable gap: mild reward scaled by gap size (larger usable residual is better).
        score -= 0.15 * (post_residual as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage scattering items across many bins.
    score += 2.5 * (open_bins_count as f64);

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bins have poor fit potential.
    if bin_residual == bin_capacity {
        // Penalize opening new bins when open bins exist and mean residual is healthy.
        score += 30.0 + mean_residual * 0.4;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 8.0;
    }

    // Early stream: be slightly more conservative (keep bins tight for the long run).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer bins that end up tight (small post_residual).
    score = (post_residual as f64) * 1.0;

    // 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // next item still fits: mild reward proportional to how close
            score -= 20.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leftover dead space, worse if tiny
            let waste = pr;
            score += 15.0 * (1.0 - waste / 50.0).max(0.0);
        }
    }

    // Reward filling bins close to capacity (small residual is good already handled,
    // but add non-linear bonus for very tight fits).
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize bins far above mean residual (wasteful bins), favor below-mean usage.
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Default new-bin score is capacity itself; adjust so it's chosen only under pressure.
        score -= 40.0 * pressure;
        score += 10.0 * (1.0 - pressure);
    }

    // Late in the stream: consolidate aggressively into fewest bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that is too small to hold
    // typical future items (>=10) is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty unless this is
            // the only fitting bin.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only open bin that can fit the
    // item, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a fresh bin is only attractive
    // when the item is large relative to capacity or existing bins are
    // fragmented (high mean residual with poor fit).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Prefer new bin when item is big and existing residuals are scattered.
        let new_bin_bias = 45.0
            - 0.35 * item_size as f64
            + 0.10 * fragmentation
            - 12.0 * progress;
        score += new_bin_bias.max(-20.0).min(60.0);
    }

    // Mild pressure to fill existing bins as the stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty proportional to number of open bins to encourage
    // consolidation when many bins are open.
    score += 0.02 * open_bins_count as f64;

    // Small bonus for bins already below mean residual (consolidating
    // small residuals together).
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer tight fits, but weight grows non-linearly with stream progress.
    let mut score = rn * (1.0 + 1.5 * progress * progress);

    // Smooth polynomial coupling: penalize mid-range residuals, reward both very tight
    // and very full (near-zero) residuals via a quartic valley centered at small rn.
    let valley = (rn - 0.15) * (rn - 0.15);
    score += 2.0 * valley * (1.0 - progress) * 0.5 + 3.0 * valley * progress;

    // Dead-space penalty: cubic in residual, amplified when few fitting bins remain.
    let fit_pressure = if fitting_bins_count <= 1 { 1.0 } else { (1.0 / fitting_bins_count as f64).sqrt() };
    score += 0.02 * rn * rn * rn * 100.0 * fit_pressure;

    // Lookahead: smooth reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let gap = (r - next_item_size as f64).abs();
        let gapn = gap / cap;
        score -= (1.0 - gapn).max(0.0) * (1.0 - gapn) * (1.0 + progress);
    }

    // Slight preference for consolidating into existing bins vs opening new ones,
    // stronger late in the stream (smooth coupling with progress).
    if bin_residual == bin_capacity {
        score += 0.5 + 1.0 * progress;
    } else {
        score -= 0.1 * (1.0 - progress);
    }

    // Mean-residual coupling: keep global balance via smooth quadratic term.
    score += 0.05 * (mean_residual - r) * (mean_residual - r) / (cap * cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10 / 25) are more attractive.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -30.0 // perfect fill
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 10 == 0 {
        -8.0
    } else if pr <= 5 {
        15.0 // tiny dead space, nearly perfect but unusable
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division threshold: leftover bucket by fifths of capacity.
    let fifth = bin_capacity / 5;
    let bucket = pr / fifth;
    score += match bucket {
        0 => -6.0,          // <= 20% used leftover: good compact bin
        1 => 0.0,
        2 => 4.0,
        3 => 9.0,
        _ => 14.0,          // mostly empty: bad choice, prefer new bin
    };

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= pr {
        if pr - next_item_size <= 10 {
            score -= 18.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize large leftovers slightly
        score += (pr as f64) * 0.08;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is good when current bins
    // would leave very large leftovers or the item is large.
    if bin_residual == bin_capacity {
        // neutral baseline for fresh bin; competitive when fits are wasteful
        score = 45.0 + (item_size as f64) * 0.15;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 5.0; // next item is big too, fresh bin pairs well
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 10.0; // existing bins are nearly full anyway
        }
    }

    // Mild preference to keep number of open bins bounded early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 - progress) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A residual gap is "dead" if it is too small for the smallest plausible item (<= 10),
    // or too small for the lookahead item when nothing else may use it.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    }
    // Gaps below the next item's size are dead w.r.t. lookahead (if not last item)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 8.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Reward near-perfect fills strongly (waste minimization)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward tight fits relative to bin capacity (small waste fraction)
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 30.0;

    // Open-bin pressure: with many open bins, prefer reusing existing bins,
    // penalize leaving many half-empty bins around.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin (bin_residual == bin_capacity).
    // Opening a new bin is only attractive when the item fits poorly everywhere:
    // i.e., when post_residual in an existing bin would create large dead space.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when justified.
        score += 35.0 + open_bins_count as f64 * 0.5;
        // If the lookahead item is large and this item is large, a fresh bin
        // may pair them well later: soften the penalty.
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 <= bin_capacity as f64 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        score += progress * 15.0;
    }

    // Mean-residual coupling: if open bins are already quite full on average,
    // reusing this bin is valuable; if mean residual is high, spreading is worse.
    if bin_residual != bin_capacity {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

