    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    }
    // Next item cannot use the leftover: penalize dead space proportionally.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize unusable dead space below the minimum item size (1..100 unknown, use conservative threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good fits), penalize loose bins.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Mild bias toward opening new bins early when many bins are open and residual is large.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost so it only wins when open bins are poor fits.
        score += 15.0 + 0.1 * open_bins_count as f64;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 8.0; // this placement blocks the next item's fit
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins relative to the fleet average.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses, but
        // discount the penalty if current bin fits poorly.
        score += 10.0 * (1.0 - 0.6 * progress);
        score += 0.05 * open_bins_count as f64;
    } else {
        score -= 3.0 * progress;
    }

    // Mild preference for bins whose residual stays "usable" (>= 10 or 0).
    if post_residual >= 10 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits, non-linear polynomial in normalized post residual
    let mut score = 2.0 * x * x - 1.5 * x;

    // Smooth coupling with stream progress: early on tolerate slack, later punish it
    let coupling = (0.8 + 1.6 * progress) * x * x;
    score += coupling;

    // Penalize wasted space relative to mean residual (smooth interaction)
    let waste = (pr - mean_residual) / cap;
    score += 0.4 * waste * waste.abs();

    // Lookahead: reward if next item fits the post residual (smooth term)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0) / cap;
        let compat = 1.0 - (fits_next * 4.0).min(1.0);
        score -= 0.9 * compat * compat;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.5;
    } else {
        score += 0.15 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Discourage scattering across too many open bins when slack is large
    score += 0.05 * (open_bins_count as f64) * x * x;

    // New-bin candidate: mild penalty so it only wins when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 1.2 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes
    // Residuals in (0..10) are near-useless "harmonic dead zone" -> heavy penalty
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64 / 10.0;
    }
    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 100.0;
    }
    // Post-residual that exactly accommodates next item: lookahead reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // slack beyond next item's need penalized mildly
            score += 0.15 * (post_residual - next_item_size) as f64;
        }
        // next item's harmonic class: if next item falls in small class, prefer tight fit
        let next_class = next_item_size / 10;
        if next_class <= 2 && post_residual > next_item_size {
            score += 5.0 * (post_residual - next_item_size) as f64;
        }
    }

    // Modulo structure on capacity fractions: prefer residuals that are
    // multiples of common item classes (10, 20, 25, 50)
    let harmonics: [u32; 4] = [10, 20, 25, 50];
    let mut harmonic_bonus = 0.0;
    for h in harmonics.iter() {
        if post_residual % h == 0 && post_residual > 0 {
            harmonic_bonus += 8.0;
        }
    }
    score -= harmonic_bonus;

    // Integer-division threshold: bins with residual in top quartile are "roomy"
    let quartile = bin_capacity / 4;
    if post_residual >= quartile * 3 {
        score -= 10.0; // wasteful to leave huge room? actually favor using roomy bins lightly
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation elsewhere
    if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate: only attractive when item is large or no good fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size >= bin_capacity / 2;
        if large_item {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // keep new-bin option for pairing: neutral-to-penalty
            score += 10.0;
        }
        if fitting_bins_count > 0 && !large_item {
            score += 30.0; // discourage opening new bin when fits exist
        }
        if mean_residual < item_size as f64 && fitting_bins_count == 0 {
            score -= 15.0;
        }
        let _ = progress;
    }

    // Coupling with mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100, min item = 1)
    // are pure waste. Penalize small gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity (low waste ratio).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into fresh bins;
    // favor closing out nearly-empty residual bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins that consolidate space
    // (place into bins with residual below average -> larger bins stay flexible).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // If next item would fit in post-residual, mild reward; otherwise mild penalty
    // for leaving a gap the next item cannot use.
    if next_item_size > 0 {
        if next_item_size < post_residual {
            score -= 4.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin has high raw residual; only make it
    // attractive when current fits are poor (large dead space) or no real bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual > 0 && post_residual < 10 && fitting_bins_count <= 1);
        if poor_fit_elsewhere {
            score -= 18.0;
        } else {
            score += 12.0 + 3.0 * (open_bins_count as f64).min(10.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            score -= 0.5 * next_item_size as f64; // next item fits, good
        } else {
            // next item won't fit here; penalize wasted potential
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare post_residual relative to mean residual: prefer bins that reduce dispersion
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Penalize tiny dead space that no future item (min size 1) can use efficiently
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so open bins are preferred unless fit is bad
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly fit future items.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room exactly for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (-gap / 20.0).exp();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Discourage opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        let pressure = 1.0 / (fitting_bins_count as f64 + 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 * pressure + 8.0 * (1.0 - progress);
        // New bin is attractive only if the item is large relative to mean slack.
        if (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    // Mild penalty for very fragmented global state.
    score += 0.02 * open_bins_count as f64;

    // Slight nudge toward bins with residual close to the mean (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 18.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);
    score -= 14.0 * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Penalize dead space relative to mean residual, coupled quadratically
    let mean_norm = mean_residual / cap;
    score += 6.0 * (norm_pr - mean_norm) * (norm_pr - mean_norm);

    // Reward tight fits via cubic fit term
    score -= 10.0 * fit * fit * fit * (1.0 - norm_pr);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: favor bins whose post-residual can hold next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Mild pressure toward consolidation as stream progresses
    score -= 3.0 * progress * (1.0 - norm_pr);

    // New-bin candidate penalty unless residual is large
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes relative to capacity fractions.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= quarter {
        score -= 60.0;
    } else if post_residual < half {
        score -= 20.0;
    } else {
        // Large residual: dead-space risk, penalize.
        score += 15.0;
    }

    // Harmonic compatibility: can next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly into this bin's remainder.
            score -= 25.0;
            // Extra reward if next item fills remainder nearly exactly.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 120.0;
            } else if gap <= quarter {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here: remainder becomes dead space unless small.
            if post_residual < 10 {
                score -= 10.0; // tiny remainder is fine
            } else {
                score += 20.0;
            }
        }
    } else {
        // Last item: minimize residual.
        score -= 50.0;
    }

    // Modulo-class bonus on post_residual (divisibility structure).
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 12.0; // remainder divisible into future equal items
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer already-open bins over opening a new bin (new-bin candidate has full residual).
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64).sqrt() * 5.0;
    }

    // Late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    } else {
        score -= progress * 10.0;
    }

    // Align with mean residual: bins deviating far below mean are precious.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // A gap is "dead" if no typical item (>= 10) can fit.
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual < 20 {
            score += 15.0;
        } else if post_residual > 60 {
            // Large leftover is fine, keep flexible space.
            score -= 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Lookahead: prefer bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading further.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += pressure;

    // New empty bin: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 18.0 + pressure;
    }

    // Slight progression bias: later in stream, tighter packing preferred.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Near-perfect match: next item fits leaving very little dead space.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 25.0;
    }
    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Relative-to-mean residual coupling: prefer bins tighter than the mean.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual > 30 && next_item_size > post_residual);
        if poor_fit_everywhere {
            score -= 20.0;
        } else {
            score += 60.0;
        }
    }

    // Late in the stream, avoid creating unusable fragments.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits strongly (non-linear)
    score -= 60.0 * fill * fill;

    // Penalize large dead space non-linearly
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * dead * dead;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * (next_item_size as f64);
        // Extra reward if next item exactly fills too
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving space that next item cannot use proportionally to waste
        let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
        score += 0.3 * waste;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many fitting bins: prefer the tightest (already via post_residual); add mild
    // penalty tied to number of alternatives to break ties toward emptier bins
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: penalize opening new bins when mean residual is high
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (20.0 + 0.8 * mean_residual + 5.0 * (open_bins_count as f64).sqrt());

    // Early in stream: mildly discourage new bins less (exploration), late: more
    score += new_bin * (1.0 - progress) * (-15.0);
    score += new_bin * progress * 10.0;

    // Prefer filling nearly-full bins as stream progresses (consolidation pressure)
    score -= fill * 10.0 * progress;

    // Small bonus for using bins with residual close to mean (balanced usage)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Prefer placing large items into emptier bins, small items into fuller bins
    let size_frac = item_size as f64 / bin_capacity as f64;
    score += 5.0 * size_frac * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, non-linearly shaped by stream progress
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth coupling: penalize large residuals more as stream advances
    score += progress * norm_pr * norm_pr * 30.0;

    // Dead-space penalty: residual too small to hold typical small item
    let dead = ((pr - 10.0).max(0.0) / cap).min(1.0);
    score -= 5.0 * (1.0 - dead) * (1.0 - dead);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Mild preference to fill bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 0.5;

    // Diverge from mean residual: prefer bins below mean residual (tighter)
    score += ((mean_residual - pr) / cap) * 1.5;

    // New-bin candidate: keep it neutral-to-slightly-worse unless tight fits exist
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small divisors: classify leftover space.
    let cap = bin_capacity as f64;

    // Reward very tight fits (post_residual in lowest harmonic class).
    if post_residual == 0 {
        score -= 50.0; // perfect pack
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Penalize dead space: post_residual too small for the smallest possible item (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic classes via integer division: post_residual / 10 buckets.
    let class = post_residual / 10;
    score += class as f64 * 4.0;

    // Lookahead: if next item fits exactly or well into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            score -= 15.0 - (nxt_left as f64) * 0.3;
        } else {
            // next item cannot use this leftover: mild penalty scaled by gap
            score += ((next_item_size - post_residual) as f64).min(40.0) * 0.2;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer reusing open bins with decent fits.
        score = cap * 0.55 + post_residual as f64;
        // If many open bins with large mean residual, opening a new bin is wasteful.
        score += open_bins_count as f64 * 2.0;
        // If mean residual is small (bins nearly full), new bin becomes reasonable.
        score -= mean_residual * 0.8;
        // Big items (harmonic class of item_size) justify a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in stream, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer filling fuller bins: penalize bins with more residual relative to mean.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    // Modulo coupling: post_residual divisible by 5 pairs better with future items.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized,
    // since nothing arriving can ever fill them.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual < 20 {
        // medium-risk gap: mild penalty scaled by how likely next item fits
        score += 8.0;
    }

    // Reward tight fits: if the next item exactly matches the post residual,
    // this is a perfect chain — strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // next item still fits: mild reward proportional to remaining slack efficiency
        score -= 6.0 * (post_residual as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // next item cannot use this gap: penalize proportionally to gap size
        score += 3.0 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing
    // bins rather than opening new ones.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + open_pressure;
        // But if the item is huge relative to typical residual, a fresh bin is fine.
        if item_size as f64 > mean_residual + 20.0 {
            score -= 35.0;
        }
    } else {
        // Using an existing bin reduces pressure — reward it.
        score -= open_pressure * 0.5;
    }

    // Prefer bins whose residual is close to mean (balanced packing) early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * (0.4 - 0.3 * progress);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / 50.0).max(-1.0);
        // Perfect lookahead match: strong bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residuals that are too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer filling a bin as much as possible
        score -= 30.0;
    }

    // Compare against mean residual: bins already "loose" are better targets
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.3 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 20.0 * pressure;
        // Early in the stream, opening new bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // If next item is large and this new bin could hold both, slight bonus
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Slight preference for bins with more residual used relative to mean
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Dynamic time horizon: progress through the stream [0, 1]
    let progress = if total_items > 1 {
        (step_index as f64 / (total_items as f64 - 1.0)).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let post = post_residual as f64;
    let mut score = post;

    // 1. Perfect fit: an exactly-closed bin is almost always optimal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2. Dead-zone bump: small nonzero leftovers are likely wasted forever.
    //    The zone widens and the penalty grows late in the stream (less chance to fill).
    let dead_top = 8.0 + 10.0 * progress;
    if post_residual > 0 && post < dead_top {
        score += 14.0 + 12.0 * progress;
    }

    // 3. Lookahead coupling with the next item (k=2).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Reward bins that can also host the next item (chained placement).
            score -= 0.6 * nxt;
            // Double perfect closure: item + next item exactly fill this bin.
            if next_item_size == post_residual {
                score -= 300.0;
            }
        } else {
            // Penalize leaving a residual just below the next item's size
            // ("almost fits" frustration -> risk of stranded space).
            let mut risk = 0.25 * (nxt - post);
            // If the global slack (mean residual) can host the next item,
            // the risk of this leftover being wasted is much lower.
            if mean_residual >= nxt {
                risk *= 0.3;
            }
            score += risk;
        }
    }

    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        if fitting_bins_count == 0 {
            // No open bin can host the item: opening a bin is mandatory.
            score -= 10_000.0;
        } else {
            // Bin proliferation penalty: grows with open bins and stream progress,
            // since late-opened bins leave residue that will never be filled.
            score += open_bins_count as f64 * (1.0 + 3.0 * progress);
            // Late-game new bins with large leftovers are strongly discouraged.
            score += 0.3 * progress * post;
        }
    } else if fitting_bins_count == 1 {
        // Last chance: this is the only open bin that fits the item.
        // Strongly prefer it over opening a new bin (stronger late in the stream).
        score -= 40.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling: reward low post_residual more strongly as stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= 6.0 * tightness * tightness * (progress * progress + 0.2);

    // Penalize large dead space non-linearly, scaled by mean residual context.
    let waste = pr / cap;
    score += 4.0 * waste * waste * waste * (1.0 + mean_residual / cap);

    // Lookahead: reward if next item fits the post residual (chaining potential).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let chain_fit = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 5.0 * chain_fit * (1.0 - progress);
    } else if next_item_size > 0 {
        // smooth penalty when next item cannot chain
        let gap = (next_item_size as f64 - pr) / cap;
        score += 3.0 * gap * gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - waste);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * waste;

    // New-bin candidate: penalize slightly unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

