    // Lookahead: reward a bin whose post_residual exactly hosts next item,
    // or at least can host it; penalize if it leaves next item stranded.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Brand-new bin candidate: neutral-ish baseline; open a fresh bin only
    // when open bins would create badly fragmented (odd-class) leftovers.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= item_size {
            score += 25.0; // discourage wasteful new bin when lookahead fits current item elsewhere
        }
        if post_residual % 10 == 0 {
            score -= 20.0; // fresh bin leaving harmonic-class residue is fine
        }
    }

    // Mild pressure to consolidate as the stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * mean_residual * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
