    // tight fits so future large items have room); late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;
    score += 6.0 * (1.0 - progress) * (1.0 - tightness);

