        let mut new_cost = 55.0;
        if fitting_bins_count == 0 {
            new_cost -= 60.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            new_cost += 20.0; // a last-chance bin exists; keep it
        }
        // Lookahead synergy: a fresh bin can host both current and next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            new_cost -= 10.0;
        }
        score = new_cost + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
