    }

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when mean residual across open bins is large.
    if bin_residual == bin_capacity {
        score += mean_residual * 1.5;
        score += 20.0;
    } else {
        // Slight preference for bins tighter than average (good fits).
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Stream progression: later in the stream, be slightly more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            // Exact or near match with next item's size is highly desirable
            let match_gap = (post_residual as f64 - next).abs();
            score -= 30.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize dead space
            score += 8.0;
        }
    } else {
        // Last item: just minimize waste
        score += post_residual as f64 * 0.5;
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when a decent fit exists
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
    }

    // Late in the stream, tighten packing further
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity as f64 - post_residual as f64) * (0.35 + 0.4 * progress);

    // Penalize creating dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }
    // If next item almost fits, slight penalty for wasting the chance.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) + 5 >= next_item_size {
        score += 4.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize extreme outliers unless they are near-empty.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.08;

    // New-bin candidate handling: empty bin gets a base cost so it is only
    // chosen when placements in open bins would be poor.
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * progress;
        // Opening a new bin is more attractive when few bins fit the item.
        if fitting_bins_count <= 2 {
            score -= 14.0;
        }
        // If the next item is large, keep a fresh bin available.
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        // Mild reward for using already-open bins to consolidate load.
        score -= 3.0;
    }

    // Penalize leaving residuals that no plausible item (>=1) can combine with,
    // scaled by how many open bins exist (fragmentation cost).
    if post_residual > 0 && post_residual < 5 {
        score += 6.0 + (open_bins_count as f64).min(10.0);
    }

    // Late in the stream, tighten packing: reward minimal post residual harder.
    if progress > 0.7 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Base: tight fit preferred, non-linearly shaped
    let mut score = (prn * prn * 3.0 + prn * 2.0) * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream -> more aggressive tightening of acceptable residual
    let prog_coupling = prn * (1.0 - progress) * (0.5 - progress * 0.5);
    score += prog_coupling * cap * 2.0;

    // Reward near-exact fits with a smooth quadratic discount
    let tightness = 1.0 - prn;
    score -= tightness * tightness * cap * 1.5;

    // Penalize residuals that can't fit the lookahead item (smooth)
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let gap = (nr - pr).max(0.0) / cap;
        score += gap * gap * cap * 2.0;
        // reward if lookahead fits exactly into post residual
        let fit_gap = (pr - nr).max(0.0) / cap;
        score -= (1.0 - fit_gap) * (1.0 - fit_gap) * cap * 0.8 * progress;
    } else {
        // last item: strongly prefer minimal residual
        score -= (1.0 - prn) * (1.0 - prn) * cap * 3.0;
    }

    // Last-chance bin bonus (only fitting bin)
    if fitting_bins_count == 1 {
        score -= cap * 0.6;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 1.5;
    }

    // Mild pressure to reuse bins vs opening new ones
    if bin_residual == bin_capacity {
        score += cap * 0.35 + open_bins_count as f64 * 0.8;
        // late stream: prefer opening fresh bins less
        score += progress * cap * 0.4;
    }

    // Mean residual context: bins deviating from mean residual slightly favored
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into buckets
    // of capacity/10. Small classes (0..10) are near-perfect fits -> big reward.
    let class = post_residual / 10;
    let class_bonus = match class {
        0 => 60.0,           // residual < 10: dead space, excellent
        1 => 45.0,
        2 => 32.0,
        3 => 20.0,
        4 => 10.0,
        5 => 0.0,
        6 => -8.0,
        7 => -16.0,
        8 => -24.0,
        _ => -32.0,
    };
    score -= class_bonus;

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are reusable -> reward them.
    let pr = post_residual as i64;
    let mut reuse = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { reuse += 12.0; }
        if pr % 20 == 0 { reuse += 6.0; }
        if pr % 25 == 0 { reuse += 6.0; }
        if pr % 50 == 0 { reuse += 8.0; }
    }
    score -= reuse;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize by how much slack would remain,
            // scaled by harmonic class of that future residual.
            let future = post_residual - next_item_size;
            score -= 10.0 + (future as f64) / 10.0;
            if future % 10 == 0 { score -= 5.0; }
        } else {
            // next item will NOT fit here: this bin becomes dead after us;
            // penalize proportionally to stranded residual.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // would leave large unusable residuals. Fresh bin residual = capacity.
    if bin_residual == bin_capacity {
        // Penalize relative to how fragmented the open bins are.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 55.0 + fragmentation * 0.5;
        // Late in the stream, prefer closing out open bins rather than opening.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Small nudge toward tighter bins overall (best-fit flavor).
    score += (bin_residual as f64) * 0.05;

    // Mean residual coupling: when open bins are on average roomy, slightly
    // prefer using them (reduce score) versus when they are tight.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100 range,
    // assume small items may still arrive, so treat very small gaps as wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Post-residual cannot host the next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: penalize placements that keep many bins open with
    // scattered residuals; encourage consolidating into bins with low residual.
    score += open_bins_count as f64 * 0.8;

    // Favor bins whose residual is below the mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for using existing bins over opening new ones as the
    // stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 40.0 * progress;
    } else {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            // Perfect fit for the next item: strong reward
            score -= 40.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item still fits here: mild reward proportional to closeness
            let slack = post_residual as f64 - next;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally to waste
            let waste = next - post_residual as f64;
            score += 15.0 * (waste / 100.0);
        }
    } else {
        // Last item: just prefer tightest fit
        score += 0.0;
    }

    // Penalize post_residual far above mean residual (wasteful bin)
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.05 * dev;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs() > 0.5 && post_residual < next_item_size
        } else {
            false
        };
        if poor_fit || fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            // Prefer reusing existing bins when a decent fit exists
            score += 25.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tight = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tight * tight;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else if post_residual >= next_item_size {
            score -= 6.0;
        }
    } else {
        // Last item: only absolute tightness matters.
        score = post_residual as f64 - 40.0 * tight;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral score with mild penalty so that
    // opening a new bin only wins when fits into open bins are poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
        // If mean residual across open bins is small, new bin is attractive.
        score -= (mean_residual / 10.0).min(10.0);
    }

    // Mild preference for bins below mean residual (balance avoidance of
    // fragmentation vs. keeping large residual bins for future big items).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Penalize leaving residuals in the awkward 20..40 zone.
    if post_residual >= 20 && post_residual < 40 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fits preferred (post_residual dominates, non-linearly)
    let mut score = (pr / cap).powi(3) * cap;

    // Non-linear coupling of post_residual with stream progress:
    // early on, waste tolerance is higher; late, minimize residual aggressively
    score += (pr / cap) * (pr / cap) * (1.0 - progress) * 20.0;

    // Reward bins whose residual after placement could host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 4.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins far from the mean residual (encourage balanced residual pool)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs().sqrt() * 5.0;

    // New-bin candidate: penalize mildly when open bins exist, more so late in stream
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: near-perfect fit (residual <= 5) -> strong reward.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 12 {
        score -= 12.0;
    } else if post_residual <= 25 {
        score -= 3.0;
    } else if post_residual <= 40 {
        // mid band: mildly penalize wasting half the bin
        score += 4.0;
    } else {
        score += 10.0;
    }

    // Modulo arithmetic: residuals that are multiples of common small item
    // sizes (10, 20, 25) remain "harmonically reusable" -> reward them.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 20 == 0 {
            score -= 4.0;
        }
        if post_residual % 25 == 0 {
            score -= 3.0;
        }
        // Odd, awkward residuals are harder to fill later.
        if post_residual % 2 == 1 && post_residual < 30 {
            score += 2.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = pr - ni;
            if slack <= 10.0 {
                score -= 8.0;
            } else if slack > 40.0 {
                score += 3.0;
            }
        } else {
            // next item cannot follow here; prefer bins whose remainder
            // stays small anyway
            score += 1.0;
        }
        // Harmonic class of next item vs residual via integer division bands
        let next_class = next_item_size / 20; // 0..4 coarse size class
        let resid_class = post_residual / 20;
        if next_class == resid_class && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current bin would leave large dead space or the
    // item is large relative to capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_ratio = item_size as f64 / cap;
        if fill_ratio > 0.6 {
            score -= 8.0; // large items start fresh bins happily
        } else {
            score += 6.0; // small items should go into existing slack
        }
        // Early in the stream, opening bins is cheap; later, prefer packing.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0 - progress * 3.0;
    }

    // Prefer tighter bins overall when mean residual is high (fragmentation risk).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Penalize spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, discourage opening yet another one.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).sqrt() * (1.0 + progress);
    if bin_residual == bin_capacity {
        score += 30.0 + pressure * 5.0;
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to the item need.
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual matching next item exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = pr - nxt;
        if diff == 0.0 {
            // Perfect pair: this bin will be exactly filled by the next item.
            score -= 50.0;
        } else if diff > 0.0 {
            // Next item still fits afterwards; mild reward, closer is better.
            score -= 10.0 * (1.0 - diff / 100.0);
        } else {
            // Next item won't fit in the leftover: penalize unusable dead space.
            score += 8.0 * (-diff) / nxt.max(1.0);
        }
    }

    // Penalize tiny post_residuals that create dead space no small item can use,
    // unless a perfect lookahead match exists (already rewarded above).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: prefer bins with residual near/below the mean
    // (tight packing), penalize dipping into unusually full bins for easy fits.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): neutral-ish baseline so it only wins
    // when all existing fits are poor (large dead space / bad lookahead).
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: tight fit preference (lower post_residual = better).
    let mut score = post_residual as f64;

    // Time horizon: fraction of stream completed.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits: subtract bonus scaled by how close post_residual is to 0.
    let perfect_bonus = (bin_capacity as f64 / 8.0) * (1.0 - post_residual as f64 / bin_capacity as f64).powi(6);
    score -= perfect_bonus;

    // Last-chance bin: strongly favor it to avoid opening a needless new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0 + 20.0 * (1.0 - t);
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement heavily (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64).powi(2);
    } else if next_item_size > post_residual && post_residual < 10 {
        // Dead space too small for the next item: penalize, more so early in the stream.
        score += 12.0 * (1.0 - t) + (10 - post_residual) as f64;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many competing bins but poor fits) or the stream is early.
    if bin_residual == bin_capacity {
        let poor_fits = (fitting_bins_count == 0) as i32;
        // Baseline cost of a new bin; reduced if the item is large (hard to place later).
        let mut new_bin_score = 60.0
            - 15.0 * (item_size as f64 / bin_capacity as f64)
            - 20.0 * poor_fits as f64
            - 10.0 * (1.0 - t);
        // If the mean residual across open bins is large, open bins are wasteful; new bin is fine.
        new_bin_score -= 5.0 * (mean_residual / bin_capacity as f64);
        // Avoid excessive bin proliferation.
        new_bin_score += 2.0 * (open_bins_count as f64).sqrt();
        score = score.max(new_bin_score.min(score)) + 0.0; // keep base comparison fair
        score = new_bin_score.max(score.min(new_bin_score)) + (post_residual as f64 - new_bin_score).min(0.0);
    }

    // Slight penalty when this bin's residual is far above the mean (fragmented bin).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Mild global-load balancing: when many bins are open, prefer filling emptier ones less.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste coupling with stream progress
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Progress-dependent smooth weighting: early stream tolerates slack, late stream punishes it
    let late_bias = 0.5 + 2.0 * progress * progress;
    score += late_bias * norm_pr * cap * 0.5;

    // Penalize residual that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * (0.5 + progress);
        // Reward if next item fits into post-residual smoothly
        let fit_frac = 1.0 - (gap / (next_item_size as f64 + 1.0));
        score -= fit_frac * 8.0 * (1.0 - progress);
    }

    // Last-chance bin bonus: smooth sigmoid-like term on fitting_bins_count
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= scarcity * 15.0 * (0.3 + 0.7 * progress);

    // Coupling with mean residual: prefer bins whose post-residual deviates smoothly from mean
    let dev = (pr - mean_residual) / (cap + 1.0);
    score += dev * dev * 20.0 * (1.0 - progress);

    // Mild reward for using a well-filled bin (small post_residual relative to capacity)
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 5.0;

    // New-bin candidate penalty: opening a bin wastes capacity unless residual is tight everywhere
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / cap);
        score += 12.0 - 10.0 * mean_tightness * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly prefer.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual via integer division thresholds.
    // Residual classes: [0..9] near-perfect, [10..24] good, [25..49] ok, [50+] wasteful.
    let class = post_residual / 25; // 0,1,2,3,4
    score += match class {
        0 => -30.0,
        1 => -10.0,
        2 => 0.0,
        3 => 15.0,
        _ => 40.0,
    };

    // Modulo coupling: residuals divisible by common small sizes are reusable.
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 20 == 0 || r % 25 == 0) {
        score -= 12.0;
    }
    // Odd, prime-ish leftovers are hard to fill: penalize slightly.
    if r > 0 && r % 2 == 1 && r % 5 != 0 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.2;
        } else {
            // Next item cannot use this bin's leftover: leftover is dead space risk.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when all open bins are tight or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (item_size as f64) / (bin_capacity as f64);
        // Prefer existing bins generally; open new bin only for big items late in stream
        // when mean residual is small.
        score += 35.0 - 30.0 * pressure - 20.0 * progress * (1.0 - mean_residual / bin_capacity as f64);
        if open_bins_count == 0 {
            score -= 100.0; // must use a bin
        }
    }

    // Mild preference for tighter (smaller-residual) bins overall.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (dead space), while exact/tight fits are rewarded.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 40.0; // unusable tiny gap => dead space
    } else if post_residual <= 20 {
        score += 15.0; // likely dead space for most items
    } else {
        // Usable residual: mild reward proportional to how well it can host future items
        score -= 5.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Pressure from number of open bins: discourage spreading across many bins,
    // but allow opening a new bin when this bin would create dead space.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it if the fit is decent (no dead space)
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover == 0 {
            score -= 30.0;
        } else if leftover < 10 {
            score += 20.0; // would create new dead space
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when open bins would produce dead space or a poor fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Large items are better in a fresh bin
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Slight alignment with mean residual: prefer bins near the mean (predictable packing)
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain completes: residual fully consumed next step
        } else if post_residual > next_item_size {
            // Next item fits here too; reward proportionally to how tight the chain is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the residual: penalize dead space creation.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }

        // Chain bonus: if both item and next item together fill the bin nearly exactly.
        let two_step_total = item_size + next_item_size;
        if two_step_total == bin_capacity {
            score -= 80.0;
        } else if two_step_total > bin_capacity {
            score += 5.0; // chain cannot complete in this bin
        }
    } else {
        // Last item: minimize residual directly (already base score).
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score -= 0.20 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize creating tiny unusable residuals (< 10) unless it was a perfect chain.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: prefer opening a fresh bin when the current best fit would
    // leave a large awkward residual and the next item is large.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.55;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can host the chain too
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits: must open
        }
        // Open new bin if many open bins are already tight (consolidation phase over).
        if open_bins_count > 0 && mean_residual < 25.0 {
            score -= 8.0;
        }
    }

    // Slight preference to fill earlier bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual is already lower score, amplify it.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize small dead space that few future items can use.
    if post_residual > 0 {
        let usable = (post_residual >= 10) as u32 as f64;
        if usable < 1.0 {
            score += 25.0; // dead space below min item size
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot follow into this bin; mild penalty proportional to waste
            score += 4.0 * (1.0 - (bin_residual as f64 - post_residual as f64) / item_size.max(1) as f64);
        }
    } else {
        // Last item: prefer fullest packing possible.
        score -= 15.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 + 0.05 * (post_residual as f64);
    }

    // Many fitting bins -> can afford to be picky; penalize mediocre fits more.
    if fitting_bins_count > 1 {
        score += 0.15 * (post_residual as f64);
    }

    // Global state coupling: compare bin residual to mean residual.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.03 * diff; // prefer bins with less-than-average residual (tighter bins)

    // Time horizon: early in stream, favor conserving space (open bins cheaply);
    // late in stream, favor filling bins completely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 5.0 + 2.0 * pressure;
        // Late in stream, opening a new bin is cheaper than scattering.
        score -= 8.0 * progress;
    }

    // Slight penalty for proliferation of open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let rn = r / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear polynomial shaping.
    let mut score = r
        + 12.0 * rn * rn * cap
        - 8.0 * rn * rn * rn * cap;

    // Smooth coupling with stream progress: later in stream, punish waste harder.
    score += (progress * progress) * 10.0 * rn * cap;

    // Coupling with mean residual: placing into a bin whose residual deviates
    // from the mean wastes packing flexibility; smooth quadratic penalty.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * cap;

    // Lookahead: if next item fits exactly in post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (r - nxt).abs();
        let fit_gap_n = fit_gap / cap;
        score -= 14.0 * (1.0 - fit_gap_n) * (1.0 - fit_gap_n) * (r / (r + nxt));
    } else {
        // Last item: reward tight packing even more.
        score -= 10.0 * rn * rn * cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mild preference for tighter fits via base term.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Congestion: many open bins -> encourage closing them (favor filling existing).
    let congestion = (open_bins_count as f64).ln().max(0.0);
    score += congestion * 1.5 * rn * cap;

    // New-bin candidate: brand-new empty bin has full residual; penalize opening
    // one unless item is large relative to capacity (smooth, no piecewise cutoff).
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        let waste = 1.0 - size_frac;
        score += 30.0 * waste * waste * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by 10 are "clean" classes.
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.35;

    // Integer division thresholds on post_residual: dead space bands.
    let band = post_residual / 10;
    if band <= 1 {
        score -= 12.0; // tight fit, excellent packing
    } else if band >= 6 {
        score += 6.0; // large unusable gap
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 15.0 - (gap as f64) * 0.5;
        // Perfect harmonic match: next item leaves a multiple-of-10 residual
        if gap % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual {
        // next item can't use this residual: penalize proportionally
        score += 4.0;
    }

    // Capacity fraction coupling: reward filling toward capacity fractions.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 0.5;
        score = 60.0 + 30.0 * progress - if crowded { 25.0 } else { 0.0 };
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin still useful for lookahead
        }
    }

    // Mean residual alignment: prefer bins near the mean residual (balanced packing).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    // Small bonus for using an existing bin as stream matures.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Archetype #167: strict dead-space avoidance + open-bin pressure.
    let mut score = 0.0;

    // Dead-space penalty: small leftovers (<10, min item size) are pure waste.
    // Penalize non-linearly as post_residual shrinks into the "dead zone".
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 + (10 - post_residual) as f64 * 6.0; // tiny gap = worst outcome
        } else if post_residual < 20 {
            score += 12.0 + (20 - post_residual) as f64 * 2.0; // risky gap
        } else {
            // Usable leftover: mild reward proportional to how well it's filled.
            score += post_residual as f64 * 0.35;
        }
    } else {
        score -= 25.0; // perfect fit: strongly favored
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Open-bin pressure: prefer spreading across existing bins, but
    // counterbalance so a new bin is only opened when fits are poor.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish baseline; open a new bin only
    // when placing here would create dead space or the fit is very loose.
    if bin_residual == bin_capacity {
        score = 55.0 - fill * 0.0; // fixed anchor; dead-space terms above won't apply (post_residual = C - item)
        // Allow new bin to win when current-bin placement is wasteful:
        if post_residual < 10 {
            score -= 10.0; // prefer fresh bin over creating a dead gap
        }
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item is large and this placement strands it, slight penalty.
    if next_item_size > post_residual && next_item_size > bin_capacity / 2 && post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mean-residual coupling: when open bins are already loose, discourage
    // adding more slack; when they're tight, tolerate slack.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Late-stream consolidation: near the end, favor filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain match: post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item fits here afterwards: reward closeness
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item would not fit after placement: penalize wasted potential
            score += 10.0 + 0.5 * diff;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize very small dead space creation only mildly; large dead space heavily
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Early in stream: encourage consolidation into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (1.0 - fit_ratio);

    // New empty bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 45.0 + 0.2 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize creating tiny dead space (< ~10) that few future items can use,
    // but only when it is not a perfect closure.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect closure is excellent
    }

    // Lookahead: reward bins whose post_residual can host the next item (chaining),
    // penalize bins where post_residual is just barely too small for next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many items remain (amortization)
        // or when open bins are already congested with large mean residuals.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 45.0;
        new_bin_cost -= 15.0 * progress; // early stream: new bins are cheaper long-term
        // If the current item is large relative to typical residuals, new bin more attractive.
        new_bin_cost -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If mean residual across open bins is small (fragmented), new bin is attractive.
        new_bin_cost -= 0.15 * mean_residual;
        score += new_bin_cost.max(0.0);
    }

    // Mild congestion bonus: spreading across many open bins is fine, but avoid
    // scattering into bins whose residual deviates wildly from the mean (fragmentation).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference for bins with larger residual when item is small (save tight bins).
    if item_size <= 20 && bin_residual < bin_capacity {
        score += 0.2 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 - t) + norm_pr * (t * t);
    score += 12.0 * poly;

    // Penalize large dead space more aggressively as stream progresses
    score += 8.0 * norm_pr * norm_pr * norm_pr * (0.5 + t);

    // Reward tight fits (small post residual) especially when few fitting bins
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    } else {
        score -= 3.0 * (1.0 - norm_pr) / (fitting_bins_count as f64);
    }

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Coupling with mean residual: prefer bins near the mean (balanced usage)
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev * (1.0 + t);

    // Mild penalty for opening a new bin when many bins are open early
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - t) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: 1..=5   (dead space, nearly useless)
    // Class 2: 6..=15  (only tiny items fit)
    // Class 3: 16..=35 (medium items fit)
    // Class 4: 36..=100 (large items still fit)
    let hclass = if post_residual == 0 {
        0
    } else if post_residual <= 5 {
        1
    } else if post_residual <= 15 {
        2
    } else if post_residual <= 35 {
        3
    } else {
        4
    };

    match hclass {
        0 => score -= 60.0,
        1 => score += 25.0, // penalize near-perfect-but-wasted fills
        2 => score += 8.0,
        3 => score -= 5.0,
        _ => {}
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 + slack * 0.15;
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty scaled by how far off we are
        score += ((next_item_size - post_residual) as f64) * 0.1;
    }

    // Modulo-arithmetic coupling: bins whose residual sits on "friendly"
    // capacity fractions (multiples of 10/20) pack better downstream.
    let r = post_residual % 20;
    if r == 0 && post_residual > 0 {
        score -= 4.0;
    } else if r <= 5 {
        score += 3.0;
    }

    // Integer-division threshold: half-full or better after placement is good.
    if post_residual * 2 <= bin_capacity {
        score -= 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 35 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let pressure = if fitting_bins_count > 0 { 0.0 } else { 30.0 };
        score = 100.0 - large_item * 40.0 - pressure
            + (open_bins_count as f64) * 1.5
            + (mean_residual - (bin_capacity as f64 - item_size as f64)).max(0.0) * 0.2;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty when post_residual falls into a
    // "dead zone" too small for typical future items (below the minimum item size
    // or below a safe threshold). These gaps are almost surely wasted.
    if post_residual < 10 {
        score += 200.0; // unusable gap
    } else if post_residual <= 20 {
        score += 60.0; // risky gap: only tiny items fit
    } else if post_residual <= 30 {
        score += 25.0;
    }

    // Reward perfect or near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward it;
    // if next item cannot fit in post_residual, the gap is likely dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size > post_residual {
            score += 15.0;
        } else {
            score -= 10.0;
        }
    }

    // Open-bins pressure: when many bins are open, prefer compacting into
    // existing ones rather than spreading; when few bins are open, tolerate
    // opening/using bins more freely.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using
    // it over opening a new bin (unless post_residual is dead space anyway).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Penalize it mildly so it is only chosen when open bins have bad fits
    // (their dead-space penalties push them above this baseline).
    if bin_residual == bin_capacity {
        score += 45.0 + pressure * 5.0;
    }

    // Progress coupling: later in the stream, waste matters more since fewer
    // chances remain to recover dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    // Prefer bins whose residual is close to the item (tight fit) relative to mean.
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.3;
    score -= (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact/near-exact matches with the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        }
    } else {
        // last item: strongly prefer tight fit
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize dead space relative to stream mean residual
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.35 * dead;
    } else {
        score += 0.15 * dead; // small bonus for tighter-than-average bins
    }

    // Last-chance bin: strongly favor using it over opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer dense packing when many bins are open
    if open_bins_count > 4 {
        score += 0.05 * post_residual as f64;
    }

    // Early stream: be more tolerant of loose fits to keep options open
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * (1.0 - progress);

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, be pickier about waste; later, accept placements.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * (1.0 - progress);

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 0.3 * next_item_size as f64;
        } else if bin_residual >= next_item_size {
            // Next item would fit this bin only if we don't place here — mild penalty.
            score += 8.0;
        }
    }

    // Last-chance bonus: only one bin fits the item, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer tight fits among them (lower post_residual already helps).
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: only open a new bin when no open bin is a decent fit,
    // i.e. when mean residual is small relative to the item.
    if bin_residual == bin_capacity {
        let mean_fit = mean_residual / item_size as f64;
        if mean_fit > 1.2 || fitting_bins_count > 0 {
            score += 100.0; // keep existing bins attractive
        } else {
            score -= 5.0; // allow opening a fresh bin when open bins are too full
        }
    }

    // Prefer bins whose residual is close to the mean (balanced usage) with mild coupling.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress
    let shape = 1.0 + 0.8 * progress - 0.6 * progress * progress;
    score *= shape;

    // Reward tight fits more strongly as stream progresses
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize large wasted residual scaled by item size coupling
    score += 6.0 * norm_pr * norm_item * (1.0 + progress);

    // Last-chance bin bonus (smoothly weighted)
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 15.0 * last_chance * (0.5 + 0.5 * progress);

    // Lookahead: favor bins whose post-residual can fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (0.3 + 0.7 * progress);
        } else {
            score += 5.0 * ((nxt - pr) / cap) * (1.0 - progress);
        }
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure)
    score += 0.05 * (pr - mean_residual).abs();

    // Slight bias against opening new bins when many bins already fit
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Harmonic class logic: classify post_residual into residue classes mod 10.
    // Residuals that are "dead" (too small for the smallest plausible item, <10)
    // are perfect; small but nonzero residuals (1..=9) are dead space -> penalize
    // slightly less than mid-range residuals which invite bad future fits.
    let pr = post_residual;
    let class = (pr % 10) as f64;
    let bucket = (pr / 10) as f64;
    if pr == 0 {
        score -= 25.0; // perfect fill
    } else if pr < 10 {
        score -= 15.0 + class; // unusable dead space is actually good
    } else {
        // Mid-range residuals: reward residuals in "harmonic" classes that
        // pair well with common item sizes (multiples of 10, 20, 25, 50).
        let harmonic_bonus = if pr % 50 == 0 {
            30.0
        } else if pr % 25 == 0 {
            22.0
        } else if pr % 20 == 0 {
            18.0
        } else if pr % 10 == 0 {
            12.0
        } else {
            0.0
        };
        score -= harmonic_bonus;
        // Penalize residuals that are awkward (class in 1..=3 within a mid bucket)
        if class < 4.0 {
            score += 6.0 - 2.0 * class;
        }
        // Larger empty buckets are more flexible; slight reward for big residuals.
        score -= 2.0 * bucket.min(5.0);
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits: strong reward, scaled by how well it pairs.
            let pair_waste = (pr - next_item_size) as f64;
            score -= 20.0 - pair_waste.min(20.0) * 0.5;
            if (next_item_size + pr) % 10 == 0 {
                score -= 8.0; // harmonic pairing to a decade boundary
            }
        } else {
            // Next item won't fit here: penalize, but less if dead space is tiny.
            let dead = pr as f64;
            if dead < 10.0 {
                score += 2.0; // fine, residual was unusable anyway
            } else {
                score += 4.0 + dead * 0.05;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral baseline; only attractive when open
    // bins are very fragmented (high mean residual relative to capacity) or
    // item is large relative to typical residual.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 25.0 * fragmentation + 10.0 * (1.0 - progress);
        if item_size >= 50 {
            score -= 10.0; // large items: fresh bin more acceptable
        }
        if next_item_size > 0 && next_item_size >= item_size && fragmentation > 0.5 {
            score -= 15.0; // big items coming, open bins too full
        }
    }

    // Mild preference to consolidate across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are wasted capacity.
    let dead_threshold = 9u32; // smallest possible item is 1, but typical stream items are larger
    if post_residual > 0 && post_residual < dead_threshold.max(next_item_size.min(20)) {
        score += 25.0 + (dead_threshold as f64 - post_residual as f64) * 2.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit: strongly rewarded
    }

    // Reward tight fits relative to the item being placed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Penalize leaving a gap that exactly wastes capacity for the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0; // lookahead item cannot use this bin afterwards
        } else if post_residual == next_item_size {
            score -= 15.0; // sets up a perfect follow-up placement
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Pressure against accumulating too many open bins: favor consolidating.
    score += (open_bins_count as f64) * 0.6;

    // Slight nudge toward bins whose residual is below the mean (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: allow opening only when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 1 {
            score -= 12.0; // but if no real alternative, opening is acceptable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that exactly matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // Penalize dead space: post_residual too small for the next item (likely wasted)
        if (post_residual as f64) < next_item_size as f64 {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins with residual near mean (balanced packing)
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 60.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // Allow new bin if item is huge relative to mean residual
        if (item_size as f64) > mean_residual {
            score -= 45.0;
        }
    } else {
        // Reward tight fits into existing bins
        score -= 10.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < item_size.min(20) {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // Using this bin would strand a small leftover before the next item.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many fitting bins: prefer the one that leaves the most useful remainder.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global pressure: when many bins are open, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (0.5 + progress);
    score += pressure * 4.0 * fit_ratio;

    // Prefer bins below the mean residual (fill the emptier bins first to
    // consolidate), unless it is a new bin candidate.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        score += 5.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        // New bin: only attractive when the item is large and would leave a
        // well-usable remainder; penalize opening bins for small items.
        score += 20.0 + 0.4 * (bin_capacity - item_size) as f64;
        if item_size <= 20 {
            score += 40.0;
        }
        // Late in the stream, opening new bins is even less attractive.
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild preference for tight fits (pr^2 term). Late: strong
    // preference for tight fits as pr^3 grows, avoiding dead space.
    let prn = pr / cap;
    let poly = prn * prn * (1.0 + 3.0 * progress) + prn * prn * prn * (2.0 + 4.0 * progress);
    score += 12.0 * poly * cap;

    // Reward filling bins deeply, scaled by progress (smooth coupling).
    score -= (item_size as f64 / cap) * (30.0 + 40.0 * progress) * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Penalize bins far below mean residual (fragmentation avoidance),
    // coupled smoothly with progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * (1.0 + progress);

    // Lookahead: reward leaving space that fits the next item (smooth kernel).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_gap = (pr - ns).abs() / cap;
        score += 25.0 * fit_gap * fit_gap * (1.0 + 2.0 * progress);
        // Extra reward if next item fits exactly-ish.
        if pr >= ns {
            score -= 10.0 * (1.0 - fit_gap) * (0.5 + progress);
        }
    }

    // Mild penalty on opening new bins when many bins are open, growing with progress.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress + (open_bins_count as f64).sqrt() * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals divisible by common item sizes (or small) are valuable.
    let pr = post_residual;
    let class = if pr == 0 {
        0.0 // perfect fit, ideal
    } else if pr < 10 {
        1.0 // small dead space, hard to fill but not catastrophic
    } else {
        // harmonic divisibility bonus: count how many "nice" moduli divide pr
        let mut div_bonus = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 { div_bonus += 1.0; }
        }
        // coarse class via integer division thresholds
        let coarse = (pr / 10) as f64;
        coarse - 2.0 * div_bonus
    };
    score += 0.7 * class;

    // Penalize leaving residual that cannot fit the next item when it otherwise could
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // chain placement possible
        } else {
            score += 4.0; // next item likely forces a new bin
        }
    } else {
        score -= 3.0; // last item: just fill anything
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad fits
    if bin_residual == bin_capacity {
        // base penalty so full bins are preferred, modulated by stream progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 14.0 + 6.0 * (1.0 - progress);
        // if item is huge relative to mean residual, opening fresh is less bad
        if (item_size as f64) > mean_residual + 15.0 {
            score -= 10.0;
        }
        if post_residual >= 50 {
            score -= 2.0; // a fresh bin leaves flexible large residual
        }
    }

    // Mild tie-break toward consolidating into fewer bins
    score += 0.05 * open_bins_count as f64;
    // Prefer tighter fits: relative waste penalty
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize heavily when post_residual falls in a "dead zone"
    // (nonzero but unlikely to be usable).
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (1.0 - pr / 12.0); // small unusable gap -> strong penalty
    }

    // Reward tight fits (near-zero post residual) super-linearly.
    if item_size > 0 {
        let tightness = 1.0 - pr / (bin_residual as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 12.0 {
            score -= 30.0 * (1.0 - slack / 12.0);
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        // next item cannot use the leftover -> dead space likely
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins when this bin
    // is a good fit; encourage using existing bins rather than opening new.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let decent = (fitting_bins_count > 0 && mean_residual > item_size as f64 * 1.6) || fitting_bins_count == 0;
        if decent {
            score -= 10.0;
        } else {
            score += 45.0 + 2.0 * open_bins_count as f64;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for bins tighter than the current mean residual.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit now.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins where the leftover exactly hosts the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // leftover can host next item: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space severity
            let waste = (next_item_size - post_residual) as f64;
            score += 1.5 * waste;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is close to the item
    // (tight fit) and penalize bins far above the mean residual (wasteful hoarding).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        // neutral baseline; slightly penalize so real bins win unless they are bad
        score += 20.0;
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += 0.5 * post_residual as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space that nothing can use (min item size 1)
        let dead = post_residual as f64;
        score += (dead / 10.0).powi(2) * 0.5;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 150.0 - (next_waste as f64) * 2.0;
        } else {
            // next item won't fit here; slight penalty for tight fill
            score += 30.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // open new bin if mean residual is small (existing bins nearly full)
        score += 400.0 - fragmentation * 3.0 - mean_residual * 4.0 + progress * 100.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 50.0; // prefer fresh space for large follow-up items
        }
    }

    // Mild preference for fuller bins relative to mean residual
    score -= (bin_residual as f64 - mean_residual) * 1.5;

    // Discourage spreading across too many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    // smooth non-linear polynomial coupling of post_residual with progress
    let mut score = pr * (1.0 + 0.6 * t * t);
    // penalize large leftover more as stream progresses (quartic-ish term)
    score += 40.0 * pr_norm * pr_norm * (0.5 + t);
    // reward tight fits
    score -= 12.0 * (item_size as f64 / bin_residual.max(1) as f64).powi(2);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-gap / 25.0) * (1.0 - t);
    }
    // mild penalty for many open bins
    score += 0.3 * open_bins_count as f64 * (0.5 + 0.5 * t);
    // mean residual alignment
    score += 0.2 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward (harmonic class 0)
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space class: post_residual too small for any future item (min size 1,
    // but items <= 10 are rare in classic streams) -> penalize tiny unusable gaps
    if post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class of post_residual via integer division thresholds
    let post_class = post_residual / 10; // 0..10 classes
    score += post_class as f64 * 3.0;

    // Lookahead compatibility: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
            // modulo coupling: next item leaves a "nice" residual class
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 25.0;
            }
            if next_post < 10 {
                score += 20.0; // would create dead space for the item after
            }
        } else {
            // next item cannot use this bin's remainder: penalize if remainder small
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: neutral-ish score so it's chosen only when
    // all open bins are poor fits (their residuals already inflated above)
    if bin_residual == bin_capacity {
        score += 45.0 + 0.1 * open_bins_count as f64;
    }

    // Prefer bins tighter than the mean (best-fit flavor)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Late in the stream, consolidate: penalize spreading across many bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * progress * 0.5;

    // Modulo-arithmetic harmonic bonus: item + residual sums to a multiple of capacity/2
    if (item_size + post_residual) % 50 == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps 1..=12 are likely wasted).
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Reward post_residuals that can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }
    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }
    // Mild pressure to consolidate into fewer bins.
    score += 0.5 * open_bins_count as f64;
    // Prefer bins with residuals below mean (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);
    // Late in stream: be more conservative, avoid tiny leftovers.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 8.0 * tightness;

    // Aggressive 2-step lookahead: perfect match with next item is a big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // exact two-item fill
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // prefer bins whose leftover after next item is small
            score -= 12.0 * (next_item_size as f64) / (post_residual.max(1) as f64);
            score += 0.05 * slack;
        } else {
            // next item cannot fit here; penalize by the shortfall
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.10 * shortfall;
        }
    } else {
        // last item: minimize leftover as much as possible
        score -= 10.0;
    }

    // Relative to mean residual: bins below mean residual are "dying" bins,
    // prefer filling them to avoid fragmentation.
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 0.05 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral base, slightly discouraged unless it's a
    // genuinely better long-term choice (large item, few fitting bins).
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    // Mild stream-progression pressure: later in the stream, consolidate more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), safe when total_items == 0.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: fraction of the bin consumed by this placement.
    let fill = (item_size as f64) / (bin_capacity as f64);
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);

    // Reward near-perfect fits strongly (best-fit core with non-linear bonus).
    if post_residual <= bin_capacity / 10 {
        score -= 12.0 + 8.0 * tight;
    } else if post_residual <= bin_capacity / 4 {
        score -= 5.0 * tight;
    }

    // Penalize dead space quadratically for large leftovers that few items can use.
    if post_residual > 40 {
        score += 0.15 * ((post_residual - 40) as f64).powi(2) / 100.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // Reward when the next item leaves a still-usable residual chain.
            let chain = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - chain / (bin_capacity as f64));
        } else {
            // Next item cannot follow into this residual: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap.min(50.0);
        }
    } else {
        // Last item: strongly prefer filling bins as tightly as possible.
        score -= 10.0 * tight;
    }

    // Last-chance bin: if this is the only bin that can fit the item, reward using it
    // to avoid opening a new bin, especially later in the stream.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // Many open bins with high mean residual: encourage consolidating into bins
    // whose residual is below the mean (tighter bins) to keep others mergeable.
    if open_bins_count > 0 {
        let rel = (bin_residual as f64) - mean_residual;
        score += 0.03 * rel;
        // Congestion pressure: with many open bins, discourage marginal fits.
        let congestion = (open_bins_count as f64).ln().max(0.0);
        score += 0.5 * congestion * (1.0 - tight);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; shrink over time so late stream
        // favors packing into existing bins, but allow fresh bins early or when
        // no open bin fits well.
        let mut open_cost = 18.0 - 10.0 * progress;
        // If the item is small and existing bins are fragmented, opening is cheap.
        if item_size <= 30 {
            open_cost -= 3.0;
        }
        // If many bins fit the item, prefer them over a new bin.
        if fitting_bins_count > 1 {
            open_cost += 6.0;
        }
        // If this item would leave a large awkward residual in any bin, new bin is fine.
        score += open_cost;
        // Slight preference modulation by mean residual: if open bins are already
        // quite full on average, opening a new bin is more acceptable.
        score -= 0.05 * mean_residual.min(50.0);
    }

    // Early stream: slight bias toward keeping large residuals for future big items.
    score += (1.0 - progress) * 0.04 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: minimize wasted residual, with non-linear (quartic) waste penalty
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more -> amplify small residuals
    let progress_coupling = 1.0 + 0.8 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);
    score *= progress_coupling;

    // Reward filling bins nearly full (post_residual near zero) more strongly late
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 20.0 * progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Penalize bins far from mean residual (fragmentation smoothing)
    score += 0.05 * ((pr - mean_residual) * (pr - mean_residual)) / (cap * cap) * 100.0;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if next_item_size as f64 <= pr {
            score -= 8.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            score += 2.0 * (gap / cap);
        }
    }

    // Mild penalty for spreading across too many open bins early
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: mod-10 classes capture
    // "friendly" leftovers (multiples of small item sizes).
    let post = post_residual;
    let class = (post % 10) as f64;

    // Penalize residuals that are not harmonically aligned with common
    // item sizes (1..=100, multiples of 5/10 common).
    if post > 0 {
        if post % 10 == 0 {
            score -= 6.0; // perfectly harmonic leftover
        } else if post % 5 == 0 {
            score -= 3.0;
        } else if post < 10 {
            score += 12.0; // dead space: nothing (>=1 min) guaranteed useful
        } else {
            score += class * 0.4; // mild penalty for off-class remainder
        }
    } else {
        score -= 10.0; // perfect fill
    }

    // Integer-division threshold: residual bucket by C/4 quartiles.
    let quart = post / (bin_capacity / 4);
    score += match quart {
        0 => 2.0,      // tiny leftover, mostly wasted
        1 => -1.0,     // quarter-class: fits small items well
        2 => -2.5,     // half-class: very reusable
        _ => -1.5,     // three-quarter: decent
    };

    // Lookahead: strongly reward bins where the next item also fits.
    if next_item_size > 0 {
        if post >= next_item_size {
            let slack = (post - next_item_size) as f64;
            score -= 4.0 + slack * 0.05;
            // harmonic chain: both post and next-item share a class
            if (post % 10) == (next_item_size % 10) {
                score -= 2.0;
            }
        } else {
            score += 3.0; // next item won't fit here; bin likely closes
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // Multiple candidates: tighten competition, favor tight fits.
        let tight = (item_size as f64) / (bin_residual as f64);
        score -= tight * 5.0;
    }

    // New-bin candidate handling: an empty bin should only win when
    // existing fits are poor (large post_residual or dead-space class).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 + 5.0;
        // Attractive if the item is large relative to capacity (few
        // open bins can host big items well later anyway).
        let frac = (item_size as f64) / (bin_capacity as f64);
        if frac > 0.6 {
            score -= 4.0 * frac;
        }
        // Late in the stream, avoid bin proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 3.0;
        // Many open bins with high mean residual -> prefer reusing them.
        score += (open_bins_count as f64).sqrt() * 1.5
               + (mean_residual / bin_capacity as f64) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (1..=100, but
    // effectively >= ~10 in typical streams) can use are pure waste.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leaves a gap that the next item cannot use -> mild penalty
        score += 6.0;
    }

    // Tightness reward: the smaller the waste relative to capacity, the better.
    score -= (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.15;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 30.0 + 40.0 * pressure;
    } else {
        score -= 10.0 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, residual waste matters even more (fewer chances to fix it).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.5 * progress;

    // Slight preference for bins below mean residual (balance load, keep
    // large residuals available for large future items).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits with small leftover.
    else if next_item_size > 0 && post_residual > next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 25.0 - leftover.min(25.0);
    }
    // Next item does not fit in this bin after placement: penalize proportionally.
    else if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap.min(40.0);
    }

    // Reward tight fits (small dead space relative to capacity).
    let tightness = (item_size as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize bins far below mean residual (unbalanced usage) mildly.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // Early in the stream, prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 0 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Make new-bin candidate (empty bin) costly unless residual is unusable.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 35.0 + waste * 0.3;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus proportional to how snugly the next item fits the leftover.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * snug;
        } else {
            // Penalize leftovers just below next_item_size (near-miss dead space).
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 20.0 {
                score += 12.0 * (1.0 - miss / 20.0);
            }
        }
    } else {
        // Last item: strongly prefer the tightest possible fit.
        score -= 60.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, mildly prefer emptier bins to consolidate load.
        score += 3.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early stream: opening bins is cheap; late stream: penalize new bins.
        let time_penalty = 20.0 + 40.0 * progress;
        // If the current bin would leave a very small residual, opening fresh is fine.
        let waste_penalty = if post_residual < bin_residual && post_residual < 15 {
            -10.0
        } else {
            0.0
        };
        score += time_penalty + waste_penalty - 5.0 * open_bins_count as f64 * 0.1;
    } else {
        // Open bin: slight bonus when its residual deviates favorably from the mean.
        score -= 2.0 * (bin_residual as f64 - mean_residual).signum() * -1.0
            * ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64);
    }

    // Global pressure: many open bins -> favor filling existing ones harder.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += poly * 40.0;

    // Favor tight fits more strongly as stream progresses.
    let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
    score -= tightness * (20.0 + 60.0 * progress);

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Penalize dead space relative to mean residual of open bins.
    score += (pr - mean_residual).max(0.0) * 0.5;

    // Last-chance bin bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild preference for reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 define
    // "dead space classes". Residues near 0 are dangerous (tiny unusable
    // slivers), residues near 5 are the most reusable mid-fractions.
    let residue = post_residual % 10;
    let harmonic_penalty: f64 = match residue {
        0 => 12.0,
        1 | 9 => 8.0,
        2 | 8 => 5.0,
        3 | 7 => 2.5,
        4 | 6 => 0.5,
        _ => 0.0, // residue 5: golden class, reward
    };
    score += harmonic_penalty;

    // Reward post-residuals that are harmonic multiples of common item
    // classes (integer-division thresholds on 100 / k).
    let div_class = post_residual / 25; // 0..=4 coarse fraction class
    match div_class {
        0 => score += 6.0,           // <25: near-full, only tiny items fit
        1 => score -= 1.0,           // 25..49: quarter-class residual
        2 => score -= 3.0,           // 50..74: half-class residual, very reusable
        3 => score -= 2.0,           // 75..99
        _ => score += 0.0,           // full bin (new-bin candidate)
    }

    // Coupling with lookahead item: if next item fits exactly into the
    // post residual, strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // harmonic class of the slack after the next item
            let next_res = slack % 10;
            if next_res == 0 && slack > 0 {
                score += 4.0; // would create a fresh dead sliver
            } else if next_res >= 4 && next_res <= 6 {
                score -= 2.0;
            }
            score += slack as f64 * 0.05;
        } else {
            // next item cannot use this residual at all
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 3 {
        score += 1.5; // plenty of alternatives, mild deprioritization
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no open bin offers a good harmonic fit.
    if bin_residual == bin_capacity {
        // baseline cost of consuming a fresh bin
        score += 8.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing fits elsewhere: must open
        } else if fitting_bins_count == 1 {
            score += 5.0; // one alternative exists, prefer it mildly less
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // big next item: fresh capacity is valuable
        }
    } else {
        // Prefer tighter existing fits: reward small post_residual
        score -= (bin_capacity - bin_residual) as f64 * 0.02;
    }

    // Progress-aware dead-space tolerance: late in the stream, squeeze
    // harder into open bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (open_bins_count as f64).sqrt().min(4.0);

    // Mild preference toward bins below mean residual (keeps spread even,
    // preserves many mid-sized residuals across the fleet).
    if (post_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps that can't fit even the smallest item)
    let min_item = 1u32; // sizes 1..100, but use next_item_size as practical minimum
    if post_residual > 0 {
        let practical_min = if next_item_size > 0 && next_item_size <= post_residual {
            next_item_size
        } else {
            min_item
        };
        if post_residual < practical_min.max(10) {
            score += 40.0; // dead space penalty
        }
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // residual won't help next item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones
    let new_bin_bonus = (open_bins_count as f64) * 1.5;
    if bin_residual == bin_capacity {
        score += new_bin_bonus;
    } else {
        score -= 2.0;
    }

    // Tightness coupling: prefer bins where item fills a large fraction of residual
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits but avoid tiny unusable slivers.
    if post_residual > 0 {
        // dead-space penalty grows super-linearly for small residuals
        let r = post_residual as f64;
        if r < 10.0 {
            score += (10.0 - r) * 2.5;
        }
    } else {
        // perfect closure is excellent
        score -= 15.0;
    }

    // 2-step lookahead: reward residuals that exactly (or nearly) match next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // exact match: next item closes this bin perfectly
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual > next_item_size {
            // next item still fits: mild bonus proportional to closeness
            score -= (1.0 - diff / bin_capacity as f64) * 4.0;
        } else {
            // next item won't fit here: penalize more if the gap is small (wasted opportunity)
            score += (1.0 - diff / bin_capacity as f64) * 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening a new bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        // neutral base; add penalty so new bins are opened only when needed
        score += 8.0;
        // but if all open bins would leave big dead space, allow new bin
        if post_residual as f64 > mean_residual * 0.5 {
            score -= 10.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean waste potential
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight preference for consolidating into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative fill of this bin before placement
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);

    // Reward tight fits strongly (non-linear): small post_residual gets big bonus
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight_fit * tight_fit;

    // Penalize leaving dead space that no plausible item can use.
    // Items are 1..100; small residuals < ~10 are nearly dead.
    if post_residual > 0 {
        let dead = (10u32.saturating_sub(post_residual)) as f64;
        score += 8.0 * dead;
    }

    // Perfect closure bonus: exactly filling the bin
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement chains beautifully.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 6.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot use leftover space -> mild penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(50.0);
        }
    } else {
        // Last item: strongly prefer closing bins / minimal residual
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 15.0 * fill_ratio;
    }

    // Many open bins: prefer consolidating into fuller bins to allow bin closure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 3.0 * pressure * fill_ratio;

    // Global residual alignment: prefer bins whose residual is close to the mean
    // (keeps the pool of usable residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early stream: be slightly conservative (favor fuller bins less aggressively);
    // late stream: pack aggressively to close bins.
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit. Penalize the empty-bin call so it wins only
    // when all fits would create large dead space.
    if bin_residual == bin_capacity {
        let worst_case_dead = 10.0; // typical unusable leftover threshold
        score += 35.0 + 0.5 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity.saturating_sub(item_size) {
            // new bin leaves room for the lookahead item: soften penalty
            score -= 12.0;
        }
        // Late in the stream, opening fresh bins is cheap; allow it more often.
        score -= 20.0 * progress;
        let _ = worst_case_dead;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with quadratic sharpening
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth non-linear coupling with stream progress: waste penalized more later
    let t = progress * std::f64::consts::PI;
    score += 30.0 * (1.0 - (t * 0.5).cos()) * norm_pr * pr;

    // Cubic interaction: tight fits (small norm_pr) heavily rewarded as stream advances
    score -= 25.0 * progress * (1.0 - norm_pr).powi(3) * pr;

    // Mean residual coupling: placing into bins below mean residual is favored
    score -= 8.0 * (mean_residual - pr) / cap;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 12.0 * fit_quality * (1.0 - progress);
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for proliferating bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize opening unless current residuals are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        let pressure = 1.0 - fragmentation;
        score += 15.0 + 25.0 * (1.0 - pressure) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space in the "small tail"
    // classes (1..=9) is nearly unusable for items of size >= 10, so penalize.
    let tail = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // fully dead residual
    } else if tail <= 5 {
        score += 8.0 * (5 - tail) as f64;
    }

    // Perfect fit reward (harmonic node at 0)
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: ratio of item to residual (capacity fraction)
    let fill_frac = item_size as f64 / bin_residual as f64;
    if fill_frac > 0.8 {
        score -= 25.0 * fill_frac;
    } else if fill_frac < 0.3 {
        score += 10.0; // wasteful placement into a large bin
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Harmonic class match: next item fits well if post_residual - next is small
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0 - gap as f64;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Bin becomes dead for the next item: penalize proportionally to closeness
        if next_item_size - post_residual <= 5 {
            score += 15.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bins should only win when open bins fit badly
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 50.0;
        // If current bins are fragmented (high mean residual spread), new bin is fine
        if mean_residual < 20.0 && next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // forced open
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Mild pressure against accumulating too many open bins
    score += open_bins_count as f64 * 0.5;

    // Harmonic threshold bonus: post_residual in reusable mid classes (20,30,...)
    if post_residual >= 10 && post_residual % 20 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // any plausible future item (min size 1..10) are pure waste.
    if post_residual < 10 {
        score += 40.0; // unusable sliver: heavy penalty
    } else if post_residual < 20 {
        score += 15.0; // barely usable, risky gap
    } else {
        // Usable residual: reward tight fits proportionally
        score -= (post_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating
    // into existing bins rather than spreading; discourage opening new bins.
    let bin_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow,
        // unless current bins are badly fragmented (high mean residual spread).
        score += 30.0 + bin_pressure * 2.0;
        // If this bin is a last chance, strongly discourage opening a new bin
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    } else {
        // Existing bin: slight reward when many bins are open (consolidation)
        score -= bin_pressure * 0.5;
        // Last-chance bin: strong reward to use it before it dies
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 12.0;
        } else {
            score -= 3.0;
        }
    }
    // If next item would NOT fit in the remaining residual, mild penalty
    // unless residual is near zero (already closed out).
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Stream progression: late in the stream, waste tolerance drops.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Mean residual context: if open bins are already loose on average,
    // penalize adding more looseness; if they are tight, reward fit.
    if mean_residual > 50.0 {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (small post_residual).
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            // Exact match is ideal; scale reward by closeness.
            let gap = pr - nxt;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize wasted space.
            score += 0.3 * (pr - nxt).abs();
        }
    }

    // Compare residual against mean residual across open bins: keep diversity of residual sizes.
    if post_residual as f64 > mean_residual {
        score += 0.2 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.1 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good open candidates exist.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if next item fits into post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.15 * (post_residual - next_item_size) as f64;
    }
    // If next item would leave this bin almost empty after, mild extra reward.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size <= 5 {
        score -= 5.0;
    }
    // Penalize bins whose residual can't serve the lookahead item (dead space risk).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is penalized, but worthwhile
    // when existing residuals are fragmented (mean residual low relative to item).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 - 10.0 * progress;
        // If many bins can fit, discourage opening a new one.
        score += 3.0 * (fitting_bins_count as f64).min(6.0);
        // If mean residual across open bins is large enough to likely fit future
        // items, opening a new bin is less urgent.
        if mean_residual > item_size as f64 + 20.0 {
            score += 10.0;
        }
        // Few open bins and small item: prefer filling existing space.
        if open_bins_count > 0 && item_size <= 30 {
            score += 8.0;
        }
    }

    // Slight preference for bins already below mean residual (consolidate fullness).
    score += 0.05 * ((bin_residual as f64 - mean_residual).max(-50.0));

    // Global pressure: when many bins are open, discourage waste more strongly.
    score += 0.01 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Core: prefer tight fits (small post_residual), with non-linear emphasis.
    let pr = post_residual as f64;
    let mut score = pr * (1.0 + 0.8 * pr / cap);

    // Smooth polynomial coupling with stream progress: early on, waste is cheap
    // (bins get filled later anyway); late, dead space is costly.
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward bins whose residual stays compatible with the lookahead item (k=2):
    // subtract if next item could fill the post-residual nicely.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 6.0 * fill_quality * fill_quality * (1.0 + progress);
        } else {
            // post-residual too small for next item: slight penalty for stranding space
            score += 2.0 * (pr / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - pr / cap).powi(2);
    }

    // Mild penalty when this bin's residual deviates from mean residual:
    // keeps the bin pool balanced, smooth quadratic term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // Empty new-bin candidate: add a penalty so it only wins when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress);
    }

    // Small tie-breaker favoring fuller bins (smaller residual) among near-equal fits.
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "reusable"
    // residue classes (multiples of small denominators) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Dead-space penalty: tiny leftovers that few future items can use.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Sweet-spot leftovers: common small item sizes fit here.
    if pr >= 10 && pr <= 30 {
        score -= 12.0;
    }
    // Exact fit is perfect.
    if pr == 0 {
        score -= 60.0;
    }

    // Modulo-class reward: leftover divisible by 10 aligns with typical item
    // granularity, making the residual more "usable".
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    // Integer-division harmonic: leftover in the same decade class as the
    // next item's size suggests a good follow-up fit.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 10.0;
            // Extra reward if leftover is within one small step of next item.
            let gap = pr - next_item_size;
            if gap <= 10 {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this bin's leftover anyway; mild penalty
            // proportional to how far off we are.
            score += (next_item_size - pr) as f64 * 0.15;
        }
        // Harmonic pairing: post_residual + next item leaves a multiple-of-10
        // class residual again.
        if next_item_size <= pr && (pr - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when existing
    // bins are fragmented or nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.45 * cap + 0.25 * mean_residual - 6.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 15.0; // can't happen for empty bin, but keeps class logic
        }
    }

    // Tie-break toward filling fuller bins: residual fraction weighting.
    score += 0.05 * (bin_residual as f64 / cap) * 10.0;

    // Mean-residual coupling: when open bins are on average roomy, prefer
    // compacting into tighter ones (penalize bins above mean residual).
    if bin_residual as f64 > mean_residual {
        score += 0.10 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr);
        } else if pr < 20.0 {
            score += 25.0 * (20.0 - pr) / 10.0;
        }
    }

    // Reward tight fits.
    score -= 15.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 8.0 * open_bins_count as f64;
        // But opening a new bin is attractive if next item is large and no bin can hold both.
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
            score -= 20.0;
        }
    }

    // Reward bins whose residual is close to mean (balanced usage) mildly.
    score -= 0.05 * (mean_residual - post_residual as f64).abs();

    // Slight penalty for residual that exactly matches next item (save for it).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing a bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if the next item fits exactly
    // into the post-residual (a chained double fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward proportional to how tight the
            // remaining space stays after the hypothetical next placement.
            let post2 = post_residual - next_item_size;
            score -= 60.0 - (post2 as f64) * 0.5;
        } else {
            // Next item cannot follow: penalize leaving a gap smaller than
            // the next item (likely dead space).
            score += (post_residual as f64).min(next_item_size as f64) * 0.8;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is already below
    // average (consolidating waste), penalize draining unusually full bins.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // item is large relative to residual capacity of open bins, or late
    // in the stream when many bins are open. Make the fresh bin slightly
    // unattractive by default.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 150.0
            - (item_size as f64) * 0.5
            - progress * 80.0
            - openness * 20.0;
        // A fresh bin is great if the item fills most of it immediately.
        if item_size * 10 / 8 >= bin_capacity * 8 / 10 {
            score -= 120.0;
        }
    }

    // Small extra nudge: reward filling bins tightly overall.
    score -= (item_size as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins that can still host the lookahead item.
            score -= 3.0 * (post_residual as f64 / next_item_size as f64).min(2.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0;
        if poor_fit {
            score -= 6.0; // encourage fresh bin when placement would waste space
        } else {
            score += 18.0; // discourage opening new bins for good fits
        }
        // Fewer open bins -> more eager to fill existing ones.
        score += 2.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Penalize bins far below mean residual (fragmented outliers) mildly.
    score += 0.08 * (mean_residual - bin_residual as f64).abs();

    // Time horizon: as stream progresses, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 4.0 * progress * tightness;
    }

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth polynomial shaping (dead-space penalty grows quadratically for small residuals)
    let mut score = pr
        + 18.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_pr
        - 12.0 * norm_pr * (1.0 - norm_pr);

    // Non-linear coupling with stream progress: early on, prefer tight fills; late, keep flexibility
    let flex = (progress * std::f64::consts::PI).sin();
    score += 20.0 * norm_pr * (1.0 - progress) * (1.0 - progress);
    score -= 10.0 * flex * (1.0 - norm_pr);

    // Lookahead coupling: reward residual that can hold next item (smooth quadratic term)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        if gap >= 0.0 {
            score -= 14.0 * (1.0 - gap * gap) * (0.5 + progress);
        } else {
            score += 10.0 * (-gap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using a bin that is the only fitting option
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Mean-residual deviation: penalize bins far from the mean (smooth square)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * open_bins_count as f64;

    // Slight preference for reusing bins over opening new ones, decaying with progress
    if bin_residual == bin_capacity {
        score += 8.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo small divisors
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize small-but-unusable residuals (dead space) via modular classes
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual >= 20 && post_residual < 30 {
        score -= 6.0;
    } else if post_residual >= 30 && post_residual < 50 {
        score -= 10.0;
    } else if post_residual >= 50 {
        score -= 4.0;
    }

    // Integer-division thresholds: residual class buckets of 25
    let quarter = post_residual / 25;
    score -= (quarter as f64) * 3.0;

    // Modulo-10 harmonic class: residuals divisible by 10 pair better with
    // common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does this bin's post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic match: residual class compatible with next item
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportional waste
            let waste = next_item_size as f64 - pr;
            score += waste * 0.3;
            // If residual is in a dead class (< 10), extra penalty
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only prefer when existing bins are poor fits
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when justified
        score += 25.0;
        // If few fitting bins and mean residual is large, new bin less attractive
        score -= (mean_residual / cap) * 20.0;
        // Early in stream, slightly more willing to open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
        // If next item is large, opening a fresh bin now is fine
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Tight-fit bonus: item fills most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.8 {
        score -= 10.0;
    } else if fill < 0.4 {
        score += 5.0;
    }

    // Slight preference for bins with below-mean residual (consolidation)
    let res = bin_residual as f64;
    score += (res - mean_residual) * 0.1;

    // Mild pressure to close bins as stream progresses
    score += (open_bins_count as f64) * 0.5 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size
    // (1..=10) are wasted forever -> penalize them super-linearly.
    if post_residual < 10 {
        score += (11 - post_residual as i32 as f64) * 40.0;
    } else if post_residual < 20 {
        // Small gaps that only very small items can use are semi-dead.
        score += 15.0;
    }

    // Reward tight fits strongly (low post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64 / bin_residual.max(1) as f64) * 25.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot follow here -> this bin becomes dead space.
            score += 12.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when few
    // fitting bins exist (last-chance bins are precious).
    if fitting_bins_count <= 1 {
        score -= 30.0; // strongly prefer using the last fitting bin
    } else {
        score += (open_bins_count as f64) * 0.5;
    }

    // New-bin candidate handling: an empty bin has full residual. Only prefer
    // it when the current item is large and would leave a poor gap elsewhere,
    // or when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // But large items that would leave big unusable gaps in existing bins
        // justify a new bin.
        if item_size >= 50 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Mild mean-residual coupling: prefer bins whose residual is below the
    // mean (i.e., tighter bins) to consolidate small residuals.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size <= post_residual {
            // reward proportional to how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot fit here: penalize leaving large awkward gaps
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize creating dead space below the minimum item size (unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer bins with residual below mean (tighter bins get filled first),
    // keeping emptier bins flexible for larger future items.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Mild penalty for opening a new bin when existing bins fit well.
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if many bins are open and fragmented, new bin can be fine
        score -= (open_bins_count as f64).min(20.0);
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but dead space below a
    // plausible minimum item size is nearly worthless.
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual < item_size {
        // residual smaller than the current item: hard to reuse
        score += (item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 1
            || (post_residual as f64) > mean_residual;
        if poor_fit {
            score -= 30.0;
        } else {
            score += 60.0; // discourage wasting a fresh bin on a loose fit
        }
    }

    // Lookahead: if the next item could use this bin's post_residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0; // perfect chain placement
        } else if post_residual > next_item_size {
            score -= 10.0; // next item still fits here afterwards
        } else {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Global state: many open bins with large mean residual -> consolidate.
    if open_bins_count > 4 && mean_residual > 20.0 {
        let tightness = (mean_residual - post_residual as f64).abs();
        score += tightness * 0.3;
        score -= mean_residual * 0.05;
    }

    // Time horizon: early in the stream, be pickier about dead space since
    // future item sizes are unknown; late in the stream, just fill bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.1;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post-residual (prefer tight fits), non-linearly warped.
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, large residuals become increasingly costly.
    let prog_sq = progress * progress;
    score += pr * pr / cap * (0.15 + 0.85 * prog_sq);

    // Fractional-fill term: reward high fill ratio with a cubic coupling.
    let fill = fit / cap;
    score -= 6.0 * fill * fill * (1.0 + progress);

    // Penalize leaving residuals just above the smallest plausible item
    // (dead space) via a smooth bump around mid residuals.
    let dead = (pr - 15.0) / 30.0;
    score += 4.0 * (-dead * dead) * (pr / cap);

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = (pr - nx) / cap;
            score -= 5.0 * (1.0 - gap * gap);
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // New-bin candidate: only attractive when few open bins or late stream;
    // otherwise penalize opening a fresh bin.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 10.0 * (1.0 - progress) * (1.0 + openness.ln().max(0.0));
        // But if no open bin fits tightly, new bin becomes reasonable.
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
    }

    // Slight preference for bins whose residual is above average (keep
    // small-residual bins for small future items).
    score += 0.5 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity fraction bands.
    // Residuals in small "dead zones" (1..=9) are nearly unusable -> penalize.
    let dead = if post_residual > 0 && post_residual <= 10 { 1 } else { 0 };
    score += dead as f64 * 25.0;

    // Class of post_residual by integer division: r/10 gives harmonic class 0..10.
    // Mid-class residuals (class 2..5, i.e. 20..50) are reusable by typical items -> reward.
    let rclass = (post_residual / 10) as f64;
    if rclass >= 2.0 && rclass <= 5.0 {
        score -= 8.0;
    }

    // Exact-fill reward: post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic coupling with next item: if next item fits exactly in post_residual,
    // this placement sets up a perfect chain -> strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item fits with a dead-zone leftover, penalize.
    if next_item_size > 0 && next_item_size < post_residual {
        let next_left = post_residual - next_item_size;
        if next_left <= 10 {
            score += 12.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item does NOT fit here, this bin's residual should be as large/reusable
    // as possible; small residuals that block nothing are fine, but a residual just
    // below next_item_size is a frustrating harmonic miss.
    if next_item_size > post_residual && post_residual > 0 {
        let miss = next_item_size - post_residual;
        if miss <= 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Brand-new bin candidate: neutral-ish score so it's chosen only when
    // open bins have poor fits. Give it a mild penalty scaled by open bins.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Early stream: be conservative, slightly prefer compact packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    // Gaps below the minimum possible item size (1) are impossible, but gaps
    // smaller than a "typical" item (say < 20) are likely dead space.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }
    // Perfect fit: strongly reward zero residual.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Coupling: dead space penalty scales with how many bins are open
    // (more open bins => more pressure to keep bins tight).
    let open_pressure = open_bins_count as f64;
    if post_residual > 0 && post_residual < 20 {
        score += open_pressure * 2.5;
    }

    // Lookahead: if the next item fits exactly into post_residual,
    // reward leaving that gap; otherwise penalize gaps close to next size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless dead space is egregious).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: neutral-to-slightly-positive baseline so it is only
    // chosen when open bins have bad fits.
    if bin_residual == bin_capacity {
        score += 15.0 + open_pressure * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (tighter bins) when post_residual is small.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Progression: late in stream, tighten more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.1 + 0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: this bin's leftover perfectly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: reserve this bin
        } else if next_item_size <= post_residual {
            // Next item still fits: reward proportionally to how snug the chain is.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize leaving a gap smaller than next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap.min(60.0);
        }
    } else {
        // Last item: just minimize leftover.
        score -= 10.0;
    }

    // Penalize creating tiny unusable fragments relative to mean residual.
    if (post_residual as f64) < mean_residual * 0.35 && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let good_fit_exists = next_item_size == 0
            || fitting_bins_count > 1
            || open_bins_count == 0;
        if good_fit_exists {
            score += 55.0; // discourage new bin when decent fits exist
        } else {
            score += 5.0;  // mild preference for fresh bin on poor fits
        }
    }

    // Slight late-stream consolidation pressure: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 6.0 * progress;
    }

    // Prefer bins with larger residuals consumed efficiently (tighter fits win).
    score += 0.05 * (bin_residual as f64 - post_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity
    score -= 0.5 * (1.0 - post_residual as f64 / cap) * (item_size as f64 / cap) * 30.0;

    // Penalize dead space that likely cannot fit future items
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.4;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0; // bin remains usable for the lookahead item
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: empty bin is attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // open new bin when mean residual is small (open bins nearly full)
        score = 40.0 + 30.0 * (1.0 - fragmentation) + 20.0 * progress;
        if next_item_size as f64 <= mean_residual.max(0.0) {
            score += 10.0; // existing bins can likely serve next item too
        }
        if item_size as f64 > 0.6 * cap {
            score -= 15.0; // big items: fresh bin gives full flexibility
        }
        return score;
    }

    // Slight preference to fill bins that are already low-residual (consolidation)
    score += (bin_residual as f64 / cap) * 5.0;

    // Penalize opening extra bins when many already open
    score += open_bins_count as f64 * 0.2;

    // Time-horizon modulation: early stream, be conservative; late stream, pack aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Core: quadratic coupling of post_residual with stream progress.
    // Early on, waste matters less; later, tight packing dominates.
    let pr = post_residual as f64;
    let mut score = pr * (1.0 + 2.5 * progress) + 0.9 * pr * pr / cap;

    // Reward near-perfect fits smoothly (non-linear bonus for tiny residual).
    let fit_ratio = pr / cap;
    score -= 6.0 * (1.0 - fit_ratio).powi(12) * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 4.0 + 3.0 * progress;
    }

    // Prefer filling bins whose residual deviates below the mean (consolidate waste).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * (0.5 + progress);

    // Lookahead: if the next item would fit the post-residual, reward this placement.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 3.0 * (1.0 - gap / cap).max(0.0);
    }

    // Mild penalty for proliferating bins; stronger late in the stream.
    score += 0.15 * open_bins_count as f64 * (0.3 + progress);

    // New-bin candidate: baseline cost so it only wins when fits are truly poor.
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress + 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "usable" residue class are rewarded, awkward classes penalized.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 12.0,                 // perfectly divisible leftover
        1 | 2 | 3 => score += 3.0,          // sliver dead space
        4 | 5 | 6 => score -= 2.0,          // mid-class, still usable
        _ => {}
    }

    // Integer-division threshold: leftover that can hold a typical small item
    let quot = pr / 25; // 0..=4 usable slots
    score -= quot as f64 * 4.0;

    // Lookahead coupling: reward leftovers that exactly host the next item
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 25.0;
        } else if pr >= next_item_size {
            score -= (pr - next_item_size) as f64 * 0.15;
        } else {
            // leftover cannot host next item: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.2;
        }
        // harmonic pairing: next item size class vs leftover class
        if (pr % 20) == (next_item_size % 20) && pr >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: penalize unless current bin fit is very tight
    if bin_residual == bin_capacity {
        let tightness = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * tightness;
    }

    // Progress-scaled tie-break: later in stream, consolidate more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Mean residual divergence: prefer bins near the mean (balanced packing)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual <= 20 {
        score += 10.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && bin_residual - post_residual >= next_item_size {
            score += 12.0; // consumes space the next item needed
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: mild penalty scaling with number of open bins,
    // encouraging consolidation into existing bins.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins tighter than the mean residual (good fits).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: only attractive when no open bin fits well
    // or residuals are very tight.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward exact/near match of next item into post_residual ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            // next item fits here: reward tight chain (small leftover after next)
            let chain_leftover = pr - nx;
            score -= 12.0 * (1.0 - chain_leftover / bin_capacity as f64);
            if chain_leftover == 0.0 {
                score -= 20.0; // perfect 2-item fill
            }
        } else {
            // next item won't fit here; penalize bins that strand near-miss space
            let miss = nx - pr;
            if miss <= 10.0 {
                score += 6.0 + 0.5 * miss;
            }
        }
    }

    // --- Mean-residual coupling: prefer bins whose residual is below mean (tight bins first) ---
    score += 0.4 * (mean_residual - post_residual as f64);

    // --- Last-chance bonus: only fitting bin, keep it alive ---
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 15.0;
    }

    // --- Penalize large dead space that few items can use ---
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // --- New-bin candidate handling: only prefer fresh bin when no open bin gives a good fit ---
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_residual as f64 - item_size as f64) > mean_residual * 0.0
            && post_residual <= 15;
        if good_fit_exists {
            score += 25.0; // discourage opening new bin when a tight fit exists
        } else {
            score -= 5.0; // mildly favor fresh bin over loose fits
        }
    }

    // --- Slight late-stream consolidation pressure ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: minimize waste, but weight it by stream progress (later items tolerate more waste)
    let mut score = x * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling of post-residual with progress
    score += (x * x * (1.0 - x)) * (0.5 + 1.5 * progress) * cap * 0.1;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (x - nx).max(0.0);
        score -= gap * gap * (2.0 - progress) * cap * 0.3;
        score += (nx - x).max(0.0) * 0.5; // next item won't fit here: mild penalty
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Slight penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.05 * x;

    // Compare against mean residual: prefer bins below-mean waste (tight fit)
    score += ((mean_residual - pr) / cap) * 0.4;

    // New-bin candidate: neutral-ish baseline, only attractive when fits are bad
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.25 * progress) - 0.5 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes (dead space) are penalized, "nice" leftovers rewarded.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Fractional fill of the bin after placement (0..1)
    let fill = 1.0 - (pr as f64) / cap;

    // Reward high fill non-linearly (harmonic-ish weighting)
    score -= 30.0 * fill * fill;

    // Modulo-class logic on post_residual: leftovers that are multiples of a
    // small modulus are more reusable (items 1..100, many sizes divisible by 5/10).
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
        // Dead-space class: tiny leftovers (1..=9) are nearly unusable
        if pr < 10 {
            score += 25.0 - 2.0 * pr as f64;
        }
    } else {
        // Perfect fit is excellent
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0;
            // Harmonic class: exact modular compatibility with next item
            if pr % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            // Prefer leftover that is a small multiple of next item size
            let ratio = pr as f64 / next_item_size as f64;
            if ratio >= 1.0 && ratio <= 2.0 {
                score -= 5.0;
            }
        } else {
            // Leaving a gap smaller than next item = wasted opportunity
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless it's a terrible fit).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early in the stream or when many bins are
        // already open and this is a large item; penalize otherwise so we
        // prefer filling existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let large_item = item_size >= 50;
        let mut nb = 20.0;
        if large_item {
            nb -= 10.0;
        }
        if open_bins_count == 0 {
            nb -= 30.0; // must open first bin
        }
        if progress < 0.2 {
            nb -= 5.0;
        }
        // If next item is huge, a fresh bin is attractive
        if next_item_size >= 60 {
            nb -= 5.0;
        }
        score = nb + (100 - item_size.min(100)) as f64 * 0.1;
    }

    // Mild preference to consolidate: bins below mean residual are worse targets
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else if bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += post_residual as f64 * 0.3;
    }

    // Pressure from number of open bins: prefer denser packing when many bins open.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make empty bin moderately attractive only when fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - slack * 0.5;
            if post_residual == next_item_size {
                score -= 400.0; // chain of perfect fits
            }
        } else {
            // Next item won't fit here: penalize small dead space more than large.
            score += 30.0 + (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Compare residual against mean residual across open bins.
    if (post_residual as f64) > mean_residual + 20.0 {
        score += 25.0; // creating an outlier large residual wastes space
    } else if (post_residual as f64) <= mean_residual {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Late in the stream, tighten packing (avoid opening bins for small gains).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // Penalize opening a new bin when open bins can fit, unless current bins are tight.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let avg_tightness = 100.0 - mean_residual;
        if avg_tightness < 60.0 {
            score += 150.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 60.0;
    }

    // Penalize dead space relative to capacity (non-linear).
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 150.0 * dead_frac * dead_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    } else if fitting_bins_count >= 2 {
        // Many alternatives: slight penalty to prefer tighter options elsewhere.
        score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 40.0 * (1.0 - miss / 60.0).max(0.0);
        }
    }

    // Global state: prefer filling bins when many are open and mean residual is low.
    let openness = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).min(1.0);
    let mean_tight = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 50.0 * openness * mean_tight;

    // Time horizon: early in stream, be more willing to open fresh bins (score new-bin lower);
    // late in stream, consolidate into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, unattractive late.
        score -= 90.0 * (1.0 - progress);
        score += 80.0 * progress;
        // New bin especially good if item is large and no open bin fits well.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    } else {
        // Existing bin: slightly more attractive as stream progresses.
        score -= 20.0 * progress;
    }

    // Mild penalty for very large post residual on an existing bin (wasted space).
    if bin_residual != bin_capacity && post_residual > 50 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual, with a non-linear (quadratic) penalty
    // for leaving awkward mid-range gaps.
    let mut score = norm_post * (1.0 + 1.5 * norm_post * (1.0 - norm_post));

    // Stream-progress coupling: early on, tolerate loose fits (explore),
    // late in the stream, aggressively tighten packing.
    let tightness = 1.0 + 2.0 * progress * progress;
    score *= tightness;

    // Interaction: post_residual x progress polynomial term penalizing
    // dead space that grows more costly as the stream ends.
    score += 0.8 * norm_post * norm_post * (0.5 + progress);

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.6 * (1.0 - progress) * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 0.3 * progress * (1.0 - norm_post);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin, scaled by how good the fit is.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = 1.0 - norm_post;
        score -= 1.2 * fit_quality * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: make the empty bin attractive only when the item fits
    // very poorly in existing bins (large post_residual would be avoided anyway);
    // otherwise keep it mildly unattractive.
    if bin_residual == bin_capacity {
        score += 0.4 + 0.5 * progress;
    }

    // Mean-residual coupling: when open bins are generally roomy, slightly
    // discourage adding to congestion in already-tight bins.
    let mean_norm = mean_residual / cap;
    score += 0.25 * (1.0 - mean_norm) * norm_post;

    // Congestion term: many open bins -> prefer filling existing ones.
    score -= 0.05 * (open_bins_count as f64).sqrt() * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the gap left behind: capacity divided into 8 harmonic bands.
    // Small gaps (near-perfect fits) are heavily rewarded; mid gaps are penalized
    // because they are hard to fill later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let band = (pr / (cap / 8.0)).floor(); // 0..8
    match band as u32 {
        0 => score -= 60.0,                 // gap <= C/8 : near-perfect fit
        1 => score -= 25.0,
        2 => score += 5.0,                  // awkward mid-size gap
        3 => score += 12.0,
        4 => score += 15.0,                 // worst dead-space zone (~C/2)
        5 => score += 8.0,
        6 => score -= 5.0,                  // large gaps stay reusable
        _ => score -= 20.0,                 // gap > 7C/8 : bin was nearly empty
    }

    // Integer-division threshold: exact modular harmony between gap and next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 90.0; // next item seals this bin perfectly
        } else if next_item_size < post_residual {
            // gap after the NEXT placement also matters: lookahead residual class
            let post2 = post_residual - next_item_size;
            let band2 = (post2 as f64 / (cap / 8.0)).floor() as u32;
            score -= match band2 {
                0 => 40.0,
                1 => 15.0,
                2 => 0.0,
                3 => -8.0,
                4 => -12.0,
                _ => -4.0,
            };
            // modulo harmony: gap divisible into chunks of the next item size
            if post_residual % next_item_size == 0 {
                score -= 18.0;
            }
        } else {
            // next item cannot fit here; this bin's gap is final
            score += 10.0;
            if band as u32 >= 2 && band as u32 <= 5 {
                score += 15.0; // finalizing a dead-space gap is bad
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 55.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // residuals are small relative to the item (poor fits everywhere).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = item_size as f64 / cap;
        let tight = mean_residual < item_size as f64 * 1.3;
        if tight && open_bins_count > 0 {
            score -= 10.0 + 25.0 * pressure; // allow escape hatch
        } else {
            score += 45.0; // discourage scattering into fresh bins
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 20.0; // next item also needs space: new bin useful
        }
    }

    // Mild stream-progression tightening: later in the stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0 * ((post_residual as f64 / cap) - 0.5);

    // Prefer bins below mean residual (filling emptier bins first keeps big gaps alive).
    score -= (mean_residual - pr) * 0.15;

    // Tie-break by exact fit fraction.
    score -= (item_size as f64 / (bin_residual.max(1) as f64)) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are pure waste.
    let dead_threshold = 10.0f64; // smallest legacy item size
    if (post_residual as f64) < dead_threshold {
        score += 40.0; // unusable sliver -> strong penalty
    }

    // Non-linear dead-space curve: small-but-nonzero gaps are quadratically bad.
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 60.0 / pr; // shrinks toward 0 as gap grows
    }

    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin residual (waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 20.0;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high,
        // but allow opening when this bin is a last-chance fit elsewhere.
        score += 30.0 + pressure;
        if fitting_bins_count == 1 {
            score += 10.0; // don't abandon the only fitting bin lightly
        }
    } else if fitting_bins_count == 1 {
        // This is the only bin that fits: strongly favor using it.
        score -= 35.0 + pressure * 0.3;
    }

    // Lookahead coupling: if the next item fits the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward if next item exactly fills the remaining gap.
        if next_item_size == post_residual {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover gap: mild penalty scaled to gap.
        score += (post_residual as f64) * 0.1;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (fill the tighter bins first, keep loose bins flexible).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(50.0) * 0.3;
    } else {
        score += (res - mean_residual).min(50.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a non-linear reward.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect chain: post_residual exactly fits next item -> strong reward.
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item can chain into this bin: reward closeness of the chain fit.
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 15.0; // exact 2-item completion of the bin
            }
        } else {
            // Next item cannot fit: penalize leftover dead space, worse when
            // the leftover is small (unusable) relative to typical item sizes.
            let waste_ratio = post_residual as f64 / 100.0;
            score += 8.0 * (1.0 - waste_ratio);
        }
        // Coupling with mean residual: if this bin's post-residual deviates
        // strongly from the fleet mean, discourage fragmenting the fleet.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    } else {
        // Last item: just close tightly.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; grows with stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 15.0 * progress;
        // But if item is large and would leave near-zero post residual in a
        // fresh bin, opening is fine (perfect pack).
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Slight preference to fill bins that are already mostly full.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small unusable leftovers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose leftover can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // leftover cannot host next item: mild penalty, stronger late in stream
            let t = step_index as f64 / (total_items.max(1) as f64);
            score += 6.0 * (0.5 + t);
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin grows with number of open bins (encourage reuse).
        score += 10.0 + 0.6 * open_bins_count as f64;
        // If few bins fit the item, a new bin is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * t;
    }

    // Global state: if mean residual is high, push toward filling the fullest bins.
    score -= 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Slight preference for bins with small residual overall (best-fit flavor).
    score += 0.05 * bin_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // Base: prefer low post-residual, with non-linear sharpening.
    let mut score = pr * (1.0 + 0.6 * fill * fill);

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, dead space is costlier.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr * (0.5 * p2 + 0.9 * p3) * (1.0 - 0.3 * tight);

    // Reward tight fits (small relative post-residual) non-linearly.
    score -= 12.0 * (1.0 - pr / cap).powi(3);

    // Last-chance bin: strongly reward using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * fill;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        let nd = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (1.0 - nd / cap).powi(2);
    } else {
        // Last item: prefer fullest packing.
        score -= 5.0 * fill;
    }

    // Penalize bins that are far below mean residual (wasteful fragmentation),
    // smoothly scaled by number of open bins.
    score += 0.15 * (mean_residual - pr).abs() * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Mild penalty on post-residuals that are unusable small gaps (non-linear).
    let gap_frac = pr / cap;
    if gap_frac < 0.2 {
        score += 10.0 * (0.2 - gap_frac) * (0.2 - gap_frac) / 0.04;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by common item sizes
    // leaves reusable space; odd fragments create dead space.
    let pr = post_residual;
    let mut harmony = 0.0f64;
    if pr == 0 {
        harmony -= 30.0; // perfect fit
    } else {
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 {
                harmony -= 12.0;
            }
        }
        if pr % 2 == 1 { harmony += 4.0; } // odd residual harder to fill
        if pr < 10 { harmony += 10.0; }    // unusable sliver
    }
    score += harmony;

    // Pairing bonus: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack < 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residual: penalize proportionally
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 8.0 + 0.1 * (item_size as f64);
    }

    // New-bin candidate handling: empty bin has full residual; make it attractive
    // only when existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.55 + (open_bins_count as f64) * 2.0;
        if item_size >= 50 {
            score -= 10.0; // big items prefer fresh bins
        }
    }

    // Late in stream: consolidate, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin is far below mean residual, it's a
    // good "garbage collector" bin; reward slightly.
    score -= 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
