pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving near-zero dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.8; // tighter chain fit -> bigger bonus
            if post_residual == next_item_size {
                score -= 150.0; // exact 2-step chain (both fit perfectly)
            }
        } else {
            // Next item cannot follow here: penalize proportionally to wasted potential.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers of dead space.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.6;
    } else {
        score -= (mean_residual - pr) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
        // Extra push when the fit is decent.
        if (post_residual as f64) <= mean_residual {
            score -= 50.0;
        }
    }

    // Penalize new-bin candidate slightly, unless current bins are too crowded to be useful.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.5;
        if crowded {
            score -= 80.0;
        } else {
            score += 90.0;
        }
    }

    // Late-stream urgency: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (1.0 - pr / bin_capacity as f64);

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Reward proportionally to how well the next item uses leftover space.
            let leftover_after_next = post_residual - next_item_size;
            score -= 50.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable residual,
    // unless the item is large relative to residuals (poor fit elsewhere).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_penalty = post_residual as f64; // = capacity - item_size
        // Early in stream: prefer reusing bins; later: opening new bins less costly.
        score += waste_penalty * (1.5 - progress) * 2.0;
        // If many open bins already, opening yet another is worse.
        score += open_bins_count as f64 * 3.0;
        // If the mean residual is small (bins are full), a new bin is more acceptable.
        score -= mean_residual * 1.5;
        // If no other bin fits (fitting_bins_count == 1 refers to this new bin), neutralize.
        if fitting_bins_count <= 1 {
            score -= 400.0;
        }
    } else {
        // Reward using bins whose residual deviates favorably from the mean
        // (consolidating residual space into fewer bins).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.3 * dev;
        // Prefer bins that become "tight" after placement.
        score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 20.0;
    }

    // Mild time decay: later in the stream, be slightly more conservative with residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr * (1.0 + 0.3 * poly);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (cap - pr) as f64 * 0.15 * (progress + 0.5);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += (next_item_size as f64 - pr) * 0.8 * (0.5 + progress);
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // Align with mean residual: prefer bins whose post residual is close to mean
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * 3.0;

    // New-bin candidate: keep it neutral-ish, slightly penalized so it is chosen
    // only when open bins would waste a lot of space
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * norm_pr * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 30.0;

    // Harmonic class of the post-residual: mod-10 buckets.
    let class = post_residual % 10;
    // Dead space classes: residuals in {1..9} are hard to fill; multiples of 10 are reusable.
    if class == 0 {
        score -= 12.0; // perfectly aligned residual, reward
    } else if class <= 3 {
        score += 8.0;  // tiny sliver, nearly dead space
    } else if class <= 6 {
        score += 4.0;  // awkward mid class
    } else {
        score += 1.0;  // moderate class, mild penalty
    }

    // Integer-division thresholds: how many "average items" could still fit.
    let avg_item = if total_items > 0 { 50.0 } else { 50.0 };
    let fits_left = post_residual as f64 / avg_item;
    score -= fits_left * 3.0;

    // Lookahead: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact harmonic match: next item fills bin completely.
            if next_item_size == post_residual {
                score -= 25.0;
            } else {
                // Modulo harmony: (post_residual - next) divisible by 10 is good.
                let gap = post_residual - next_item_size;
                if gap % 10 == 0 {
                    score -= 10.0;
                } else {
                    score -= 4.0;
                }
            }
        } else {
            // Next item won't fit here; penalize slightly unless residual is small anyway.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost.
        score = 40.0 + fit_ratio * 10.0;
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 2.0);
        // If mean residual across open bins is large, prefer reusing open bins -> raise new-bin score.
        score += (mean_residual / bin_capacity as f64) * 30.0 * pressure;
        // If current fit creates a tiny dead sliver in an existing bin, new bin becomes better.
        if post_residual > 0 && post_residual < 10 {
            score -= 15.0;
        }
        // Late in stream, be more conservative about opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Global tie-break: prefer bins with residual close to item_size (tightest packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 15.0;

    // Prefer bins below mean residual (more filled bins first).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space): residuals too small for the
    // smallest plausible item are worthless.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 8 {
        score += 25.0 + (8 - (post_residual - min_item)) as f64 * 3.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 6.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing bins over
    // opening new ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 2.0 + mean_residual * 0.05;
        score += 15.0 + pressure;
        // If lookahead item would fit the new bin nicely, soften penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Stream progression: early on, be more willing to open bins (explore);
    // later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Slight preference for bins below mean residual (balance residuals).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too: reward proportional tightness.
            let tightness = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 25.0 * tightness;
        } else {
            // Next item cannot use leftover: penalize dead space, worse if tiny leftover.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 30.0 * (10.0 - dead);
            }
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 20.0;
    }

    // Penalize unusable residue below minimum plausible item size (interface: 1..=100, but reward vs mean).
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New empty bin candidate: only attractive when few fitting bins or huge item.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 45.0 };
        score += pressure + 10.0 * (open_bins_count as f64).sqrt();
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    } else if post_residual >= 12 && post_residual < 30 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a residual that
            // neither fits next item nor is broadly reusable.
            score += 6.0;
        }
    } else {
        // Last item: just empty the bin if possible.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when the
    // current item is large relative to mean residual or fits are poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Large items deserve a fresh bin; small items should use existing space.
        score -= 20.0 * fill_ratio;
        // If many bins are open and mean residual is high, discourage new bins.
        score += 0.15 * open_bins_count as f64;
        score += 0.10 * (mean_residual - item_size as f64).max(0.0);
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Prefer bins with residual close to item (exactness) via quadratic term.
    let waste = (bin_residual - item_size) as f64;
    score += 0.05 * waste * waste / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: minimize wasted space, with smooth non-linear shaping
    let mut score = pr * pr / cap;

    // Polynomial coupling of post-residual with stream progress:
    // early on, prefer tight fills (penalize large residuals more);
    // late, allow larger residuals since bins close out anyway.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * pr_norm * pr_norm * cap;

    // Smooth interaction: item size vs post residual (favor balanced splits)
    let balance = (item_norm * pr_norm) * cap;
    score -= 0.8 * balance * (1.0 - progress);

    // Last-chance bonus: strongly favor the single fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 3.0 + 4.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        score += 2.0 * progress;
    }

    // Crowd penalty: many open bins -> prefer consolidation (favor existing bins)
    let crowd = (open_bins_count as f64).ln() * (1.0 + mean_residual / cap);
    score += 0.6 * crowd * (pr_norm + 0.1);

    // New-bin candidate: penalize opening fresh bins unless residuals are poor
    if bin_residual == bin_capacity {
        let avg = if mean_residual.is_finite() { mean_residual } else { cap };
        score += 8.0 + 20.0 * (avg / cap) * (1.0 - progress);
    }

    // Tiny smooth tie-breaker to avoid degenerate ties
    score += 0.01 * (item_norm * (progress + 0.5));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: exact fits are perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residues are dead space.
    // Penalize residues in "dead" classes (1..=9) which few items can reuse.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 3.0 } else { 0.0 };
        score += dead * (post_residual as f64).powf(0.5);
    }

    // Modulo-10 harmonic classes: residues that are multiples of 10 are more
    // reusable (item sizes often cluster on decade boundaries).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: reward when next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Fraction of post_residual consumed by the next item.
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * frac;
        } else {
            // Next item cannot use this residue: mild penalty scaled by waste.
            score += 2.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless the item
    // is huge relative to mean residual (a fresh bin is genuinely needed).
    if bin_residual == bin_capacity {
        let mean_fit = mean_residual >= item_size as f64;
        if mean_fit && fitting_bins_count > 0 {
            score += 40.0;
        }
        // Large items early in the stream justify fresh bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 60 {
            score -= 10.0 * (1.0 - progress);
        }
    } else {
        // Prefer tighter bins: reward small post_residual relative to capacity.
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        // Spread awareness: if mean residual is large, encourage consolidation.
        if mean_residual > 30.0 {
            score -= 5.0;
        }
    }

    // Integer-division threshold: bins whose residual can hold a "half item"
    // (>= 50) remain useful; bins below that threshold are near-dead.
    if post_residual < 50 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are pure waste; penalize them quadratically, but full/zero residual is fine.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0 + 8.0;
    }
    // Unusable gap for the known next item: penalize if next item just misses.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= tightness * 12.0;

    // Open-bin pressure: discourage spreading across many bins; encourage
    // closing bins out when many are open.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., mean residual is small relative to item) or stream is early.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < item_size as f64 / bin_capacity as f64 {
            score -= 10.0; // open a fresh bin when open bins are too full
        } else {
            score += 14.0 + open_bins_count as f64 * 0.6; // keep using open bins
        }
    }

    // Mild preference to place into below-average-residual bins (denser bins).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits here afterwards: mild reward proportional to tightness.
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item would NOT fit here: penalize leaving a gap that blocks it,
            // scaled by how much of the next item is stranded.
            let stranded = (next_item_size - post_residual) as f64;
            score += 0.5 * stranded;
        }
    }

    // Penalize large dead space relative to mean residual (waste indicator).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // the item would leave a poor fit in existing bins or few bins fit.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0;
        if poor_fit || fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            score += 120.0;
        }
    }

    // Early in stream: encourage opening bins to build diverse residual pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 20.0;
    }

    // Mild penalty for using many bins when plenty already fit elsewhere.
    if fitting_bins_count > 3 && bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear penalty
    // on large dead space that is hard to reuse.
    let dead = post_residual as f64;
    score += 0.35 * (dead / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for crowding when alternatives exist.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // Extra reward if next item exactly fills the post-residual.
            if next_item_size == post_residual {
                score -= 30.0;
            }
        } else {
            // Penalize leaving post-residual that is too small for the next item
            // but large enough to be "wasted" dead space.
            if post_residual > 0 && post_residual < next_item_size {
                score += 0.25 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Global state coupling: many open bins with high mean residual suggests
    // fragmentation; encourage consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fragmentation = mean_residual / bin_capacity as f64;
    if fragmentation > 0.5 && open_bins_count > 2 {
        score -= 6.0 * fragmentation * ((open_bins_count as f64).ln() + 1.0);
    }

    // Time horizon: late in the stream, be more conservative — prefer opening
    // new bins less (residuals matter more), since fewer chances to fix mistakes.
    score *= 1.0 + 0.15 * progress;

    // Slight bias against opening a brand-new bin when any open bin can fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 12.0 + 3.0 * fitting_bins_count as f64;
        }
        // But if mean residual is very low (open bins nearly full), new bin is fine.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Small penalty for very large item in a nearly-full bin mismatch.
    if item_size as f64 > bin_residual as f64 * 0.9 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic dead-space penalty, modulated by stream progress
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth progress coupling: later in the stream, waste is more costly
    score += 30.0 * progress * norm_pr * norm_pr;

    // Lookahead: reward residual that can still host the next item (smooth polynomial)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_margin = (pr - nx) / cap;
        let usable = fit_margin.max(-1.0);
        score -= 12.0 * usable * (1.0 + usable);
    }

    // Penalize near-empty-bin usage when many bins are open (avoid bin sprawl)
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    score += is_new_bin * (8.0 + 6.0 * open_bins_count as f64 * norm_pr);

    // Last-chance fitting bonus: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild preference toward tighter bins overall (deviation from mean residual)
    score += 0.15 * (pr - mean_residual).abs();

    // Small penalty for very small items in large-residual bins (waste of capacity)
    score += 0.05 * (item_size as f64 / cap) * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // "dead zones" (mod 10 near zero) are nearly perfect fits — reward them.
    let pr = post_residual;
    let m = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if m == 0 {
        score -= 12.0; // clean multiple-of-10 leftover, reusable by typical items
    } else if m <= 3 {
        score += 6.0 + m as f64; // tiny sliver, dead space
    }

    // Integer-division threshold classes on post_residual
    let q = pr / 10;
    match q {
        0 => score += 8.0,              // leftover < 10: unusable for most items
        1 => score -= 2.0,              // 10..19: fits smallest class
        2 => score -= 5.0,              // 20..29
        3 => score -= 7.0,              // 30..39
        _ => score -= 9.0,              // large leftover: bin stays flexible
    }

    // Lookahead coupling: harmonic class of next_item_size
    if next_item_size > 0 && pr >= next_item_size {
        let nm = next_item_size % 10;
        // reward if next item exactly consumes leftover class
        if pr == next_item_size {
            score -= 25.0;
        } else if (pr - next_item_size) % 10 == 0 {
            score -= 8.0;
        }
        if nm == 0 {
            score -= 3.0; // next item is round-sized, pairs well with round residuals
        }
    } else if next_item_size > 0 {
        score += 5.0; // next item cannot follow into this bin
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: must open a new bin
        }
    }

    // Mean residual pull: prefer bins close to the mean (balanced packing)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // Stream progression: late in the stream, tighten up (waste matters more)
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * t * 0.5;

    // Slight preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small gaps that nothing can fit are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 40.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Last chance: only this bin can fit the item; strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // Pressure from many open bins: discourage spreading across bins
    // when already many are open; encourage using existing space.
    score += 3.0 * open_bins_count as f64;

    // Prefer bins whose residual is below the mean (pack the fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if the next item would fit into this bin's post_residual,
    // reward keeping this residual; if it would not fit anywhere else either,
    // slight penalty for leaving a residual the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when no open bin fits well (large residual waste avoided).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, reduced late in the stream
        // (fewer future items to benefit from consolidation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // new bin has room for the lookahead item too
        }
        if fitting_bins_count == 1 {
            score += 80.0; // never open a new bin when one open bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact/near-exact fits strongly (non-linear in post_residual).
    let pr = post_residual as f64;
    score -= (1.0 - pr / bin_capacity as f64).powi(6) * 60.0;

    // Perfect fit: zero residual is the ideal placement.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post residual, this bin is a perfect chain -> strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let prf = post_residual as f64;
        if (post_residual as u32) == next_item_size {
            score -= 90.0; // chain completes exactly
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how snugly it fits after
            let chain_residual = prf - nxt;
            score -= (1.0 - chain_residual / bin_capacity as f64).powi(5) * 40.0;
        } else {
            // next item will NOT fit here: penalize leaving a residual that is
            // too small to be useful (dead space), worse when gap is small.
            let gap = nxt - prf;
            if gap <= 20.0 {
                score += gap * 1.5; // just-missed: wasteful residual
            }
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual far below the mean wastes capacity; near/above mean is fine.
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        if ratio < 0.5 {
            score += (0.5 - ratio) * 30.0;
        } else if ratio > 1.0 {
            score -= (ratio - 1.0).min(1.5) * 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when the item fits
    // poorly everywhere (large residual elsewhere / dead-space risk).
    if bin_residual == bin_capacity {
        // neutral baseline slightly above good fits
        score += 25.0;
        if item_size >= 60 {
            score -= 15.0; // big items fine in a fresh bin
        }
        if next_item_size > 0 && next_item_size > bin_residual - item_size.min(bin_residual) {
            // fresh bin preserves room for the next item
            score -= 10.0;
        }
    }

    // Early in the stream: be slightly more willing to keep bins tidy.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // Many open bins: prefer consolidating into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty reduction on small post_residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize large dead space (post residual too big to be useful).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill bonus
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 2.0; // awkward residual zone
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Slight penalty when many alternatives exist; prefer best fit among them.
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // Next item won't fit here; penalize leaving large residual that wastes space.
            score += 0.05 * post_residual as f64;
        }
    }

    // Global state: when mean residual is high, prefer consolidating into existing bins.
    if mean_residual > item_size as f64 {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_fill = bin_capacity as f64 - mean_residual;
        let pressure = open_bins_count as f64 / (step_index as f64 + 1.0);
        if fitting_bins_count == 0 {
            score -= 25.0; // forced: no alternative
        } else if fitting_bins_count == 1 {
            score += 18.0; // an open bin is a last chance; don't open new
        } else if avg_fill > 60.0 && pressure > 0.5 {
            score -= 3.0; // bins mostly full, opening fresh is fine
        } else {
            score += 10.0; // keep consolidating into open bins
        }
    }

    // Mild time-horizon term: early in stream, slightly discourage new bins to
    // encourage packing; late in stream, neutral.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 + norm_pr * progress * 20.0
                 + (1.0 - norm_pr) * (1.0 - norm_pr) * progress * 30.0;
    score += coupling;

    // Reward tight fits (small post residual), more strongly later in stream
    score -= (1.0 - norm_pr) * (1.0 - progress) * 10.0;

    // Penalize bins with residual far from mean residual (fragmentation)
    score += ((pr - mean_residual) / cap).abs() * 8.0;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: bonus if next item fits well in post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: mildly discourage unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress - 2.0 * open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "usable" classes (divisible by common small item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        let mut usable_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                usable_bonus += 4.0;
            }
        }
        score -= usable_bonus;
        // Dead space: small odd residuals are hard to fill later.
        if pr < 10 {
            score += 25.0;
        }
    } else {
        // Perfect fit is ideal.
        score -= 40.0;
    }

    // Integer-division threshold on residual: large residual chunks are valuable.
    let chunk = pr / 25; // 0..4
    score -= chunk as f64 * 6.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot follow here; slight penalty proportional to overflow.
            score += (next_item_size - pr).min(30) as f64 * 0.3;
        }
        // Harmonic class match between next item and residual.
        if pr > 0 && next_item_size % 10 == 0 && pr % 10 == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin is a fallback; prefer it only when
    // post_residual would be large and mean residual across bins is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - progress * 10.0 - mean_residual * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += (bin_capacity - next_item_size) as f64 * 0.1;
        }
        if item_size >= 60 {
            score -= 10.0; // big items fine in fresh bins
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the known next item are semi-dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward when the gap exactly hosts the next item (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 15.0 + 4.0 * open_bins_count as f64;
        // But if all open bins would leave tiny dead space, new bin becomes attractive.
        if post_residual > 0 && post_residual < 10 {
            score -= 90.0;
        }
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in the stream, tighten up: prefer filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact fits (dead space zero).
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a perfect chain placement -- reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves some slack: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: the leftover is likely dead space.
            // Penalize more if leftover is small (unusable) relative to item range.
            let leftover = post_residual as f64;
            if leftover < 10.0 {
                score += 60.0;
            } else {
                score += 0.5 * leftover;
            }
        }
    } else {
        // Last item: pure tightness packing.
        score -= 100.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: prefer bins whose residual is below the mean
    // (filling fuller bins first keeps many partially-filled bins available).
    score += 0.6 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.3 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate: opening a fresh bin is only attractive early in the
    // stream or when the current fit is very poor. Otherwise penalize it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Penalize new bins more as stream progresses; allow it for large items
        // or when many open bins already exist (spread load).
        score += 90.0 * progress - 25.0 * fit_quality - 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for leaving little dead space.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit_gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - next_fit_gap / (bin_capacity as f64));
    } else if next_item_size > post_residual {
        // Post-residual too small for next item: penalize creating dead space
        // that the lookahead cannot use, scaled by how dead it is.
        if post_residual > 0 {
            score += 8.0 * (post_residual as f64) / (next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // encourage consolidation into existing bins rather than opening new ones.
    if bin_residual != bin_capacity {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.05 * consolidation;
        score -= 0.5 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize mildly so we only open when fits are poor,
        // but reward when existing residuals are all small (nothing useful to pack into).
        score += 15.0;
        if mean_residual < 10.0 {
            score -= 12.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Waste penalty proportional to how much capacity is locked into unusable space.
    if post_residual > 0 && post_residual < 10 {
        // Tiny slivers are nearly useless dead space.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear penalty on residual waste, growing with stream progress.
    let norm_pr = pr / cap;
    score += 18.0 * norm_pr * norm_pr * (0.4 + 0.8 * progress);

    // Reward exact-looking fit with lookahead item (post_residual == next_item_size).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = 1.0 - ((pr - nxt).abs() / cap);
        if match_term > 0.0 {
            score -= 14.0 * match_term * match_term;
        }
        // Penalize residual too small for the next item (dead space).
        if pr < nxt {
            score += 10.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0 * (1.0 - 0.5 * progress);
    }

    // Deter opening a new bin when decent open bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 8.0 + 3.0 * openness + 12.0 * (1.0 - progress);
        // Allow new bin only if this item is huge relative to mean residual.
        let fit_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        score -= 20.0 * fit_gap;
    } else {
        // Slightly prefer tighter-than-average bins.
        score -= 4.0 * ((mean_residual - bin_residual as f64) / cap).clamp(-1.0, 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "useful"
    // classes (multiples of common small sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        let mut class_bonus = 0.0;
        for d in [10u32, 20, 25, 50].iter() {
            if pr % d == 0 {
                class_bonus += 6.0;
            }
        }
        // Very small dead space is excellent.
        if pr <= 5 {
            class_bonus += 12.0;
        } else if pr <= 10 {
            class_bonus += 8.0;
        }
        // Dead zones: residuals that few item sizes can use are penalized.
        // Integer-division threshold: residual in (10,20) or (50,60) hard to fill.
        if (pr > 10 && pr < 20) || (pr > 50 && pr < 60) || (pr > 60 && pr < 70) {
            class_bonus -= 7.0;
        }
        score -= class_bonus;
    } else {
        // Perfect fill.
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 5.0 + (pr - next_item_size) as f64 * 0.05;
        } else {
            // Next item cannot use this residual: penalize wasted space proportionally.
            score += 0.10 * pr as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is discouraged unless
    // current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0 + fragmentation * 0.3;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // Many open bins already: prefer consolidation into existing bins.
        if open_bins_count > 4 {
            score += 8.0;
        }
    }

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Mild preference for bins below mean residual (balancing).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Assume minimum realistic item size ~10; gaps below that are dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // small but nonzero gap is wasted
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit is ideal
    }

    // Reward tight fits relative to residual (low waste ratio)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness * tightness;

    // Penalize creating a gap that the next item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward a gap exactly usable by the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += 3.0 * pressure * (1.0 - progress) * (mean_residual / bin_capacity as f64);

    // New-bin candidate: neutral-ish baseline, penalize mildly so it only wins
    // when existing bins are genuinely poor fits (high dead-space risk).
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
        // but if item is large, a fresh bin is attractive
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact matches between post_residual and next item size.
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 2.0
        };
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
    }

    // Penalize residuals far from the mean residual (relative waste).
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * mean_gap;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 && post_residual < item_size {
            score += 10.0;
        }
    }

    // Slight preference for tighter fits overall.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post_residual), with smooth non-linear shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, waste matters less (quadratic term small);
    // late in the stream, penalize large residuals more aggressively.
    let waste_coupling = pr_norm * pr_norm * (0.5 + 2.5 * progress) * cap;
    score += waste_coupling;

    // Cubic interaction: dead space penalty grows super-linearly as stream progresses
    score += pr_norm.powi(3) * cap * progress * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: reward leaving room for the next item if it fits post-placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - ((pr - nxt) / cap).abs();
            score -= 8.0 * snug * (0.5 + progress);
        } else {
            // next item won't fit here; slight penalty scaled by how much it misses
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Favor bins tighter than average (concentrate waste)
    score += 2.0 * (mean_residual - pr) / cap;

    // New-bin candidate: make empty bin attractive only when current fit is bad
    if bin_residual == bin_capacity {
        score = pr + 15.0 + 20.0 * progress - 10.0 * (1.0 - pr_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bucket post_residual into classes of 10.
    // Residuals that are multiples of small item sizes are reusable; penalize others.
    let class = post_residual / 10;
    let class_bonus = match class {
        0 => -12.0,                       // near-perfect fill
        1 => -6.0,                        // very tight leftover
        2 => -2.0,                        // usable for small items
        3 => 0.0,
        4 => 1.5,
        _ => 3.0,                         // large dead space
    };
    score += class_bonus;

    // Penalize awkward remainders (post_residual % 10 in 7..9 wastes space).
    let rem = post_residual % 10;
    if rem >= 7 { score += 2.5; }
    if rem == 0 && post_residual > 0 { score -= 2.0; }

    // Exact fill is ideal.
    if post_residual == 0 { score -= 15.0; }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Lookahead: reward if next item fits into the resulting residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0 + (post_residual - next_item_size) as f64 / 20.0;
        } else {
            score += 1.0;
        }
    }

    // New-bin candidate: keep it competitive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (mean_residual / bin_capacity as f64) < 0.35;
        let pressure = open_bins_count as f64 / 8.0;
        if crowded && fitting_bins_count > 0 {
            score -= 6.0 + pressure;
        } else {
            score += 4.0 + pressure;
        }
    }

    // Mild preference for packing into fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * (2.0 + 2.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot host even the
    // smallest plausible item are pure waste — penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 6.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave a gap matching the lookahead item
    // (or large enough to be reusable later).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            // gap too small for the known next item: extra penalty
            score += 10.0;
        }
    }

    // Tight-fit bonus relative to bin residual: prefer filling fuller bins.
    let fill_ratio = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 1.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, discounted when
        // no existing bin offers a decent fit.
        score = 25.0 + pressure * 0.6;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if post_residual < 10 && post_residual > 0 && item_size < bin_capacity {
            score += 40.0; // opening a bin with a doomed tiny gap is bad
        }
    } else {
        // Existing bins: slight bonus if this is the last chance bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        score += pressure * 0.1;
        // Penalize choosing a much-fuller-than-average bin poorly or a
        // much-emptier-than-average bin when mean residual is high.
        score += 0.15 * ((bin_residual as f64) - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * bin_capacity as f64;

    // 2-step lookahead: reward if next item fits into post_residual (chain placement).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here — strong reward proportional to how well it fills remainder.
            score -= 18.0 + 0.25 * next_item_size as f64;
        } else {
            // Next item won't fit here — penalize wasted chain opportunity,
            // scaled by how close it was (near-miss is worse).
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 12.0 + 0.6 * (20.0 - gap);
            } else {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins rather than new ones.
    score -= 0.4 * open_bins_count as f64;

    // Prefer bins whose residual deviates favorably from the mean:
    // bins with less residual than mean are more "committed" — prefer them.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference for using older/more filled bins early vs late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Penalize leaving dead space that nothing (min size 1..10 typical) can use.
    if post_residual < 10 && post_residual > 0 {
        score -= 6.0; // near-perfect fill — actually reward this
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic horizon
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize dead space: small post_residual that cannot host the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // wasted residual relative to lookahead need
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // reward bins that can also host the next item
            score -= 0.25 * next_item_size as f64 * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of opening a bin
        score += 30.0;
        if fitting_bins_count <= 1 {
            // opening a new bin is reasonable if few alternatives
            score -= 25.0;
        }
        if post_residual < 10 {
            score -= 15.0; // perfect fit in fresh bin
        }
        // late in stream, prefer closing out open bins
        score += 10.0 * progress;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first)
    score -= 0.10 * (mean_residual - bin_residual as f64);

    // Mild pressure to fill bins tightly as stream progresses
    score += progress * post_residual as f64 * 0.20;

    // Reward using bins that become exactly full
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 5 {
        score -= 8.0;
    }

    // Slight penalty for very fragmented placement (item barely fits)
    if item_size as f64 > 0.9 * bin_residual as f64 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = post / cap;
    let next = next_item_size as f64;

    // Base: quadratic penalty on post residual (dead space), softened for small residuals.
    let mut score = post * post / cap;

    // Smooth cubic interaction: residual usefulness decays with stream progress.
    let decay = (1.0 - progress) * (1.0 - progress);
    score -= 18.0 * fit_norm * decay * cap * 0.01;

    // Reward tight fits with smooth saturating term.
    let tightness = 1.0 - fit_norm;
    score -= 6.0 * tightness * tightness;

    // Lookahead coupling: smooth polynomial affinity between post residual and next item.
    if next > 0.0 {
        let affinity = (post - next) / cap;
        score += 10.0 * affinity * affinity;
        score -= 4.0 * affinity; // slight bonus when next item fits snugly
    }

    // Penalize last-chance bins less (avoid opening new bins unnecessarily).
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
    }

    // Mild global pressure: when many bins are open relative to progress, prefer filling.
    score += 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * fit_norm * cap * 0.02;

    // Mean residual divergence penalty: smooth deviation from average slack.
    score += 0.5 * (post - mean_residual).abs();

    // New-bin candidate: make empty bin attractive only when post residual of fill is poor.
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets by capacity fractions
    let cap = bin_capacity as f64;
    let quarter = (bin_capacity / 4) as u32;
    let half = (bin_capacity / 2) as u32;

    // Penalize dead space in low-harmonic classes (tiny unusable residuals)
    if post_residual < quarter {
        score += 12.0 * (quarter - post_residual) as f64 / cap;
    }
    // Reward landing in the "sweet" middle-harmonic class
    if post_residual >= quarter && post_residual <= half {
        score -= 6.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item sizes are reusable
    if post_residual > 0 && next_item_size > 0 {
        if post_residual % next_item_size == 0 {
            score -= 8.0; // perfect future fit possible
        } else if next_item_size <= post_residual {
            score -= 3.0;
        } else {
            score += 4.0; // next item cannot use this bin anyway
        }
    }

    // Integer-division threshold: classify post_residual into capacity/10 slots
    let slot = post_residual / (bin_capacity / 10).max(1);
    score -= slot as f64 * 1.5;

    // Last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer tighter bins relative to current mean residual
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // Early stream: be conservative, mildly favor opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    // Slight penalty when many bins already open (encourage consolidation)
    score += open_bins_count as f64 * 0.02;

    // New-bin candidate baseline: empty bin gets neutral score with a mild bias
    if bin_residual == bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small for any
    // future item (min size 1..100 unknown, assume small items >=10 possible)
    // are pure waste. Penalize "fragile" gaps hard.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        // unusable dead space
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // risky narrow gap: only tiny items can use it
        score += 15.0 + pr * 0.5;
    }

    // Reward tight fits (small post_residual) superlinearly.
    score -= 25.0 * (1.0 - pr / bin_capacity as f64).powi(6);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item cannot fit in post_residual but fits elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chain fit
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 10.0; // stranded residual
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins with below-mean residual (consolidate emptier bins).
    score += (pr - mean_residual) * 0.3;

    // Slight progression bias: later in the stream, be more frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // New-bin candidate: neutral-ish baseline so it only wins when open bins score badly.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins where the next item fits snugly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item fits this bin but not after this placement: mild penalty
        score += 8.0;
    } else if next_item_size > 0 {
        // next item won't fit here at all: small bonus for using this bin now
        score -= 4.0;
    }

    // Penalize dead space that is too small for the minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer tight fits relative to mean residual of open bins
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, consolidate: discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early stream -> prefer tight fits less aggressively, late -> maximize fill
    let t = step_index as f64 / total_items.max(1) as f64;

    // Tightness of fit: reward small post_residual non-linearly
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Reward filling bins with large residuals relative to mean (consolidate space)
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        score -= 6.0 * (rel - 1.0);
    }

    // Lookahead: if next item fits exactly in post_residual, strong bonus
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual - next_item_size;
        score -= 10.0 * (1.0 - chain as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty for leaving awkward residue
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Penalize spreading across many open bins when few fit
    if fitting_bins_count <= 2 && open_bins_count > 2 {
        score -= 4.0;
    }

    // New-bin candidate: neutral-ish base, prefer it only when all fits are bad
    if bin_residual == bin_capacity {
        // Opening cost grows with stream progress (sunk bins already committed)
        score = 40.0 + 20.0 * t + 2.0 * open_bins_count as f64;
        // But if next item is large, fresh bin is attractive
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Late-stage: reward near-perfect packing more strongly
    score -= 12.0 * t * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(3));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Normalized post-residual (dead space fraction)
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling: dead space penalized super-linearly,
    // more strongly later in the stream when compacting matters.
    let dead_penalty = pr_norm * pr_norm * (0.5 + 2.0 * progress) * cap * 0.5;
    score += dead_penalty;

    // Reward excellent fits (post residual below item size / small absolute gap)
    let fit_quality = 1.0 - (pr / cap); // high when pr small
    let fit_reward = fit_quality * fit_quality * (10.0 + 20.0 * progress);
    score -= fit_reward;

    // Last-chance bonus: only one bin fits this item -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 40.0 * progress;
    }

    // Lookahead: if next item would fit exactly in post_residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (nx - pr).abs() < 1.0 {
            score -= 25.0;
        } else if nx <= pr {
            // next item fits in leftover: mild reward scaled by how well it fills
            let fill = nx / pr;
            score -= 10.0 * fill * (1.0 - progress);
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a "dirty" bin; prefer cleaning it up when mean residual is high.
    let bin_res_f = bin_residual as f64;
    let residual_gap = (mean_residual - bin_res_f) / cap;
    score -= residual_gap * residual_gap * mean_residual * 0.5;

    // New-bin candidate: neutral-ish baseline that scales with open bins count
    // and stream progress, so a new bin is chosen only when no open bin offers
    // a competitive (low) score.
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + 0.1 * open_bins_count as f64;
        // still allow lookahead advantage for a fresh bin
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if (nx - pr).abs() < 1.0 {
                score -= 20.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "usable" for
    // typical item sizes (multiples of 5, 10) are rewarded; awkward residues
    // (dead space) are penalized.
    let post = post_residual as i64;
    let usable = if post == 0 {
        4.0 // perfect fit is best
    } else if post % 10 == 0 {
        3.0
    } else if post % 5 == 0 {
        2.0
    } else if post % 2 == 0 {
        1.0
    } else {
        0.0
    };
    score -= usable * 4.0;

    // Integer-division thresholds: penalize post_residual in awkward bands
    // (too small for the smallest item but nonzero -> pure dead space).
    if post > 0 && post < 10 {
        score += 15.0;
    } else if post >= 10 && post < 20 {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward heavily; if next item cannot possibly fit anywhere else, keep bin.
    if next_item_size > 0 {
        if post == next_item_size as i64 {
            score -= 12.0;
        } else if post > next_item_size as i64 {
            score -= 3.0;
        } else {
            // next item won't fit here; mild penalty so a roomier bin wins
            score += 4.0;
        }
    }

    // New-bin candidate handling: fresh bin has full residual. Prefer keeping
    // it closed early on when decent fits exist, but allow opening when the
    // stream is long and current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // open new bin when existing bins are tight/fragmented or few fit
        let pressure = fragmentation * 0.5 + (fitting_bins_count as f64).recip() * 0.3 + progress * 0.2;
        score += 30.0 - pressure * 40.0;
    }

    // Tight-fit reward: item fills most of the residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 8.0;

    // Slight preference for larger residual bins when all else equal.
    score -= (bin_residual as f64) * 0.05;

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // ---- Strict dead-space avoidance ----
    // A perfect fit (post_residual == 0) is heavily rewarded. Small nonzero gaps
    // (1 .. DEAD_THRESHOLD-1) are treated as likely-dead space and penalized
    // proportionally, so the packer prefers leaving a usable gap of
    // >= DEAD_THRESHOLD over a tight-but-unusable sliver.
    const DEAD_THRESHOLD: u32 = 10;
    const DEAD_PENALTY: f64 = 20.0;
    const PERFECT_FIT_BONUS: f64 = 1000.0;

    if post_residual == 0 {
        score -= PERFECT_FIT_BONUS;
    } else if post_residual < DEAD_THRESHOLD {
        score += DEAD_PENALTY * (DEAD_THRESHOLD - post_residual) as f64;
    }

    // ---- Lookahead (k=2) coupling ----
    // Reward bins whose leftover can also host the next item; an exact
    // two-item chain (post_residual == next_item_size) is especially valuable.
    // Mildly penalize bins that become unusable for the immediately next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == post {
            score -= 250.0;
        } else if nxt < post {
            score -= 40.0 * (nxt / post);
        } else {
            score += 15.0;
        }
    }

    // ---- Consolidation pressure via mean residual ----
    // Prefer bins that are fuller than the current average (negative residual
    // gap), and slightly penalize emptier-than-average bins. This steers
    // items toward bins that are already well filled.
    let fill_deficit = mean_residual - bin_residual as f64;
    if fill_deficit > 0.0 {
        score -= 2.0 * fill_deficit.min(50.0);
    } else {
        score += (-fill_deficit).min(50.0);
    }

    // ---- New-bin candidate vs. last-chance open bin ----
    if is_new_bin {
        if fitting_bins_count == 0 {
            // No open bin can host this item: the fresh bin is the only option.
            score -= 500.0;
        } else {
            // Opening a new bin competes with usable open bins: penalize it,
            // with pressure growing as more bins are already open and as the
            // stream progresses. Large items get partial relief (they are less
            // wasteful in a fresh bin), small items should fill existing gaps.
            let size_relief = 1.0 - 0.5 * (item_size as f64 / cap);
            let open_pressure = (60.0 + 10.0 * open_bins_count as f64) * (0.5 + 0.5 * progress);
            score += open_pressure * size_relief;
        }
    } else if fitting_bins_count == 1 {
        // This is the only open bin that fits: using it avoids opening a new
        // bin, which is the primary objective. Reward scales with open-bin
        // count so late-stream consolidation is favored even more.
        score -= 60.0 + 4.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 40.0;

    // 2-step lookahead: reward when next item exactly fills the new post_residual,
    // penalize when next item would be stranded by leftover dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 20.0 - slack_after_next as f64 * 0.4; // good chain, tighter better
        } else {
            // next item won't fit here; dead space penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6;
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // residual is wasteful when other bins are similarly loose.
    let mean_gap = post_residual as f64 - mean_residual;
    score += mean_gap * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // no open bin fits well (large post_residual for existing bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Neutral base score for a fresh bin; becomes less attractive later.
        score = 30.0 + progress * 20.0;
        if fitting_bins_count == 0 {
            score = 0.0; // must open new bin
        }
    }

    // Late-stream consolidation: favor filling existing bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on leftover space.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose leftover can host the next item (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * (next_item_size as f64);
        } else if post_residual > 0 && post_residual < 10 {
            // Tiny dead space is nearly useless; slight penalty.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Penalize opening a bin when alternatives exist,
            // unless mean residual is large (open bins are roomy but fragmented).
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 30.0 - 15.0 * progress;
            if mean_residual > (1.5 * item_size as f64) {
                score -= 10.0; // fragmentation: new bin may be cleaner
            }
        } else {
            // No open bin fits: new bin is necessary; make it attractive.
            score -= 25.0;
        }
    }

    // Mild preference for bins below mean residual (consolidating space).
    if !is_new_bin {
        score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Late in the stream, avoid leaving large residuals (less time to fill them).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic bonus for small post_residual
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr).powi(2) / (bin_capacity as f64).powi(2) * 12.0;

    // Non-linear coupling of post_residual with stream progress:
    // early on tolerate loose fits; late in stream demand tightness.
    let tightness = pr / bin_capacity as f64;
    score += tightness * tightness * (1.0 - progress) * 8.0;
    score += tightness * progress * 15.0;

    // Penalize dead space relative to mean residual (smooth coupling)
    let dev = pr - mean_residual;
    score += dev * dev * 0.05 - dev * 0.15;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (0.5 + progress);
    }

    // Lookahead: if next item can use the post_residual, reward leaving useful space
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 3.0 * (-gap / bin_capacity as f64);
        }
    }

    // Slight preference for compacting into fewer bins when many open
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - tightness);

    // Mild pressure against opening new bins mid-stream
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual ---
    // Residuals divisible by common item sizes (or near-halves/quarters of capacity)
    // are "usable" classes; odd/dead residues are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual exactly divisible by 10 (harmonic decade class) -> reward
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class 2: post_residual divisible by 5 but not 10 -> mild reward
    else if post_residual % 5 == 0 {
        score -= 2.0;
    }
    // Class 3: odd residual -> dead-space penalty (can never pair with even item)
    if post_residual % 2 == 1 {
        score += 3.0;
    }

    // Integer-division threshold bands on post_residual
    let band = post_residual / 10; // which decade band the residual lives in
    match band {
        0 => score += 12.0,      // 0..9: nearly full bin, waste is tiny anyway
        1 => score += 4.0,       // 10..19: small but often unusable sliver
        2 => score -= 1.0,       // 20..29
        3 => score -= 3.0,       // 30..39: sweet spot (fits a 30-class item)
        4 => score -= 4.0,       // 40..49: fits half-class items
        5 => score -= 2.0,       // 50..59
        _ => {}
    }

    // Fractional capacity coupling: residual close to half capacity is valuable
    let half = cap / 2.0;
    let dist_half = (pr - half).abs();
    score += dist_half * 0.08;

    // --- Lookahead harmonic coupling (k=2) ---
    if next_item_size > 0 {
        // Perfect lookahead fit: next item exactly fills post_residual
        if next_item_size as f64 == pr {
            score -= 15.0;
        }
        // Next item fits into post_residual with harmonic residue
        else if next_item_size <= post_residual {
            let r2 = post_residual - next_item_size;
            if r2 % 10 == 0 {
                score -= 5.0;
            } else if r2 % 2 == 0 {
                score -= 1.5;
            } else {
                score += 2.0; // leaves an odd dead residue
            }
            // chain: two-step exact fill of capacity
            if item_size + next_item_size as u32 == bin_residual {
                score -= 4.0;
            }
        }
        // Next item does NOT fit here: residual below next item is dead unless reusable
        else {
            let gap = next_item_size as f64 - pr;
            if gap > 20.0 {
                score += 2.0; // large unusable gap for the upcoming item
            }
        }
    }

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0; // strongly prefer using the only bin that fits
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty bin baseline: slightly worse than a good existing fit,
        // but better than squeezing into a nearly-full bin.
        score = cap - item_size as f64; // = post_residual of a fresh bin
        score += 10.0;                 // mild reluctance to open new bins
        if fitting_bins_count == 0 {
            score -= 10.0; // no open bin fits: must open
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 3.0; // big item coming: fresh bin is attractive
        }
    }

    // --- Stream progression: late in the stream, consolidate aggressively ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - pr) * 0.05;

    // Prefer bins tighter than the current mean residual
    score += (mean_residual - pr) * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strongly reward zero post_residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small nonzero gaps are nearly unusable.
        let gap = post_residual as f64;
        if gap <= 10.0 {
            score += (11.0 - gap) * 20.0; // severe penalty for tiny unusable gaps
        } else {
            // Mild decay penalty: larger gaps are less harmful per unit.
            score += 200.0 / gap;
        }
        // If next item could exactly fill the resulting gap, reward this placement.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 300.0;
        }
        // Penalize if the gap cannot hold the lookahead item but could have.
        if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
            score += 50.0;
        }
    }

    // Pressure to close bins: fewer open bins preferred unless fit is excellent.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize deviating from mean residual (avoid fragmenting many bins).
    score += (bin_residual as f64 - mean_residual).abs() * 0.5;

    // New-bin candidate: penalize opening a bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 5.0;
        // But allow a new bin if this item is large and would leave a bad gap elsewhere.
        if item_size > bin_capacity / 2 && post_residual == 0 {
            score -= 500.0;
        }
    }

    // Late-stream tightening: be more conservative as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += gap * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual nonlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 40.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        if leftover == 0 {
            score -= 25.0; // perfect 2-item chain
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post_residual too small for next item: penalize dead space, scaled by how close it came.
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins tighter than mean are attractive.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: avoid wasting the only fitting bin on a loose fit.
    if fitting_bins_count == 1 && post_residual > bin_capacity / 4 {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when nothing fits well; make empty bin mildly unattractive.
    if bin_residual == bin_capacity {
        score += 5.0;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of bin consumed by this item
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fit_ratio;

    // Penalize large dead space nonlinearly (small residuals are good)
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead * dead;

    // Lookahead: if next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how well it fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // next item won't fit here; slight penalty if we leave a big hole
            score += 10.0 * dead;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: prefer the one closest to a perfect fit (handled via post_residual),
    // but add mild penalty to spread pressure when bins are plentiful
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state coupling: if mean residual is high, encourage consolidating into
    // existing bins rather than opening new ones
    score -= 0.15 * mean_residual;

    // New-bin candidate logic: brand-new empty bin
    if bin_residual == bin_capacity {
        // Early in stream: opening new bins is cheap and flexible
        let open_bonus = 20.0 * (1.0 - progress);
        // Penalize when other bins already fit the item (avoid bin explosion)
        let fit_penalty = if fitting_bins_count > 0 { 35.0 } else { 0.0 };
        // Penalize more when many bins are already open
        let count_penalty = 1.5 * open_bins_count as f64 * progress;
        score += fit_penalty + count_penalty - open_bonus;
        // If item is huge relative to capacity, new bin is fine
        score -= 15.0 * fit_ratio;
    }

    // Late stream: tighten up, prefer filling existing bins
    score += 15.0 * progress * dead;

    // Small tie-breaking preference for bins with residual near item size
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = (item_size as f64 / bin_residual as f64).min(1.0);
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize waste relative to mean residual across open bins
    score += 0.3 * (pr - mean_residual).abs();

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for proliferating open bins early on
    score += 2.0 * open_bins_count as f64 * (1.0 - progress) * 0.1;

    // New-bin candidate: prefer it only when no open bin gives a good fit
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes mod 10 and integer-division bands.
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let band = (pr / 10) as f64; // 0..10

    // Reward exact fits strongly.
    if pr == 0 {
        score -= 200.0;
    } else {
        // Dead-space penalty grows for small unusable leftovers (<10, min item size).
        if pr < 10 {
            score += 150.0;
        }
        // Fractional-capacity coupling: leftover as fraction of capacity.
        let frac = pr as f64 / cap;
        score += 40.0 * frac * frac;

        // Harmonic class logic: post_residual divisible by 10 aligns with typical
        // item granularity, making the space reusable -> reward it.
        if pr % 10 == 0 {
            score -= 8.0 * band.min(10.0);
        } else {
            score += class10 * 1.5;
        }

        // Lookahead coupling: can next item fit into the post residual?
        if next_item_size > 0 {
            if (next_item_size as u32) <= pr {
                // Reward proportionally to how well next item fills the remainder.
                let fill = next_item_size as f64 / pr as f64;
                score -= 30.0 * fill;
                // Harmonic match: next item size class equals post_residual class.
                if pr % 10 == next_item_size % 10 {
                    score -= 10.0;
                }
            } else {
                // Leftover too small for the known next item: penalize.
                score += 12.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the current item leaves a bad remainder elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score = (bin_capacity - item_size) as f64 + 35.0;
        // Open a new bin early in the stream (builds inventory of bins) or when
        // the item would leave a tiny dead remainder in any existing bin.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 45.0 * (1.0 - progress);
        if post_residual < 10 && !is_new_bin {
            score -= 100.0;
        }
        // If many bins fit the item, opening new is less urgent.
        score += 8.0 * fitting_bins_count as f64;
        // If mean residual is high, prefer reusing existing bins.
        score += 0.6 * mean_residual;
        // Lookahead: new bin can host next item too if large item stream.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0;
        }
    }

    // Mild penalty for spreading across many open bins when residuals are similar.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps left after placement are nearly unusable
    // (items are >= 1, but typical small items still struggle with < 10 gaps).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0; // heavy penalty for dead space
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills the post_residual,
    // this placement is ideal.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use the leftover gap -> dead space is confirmed waste.
        score += (post_residual as f64).min(9.0) * 3.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate handling: an empty bin is only attractive when the item
    // is large (little room to waste) or no good existing fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize new bins for small/medium items; large items are fine.
        score += (1.0 - fill_ratio) * 30.0;
        // But if existing bins would leave big dead space, new bin becomes viable:
        // reward new bin when item is huge.
        if item_size >= 90 {
            score -= 60.0;
        }
        // Slight discount late in the stream to consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    // to consolidate fragmentation.
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: reward if next item fills post_residual exactly
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Perfect chain: this item leaves exactly room for next item
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving space that next item cannot use well
        if next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Penalize dead space relative to mean residual (waste coupling)
    let dead = post_residual as f64;
    if dead > mean_residual {
        score += 0.3 * (dead - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - dead);
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild pressure against opening new bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless post_residual extremely small (rare)
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    // Small structural term: prefer bins with less residual overall (tight packing)
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), especially if the next item can use the leftover.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // leftover is usable by lookahead item: strong reward
            score -= 12.0 + 0.35 * (post_residual as f64);
        } else {
            // leftover is dead space relative to next item: penalize small unusable gaps
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: only bin that fits the item; avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Mild penalty for spreading across many open bins early in the stream.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins whose residual is already below average (consolidate tightness).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: usually high post_residual already; add slight penalty so it's
    // chosen only when fits are truly bad (large dead space in all open bins).
    if bin_residual == bin_capacity {
        score += 6.0;
        // allow opening a new bin if the item would leave a very poor fit elsewhere
        if post_residual < 10 && item_size >= 90 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), non-linearly scaled.
    let mut score = (pr / cap).powf(1.6) * cap;

    // Smooth interaction: post_residual coupled with stream progress.
    // Late in the stream, dead space becomes more costly.
    score += pr * (0.15 + 0.85 * progress * progress) * 0.5;

    // Reward filling bins well: item_size relative to residual, smooth polynomial.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * fill * 12.0;

    // Penalize bins whose post_residual deviates from mean residual
    // (prefer bins near the packable "sweet spot" of remaining space).
    let dev = pr - mean_residual;
    score += 0.08 * dev * dev / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    } else if fitting_bins_count > 0 {
        // Mild penalty spreading across many candidates to break ties by fit.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (1.0 - gap / cap).max(0.0).powi(3);
        // Penalize leaving residuals that are awkwardly small for the next item.
        if pr < next_item_size as f64 {
            score += 6.0 * (1.0 - pr / cap);
        }
    }

    // Slight preference to keep open bin count low early, allow spreading later.
    score += open_bins_count as f64 * 0.4 * (1.0 - progress);

    // New-bin candidate handling: empty bin gets neutral-ish score so that
    // only genuinely poor fits among open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 10.0 * (1.0 - progress);
        // If no open bin fits tightly, opening new bin is attractive.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 >= cap * 0.9 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item-size classes (10/20/25/50) are more reusable -> reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 7.0; }
        // Dead-space penalty: unusably small residuals (pr < 10) are waste
        // unless zero. Quadratic penalty on tiny residuals.
        if pr < 10 {
            score += (10 - pr) as f64 * (10 - pr) as f64 * 0.8;
        }
    }

    // Harmonic coupling with next item: if next item fits exactly into the
    // post residual, this is a chained perfect fit -> strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // harmonic classes of the leftover slack
            if slack % 10 == 0 { score -= 6.0; }
            if slack % 25 == 0 { score -= 4.0; }
            score += slack as f64 * 0.15;
        } else {
            // next item cannot use this residual at all -> mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: brand-new empty bin should only win when the item
    // is large or all open fits are poor. Penalize opening new bins mildly,
    // scaled by stream progression and current open-bin count.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // Large items pair well with fresh bins (room for lookahead)
        if item_size >= 50 { score -= 10.0; }
    }

    // Tight-fill reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Prefer bins with residual close to the item (tight fit) using
    // integer-division thresholds on bin_residual.
    let q = bin_residual / 25; // coarse class of available space
    match q {
        0 => score += 4.0,   // nearly full bin, tight placement good
        1 => score -= 2.0,
        2 => score -= 1.0,
        _ => score += 1.0,   // mostly empty bin, deprioritize
    }

    // Mean-residual coupling: placing into a bin far below mean residual
    // balances the portfolio of open bins.
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post_residual (tight fit).
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals that are too small to be useful later
    // are pure waste. Treat residuals below the minimum useful threshold (assume
    // small items ~10) as dead space and penalize quadratically.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * (dead_threshold - pr) * 3.0;
    }

    // Perfect fit bonus: strongly reward filling the bin completely.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets a
    // penalty proportional to open_bins_count).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 8.0;
        // But if mean residual across open bins is tiny, opening fresh bin
        // is attractive: relieve that penalty.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // If no open bin leaves useful room and next item is large, new bin ok.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Lookahead: reward placing current item so that the next item still fits
    // in this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Dead space relative to the next item's need.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Mild preference for using emptier bins when few bins are open
    // (keep large residuals consolidated for future big items).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (small post_residual).
    let post = post_residual as f64;
    score = post * post / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward when the next item fits exactly
    // into the post_residual (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if nxt <= post {
            // Next item fits: reward proportional to how snugly.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            if diff < 1.0 {
                score -= 40.0; // perfect chain bonus
            }
        } else {
            // Next item would NOT fit here: penalize leaving awkward space
            // that is too small for the next item (dead space risk).
            score += 12.0 * (1.0 - post / nxt);
        }
    }

    // Relative-to-mean-residual coupling: bins with residual far from the
    // mean are either hoarders or nearly full; normalize placement.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // early in the stream or when current bin fit is terrible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline with mild penalty so real fits win,
        // but allow opening when post_residual of others is wasteful.
        score = 55.0 + 30.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) > 0.9 * bin_capacity as f64 {
            score -= 20.0; // big next item: fresh bin is fine
        }
    }

    // Penalize creating tiny unusable slivers (< 10 units dead space),
    // unless it was the last fitting bin.
    if post > 0.0 && post < 10.0 && fitting_bins_count > 1 {
        score += 20.0;
    }

    // Many open bins: encourage closing them out (prefer fuller bins).
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_capacity as f64 - post) / 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared residual penalty amplified for near-perfect fits.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 40.0;

    // Perfect-fit bonus (residual unusable for min-size items anyway).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chaining),
    // penalize if this placement leaves residual too small for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else {
            score += 8.0;
            // Extra penalty if this bin was the only fitting option (last chance).
            if fitting_bins_count == 1 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidating into existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > (item_size as f64) {
        score -= 6.0;
    }

    // Time horizon: late in the stream, waste matters more; be conservative.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate (empty bin): keep it neutral-ish so it only wins
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * (1.0 + 0.3 * progress)
            - if next_item_size > 0 && next_item_size <= bin_capacity { 5.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Non-linear penalty on large dead space, sharpened as stream advances.
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits: subtract for small post residual (smooth exponential).
    score -= 25.0 * (-pr / 12.0).exp();

    // If this is the only fitting bin, strongly favor using it (last chance).
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Penalize bins far from mean residual (prefer balanced residual profile),
    // scaled smoothly by number of open bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (open_bins_count as f64).ln().max(1.0);

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (-gap / 10.0).exp();
        // Penalize leaving residual just under the next item (unusable wedge).
        if pr < next_item_size as f64 {
            score += 8.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // New-bin candidate: keep it neutral-ish, slightly worse than a decent fit,
    // but attractive when open bins would waste much space.
    if bin_residual == bin_capacity {
        score = cap - 0.5 * mean_residual * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Small post-residuals (tight fits) are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class index via integer division thresholds (harmonic classes of C):
    // class 0: <=10 (perfect dead space), 1: <=25, 2: <=50, 3: >50
    let class = if post_residual <= 10 { 0 } else if post_residual <= 25 { 1 } else if post_residual <= 50 { 2 } else { 3 };
    score -= (3 - class) as f64 * 12.0; // reward tight classes strongly

    // Non-linear tightening bonus: quadratic reward for small residuals
    score -= (1.0 - frac) * (1.0 - frac) * 20.0;

    // Exact-fill perfection
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic coupling with next item: if the next item exactly fills the
    // post-residual, this bin becomes perfect — big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // next item fits: reward proportional to how well it fills
            let nf = next_item_size as f64 / pr;
            score -= nf * 15.0;
        } else {
            // next item won't fit here: penalize if post-residual is in a
            // "dead" harmonic class that few items can use
            if post_residual < 10 {
                score += 8.0; // tiny residual likely wasted anyway, slight penalty for using this bin now
            }
            score += 5.0;
        }
        // modulo harmony: next_item_size mod class buckets
        let next_class = next_item_size % 10;
        if next_class == 0 {
            score -= 4.0; // round-sized next item pairs well with round residuals
        }
    }

    // Last-chance bin: only bin that fits — strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless this placement
    // would be terrible. New bin has residual == capacity.
    if bin_residual == bin_capacity {
        score += 55.0; // base cost of a fresh bin
        // but if item is huge and no tight option exists, new bin is fine:
        if item_size >= 60 {
            score -= 20.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer fuller bins: compare bin_residual tightness vs mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 6.0; // this bin is tighter than average: good
    } else {
        score += 3.0;
    }

    // Many open bins: encourage filling existing ones rather than spreading
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.5;
    }

    // Integer-division harmonic nudge: reward when item_size divides
    // harmonically into capacity classes (item mod 25 == 0 packs cleanly)
    if item_size % 25 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps.
    // A residual gap is "dead" if it's smaller than the smallest plausible item (1..100 range),
    // but especially toxic in the 1..=10 zone where almost nothing fits.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 6.0; // up to +60 for gap of 1
    } else if post_residual > 10 && post_residual <= 25 {
        score += (25.0 - post_residual as f64) * 0.8; // mildly toxic small-but-usable gap
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = (item_size as f64) / (bin_residual as f64);
        score -= tightness * 12.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // (penalize the new-bin candidate and discourage spreading).
    let bin_pressure = open_bins_count as f64 / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: strongly penalized, softened late in the stream
        // when leftover items may need fresh bins anyway.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 * (1.0 - 0.4 * progress) + bin_pressure * 10.0;
    } else {
        score -= bin_pressure * 2.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward this placement (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_slack = post_residual - next_item_size;
        if chain_slack <= 5 {
            score -= 15.0;
        } else {
            score -= 4.0;
