    } else if next_item_size > post_residual && post_residual > 0 && post_residual <= next_item_size {
        // Next item won't fit here anyway; penalize leaving a gap smaller than next item.
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier-of-space bins first,
    // keeping large residuals available for large future items).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    // Late-stream nudge: consolidate toward the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.85 {
        score -= post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
