    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score -= norm_pr * norm_pr * (1.0 + 40.0 * p2) * 12.0;
    score += norm_pr * norm_pr * norm_pr * (20.0 + 60.0 * p3);

    // Reward tight fits with smooth sigmoid-like term
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Lookahead: penalize if next item cannot use leftover space (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx as f64 {
            let gap = (nx - pr) / cap;
            score += gap * (30.0 + 40.0 * p2);
        } else {
            let slack = 1.0 - ((pr - nx) / cap).min(1.0);
            score -= 10.0 * slack * slack;
        }
    }

    // Last-chance bin bonus (smooth decay with progress)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: mildly penalize early, allow late when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress) - 12.0 * (1.0 - fit_ratio);
    }

    // Slight preference to spread among bins when many open (coupled with progress)
    score += (open_bins_count as f64).ln() * 0.3 * (1.0 - progress);

    // Mean residual coupling: prefer bins deviating below mean (keeps big bins free)
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += dev * (5.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division bands.
    let pr = post_residual;
    let band = pr / 10; // 0..=10 harmonic band
    let residue = pr % 10;

    // Reward low bands (tight fits) super-linearly.
    score -= (10 - band.min(10)) as f64 * 4.0;

    // Residue alignment: exact decade residuals are "clean" classes, reward slightly.
    if residue == 0 {
        score -= 3.0;
    } else if residue <= 2 {
        score -= 1.0;
    } else if residue >= 8 {
        score += 1.5; // sliver dead space penalty
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let next_post = pr - next_item_size;
            // Harmonic class match: next item leaves another clean decade.
            if next_post % 10 == 0 {
                score -= 8.0;
            } else {
                score -= 4.0;
            }
            // Extra reward if next item nearly fills the bin (chained tight fit).
            if next_post <= 5 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; penalize leaving mid-range dead space.
            if pr >= 10 && pr <= 30 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; small penalty so decent fits in open bins win.
        score += 6.0;
        // But if many open bins are cluttered (high mean residual), opening fresh is fine.
        if mean_residual > 40.0 {
            score -= 4.0;
        }
        // Early stream: opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 3.0;
    }

    // Fraction-of-capacity coupling: reward placing into bins whose fill ratio
    // crosses harmonic thresholds (25%, 50%, 75%).
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    for t in [0.25f64, 0.5, 0.75] {
        if fill < t && (fill + item_size as f64 / cap) >= t {
            score -= 5.0;
        }
    }

    // Penalize opening bins when few fitting bins exist but stream is late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if fitting_bins_count == 0 && bin_residual == bin_capacity && progress > 0.8 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful are toxic.
    // Assume unknown distribution -> treat very small gaps (< 10) as near-wasted,
    // and moderately small gaps (< 25) as risky.
    if post_residual < 10 {
        score += 60.0; // unusable sliver: heavy penalty
    } else if post_residual < 25 {
        score += 25.0; // risky gap
    }

    // Perfect fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // exact lookahead fit
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; this residual becomes potential dead space
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    // New-bin candidate (empty bin) gets pressure applied to discourage needless opening.
    if bin_residual == bin_capacity {
        score += pressure * 3.0 + 15.0;
        // But if no open bin fits well (large item), opening may be fine: soften when item is large.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight reward for using it, scaled by how full it already is.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 10.0;
        // Mild penalty relative to open bins count to consolidate.
        score += pressure * 0.3;
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (tighter bins first keeps looser bins flexible).
    let residual = bin_residual as f64;
    if mean_residual > 0.0 && residual < mean_residual {
        score -= (mean_residual - residual) * 0.2;
    } else if residual > mean_residual {
        score += (residual - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity.
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (perfect chained packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match => strong bonus (subtract heavily).
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Penalize mismatch proportionally; small mismatches still mildly favored.
            score += diff * 0.35;
        }
        // If next item fits into post_residual, mild bonus; otherwise penalty
        // for creating a residual too small to be useful.
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 12.0 + post_residual as f64 * 0.2;
        }
    } else {
        // Last item: just minimize waste, tiny bonus for any nonzero residual.
        score += 0.0;
    }

    // Prefer bins whose residual is already below mean (filling laggard bins
    // keeps the bin profile tight); penalize bins far above mean residual.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when the
    // current fit is poor. Penalize opening a new bin mildly, more when many
    // bins are already open and stream is early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_penalty = 30.0 + 20.0 * (1.0 - progress);
        // If next item is huge and post_residual of a fresh bin would serve it,
        // reduce the penalty slightly (lookahead favors fresh capacity).
        if next_item_size > 0 && post_residual >= next_item_size {
            open_penalty -= 8.0;
        }
        score += open_penalty;
    }

    // Extra penalty for leaving dead space that nothing (size>=1) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress-based time horizon (dynamic).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let urgency = 0.5 + 0.5 * progress; // later in stream => close bins harder

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize large dead space, amplified by urgency.
        score += (post_residual as f64 / bin_capacity as f64) * 60.0 * urgency;
    }

    // Lookahead: reward if next item fits in the post residual (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.3 * next_item_size as f64;
        // Extra reward for near-perfect chain (next item leaves almost nothing).
        let chain_left = post_residual - next_item_size;
        score -= 20.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize if next item cannot use the leftover: dead space risk.
        score += 0.25 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0 * urgency;
    }

    // Global state coupling: many open bins with high mean residual =>
    // prefer consolidating into existing bins rather than fragmenting.
    if open_bins_count > 1 {
        score -= (open_bins_count as f64).ln() * 5.0;
        if (mean_residual - post_residual as f64).abs() < 5.0 {
            score -= 10.0; // keeps residual distribution homogeneous
        }
    }

    // New-bin candidate handling: empty bin should only win when the item
    // fits poorly in existing bins (large leftover risk) or few bins open.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual as f64) > mean_residual.max(1.0);
        if poor_fit_elsewhere || open_bins_count == 0 {
            score -= 25.0;
        } else {
            score += 80.0 + 0.5 * item_size as f64; // discourage wasteful new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let tight = 1.0 - pr / cap;
    // Non-linear polynomial coupling of tightness with stream progress
    score -= 12.0 * tight * tight * (0.5 + progress);
    // Reward near-exact fits, smoothly
    score -= 8.0 * (-pr * pr / 50.0);
    // Penalize dead space when many bins are open
    score += (open_bins_count as f64).ln() * (pr / cap).powi(3) * 6.0;
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 + progress);
    }
    // Lookahead: favor bins leaving room for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 6.0 * (-gap * gap / 80.0);
    }
    // Smooth new-bin preference early in the stream
    score += (1.0 - progress) * (pr / cap) * 4.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: how "usable" is the leftover space? ---
    // Residuals divisible by common item sizes (or small) are highly reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure: bin completely filled
    } else {
        // Fraction of capacity wasted
        let waste_frac = pr as f64 / cap;
        score += 30.0 * waste_frac * waste_frac; // quadratic penalty on dead space

        // Harmonic class: post_residual mod small integers
        // If leftover is a multiple of a typical small item size (or >= min size), it's reusable
        let min_item = 1u32;
        if pr >= min_item {
            score -= 8.0; // leftover can still accept something
        }
        // Modulo classes: leftover fitting exactly common denominators is golden
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 3.0; }

        // Integer-division threshold: leftover in "awkward" band (e.g., 1..10) is nearly dead
        if pr < 10 {
            score += 12.0 * (1.0 - pr as f64 / 10.0);
        }
    }

    // --- Tight fit reward: item fills most of the bin's current residual ---
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // --- Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // --- Lookahead (k=2): reward bins whose leftover can host the next item ---
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 15.0; // chain placement possible
            // exact pairing: post residual equals next item size -> perfect chain
            if pr == next_item_size {
                score -= 10.0;
            }
        } else {
            score += 5.0; // next item won't fit here; less valuable to keep open for it
        }
    } else {
        // Last item: closing bins fully matters most
        score += 2.0 * pr as f64 / cap;
    }

    // --- New-bin candidate logic: only open a new bin when existing fits are poor ---
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; slight preference when current bins are fragmented
        score = 55.0 + 0.15 * mean_residual - (post_residual as f64);
        // Prefer new bin late in stream if many bins open (fragmentation)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        // If many bins already fit the item, discourage opening a new one
        if fitting_bins_count > 0 {
            score += 12.0 * (fitting_bins_count as f64).min(4.0);
        }
        // If next item is huge, a fresh bin keeps flexibility
        if next_item_size > 0 && next_item_size as f64 > 0.6 * cap {
            score -= 8.0;
        }
    }

    // --- Mild exploration: mod-based tie-breaking on residual classes ---
    let class = (post_residual / 7) % 3;
    score -= class as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // fit a plausible future item (1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Gaps in [10,20) are usable only by small items; still risky.
        score += 12.0;
    }

    // Reward tight fits (low post_residual) non-linearly.
    let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Perfect fit is a gift: strongly prefer.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += 0.8 * open_bins_count as f64 * (1.0 - fill);

    // Last-chance bin: if this is the ONLY bin that fits, avoid forcing a new bin
    // unless the placement would create dead space.
    if fitting_bins_count == 1 {
        if post_residual < 10 && post_residual > 0 {
            score += 30.0; // dead space in only fitting bin -> prefer new bin
        } else {
            score -= 15.0; // acceptable fit -> keep stream consolidated
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a new bin; gets cheaper late in stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 40.0 - 15.0 * progress;
        // If item would leave a large usable residual, new bin is attractive
        // when existing bins are fragmented.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        // Never open a new bin for an item that fits perfectly somewhere.
        if fitting_bins_count > 0 && item_size >= 90 {
            score += 50.0;
        }
        return score;
    }

    // Lookahead coupling: if next item would exactly fit the post_residual,
    // this placement is excellent (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // Next item can't use this gap anyway -> dead space is more tolerable.
            score -= 3.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            // Next item would leave another dead gap -> penalize.
            score += 8.0;
        }
    }

    // Mild preference for bins below mean residual (balance fragmentation).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Perfect chain: next item exactly fills the bin afterwards.
        if next_item_size == post_residual {
            score -= 45.0;
        }
        // Next item slightly smaller than post residual -> small dead space.
        if next_item_size < post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here; penalize leaving a large awkward residual.
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer tightest fit, strongly.
        score -= 50.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are more precious.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 6.0 * (rel - 1.0);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize creating tiny unusable residuals (dead space under typical small item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer fuller bins overall (best-fit flavor).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    // New-bin candidate: keep it neutral-to-slightly-high so it's chosen only
    // when no open bin offers a good (lookahead-matched) fit.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If stream is late and many bins open, discourage spreading further.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 10.0 * progress;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin guarantees a future home for the next item.
            score -= 5.0;
        }
    }

    // Mild penalty for opening bins when few items remain.
    if bin_residual == bin_capacity && total_items > 0 {
        let remaining = total_items.saturating_sub(step_index) as f64;
        if remaining < 3.0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared bonus for small leftover space.
    score -= ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(6) * 30.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize leaving a gap that exactly blocks the next item,
    // reward leaving a gap that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Time horizon: early in the stream, keep bins flexible (penalize tiny residuals
    // that become dead space); late in the stream, prioritize packing tightly now.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if t < 0.5 {
        if post_residual > 0 && post_residual < 10 {
            score += 15.0 * (1.0 - t * 2.0);
        }
    } else {
        score -= 10.0 * (t - 0.5);
    }

    // Global state: many open bins -> consolidate; few open bins -> opening new is cheap.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Penalize bins far from mean residual when they'd become wasteful.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: only attractive if item is large or no good fits exist.
    if bin_residual == bin_capacity {
        score += 25.0
            - 0.3 * item_size as f64
            - (if fitting_bins_count == 0 { 60.0 } else { 0.0 });
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear saturation.
    let mut score = norm_pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more (dead space penalized harder).
    let coupling = 2.5 * progress * (1.0 - progress) + 1.5 * progress * progress;
    score += coupling * norm_pr * norm_pr;

    // Reward near-perfect fits smoothly (smoothed indicator on norm_pr).
    let tightness = (1.0 - norm_pr).powi(4);
    score -= 3.0 * tightness * (0.5 + progress);

    // Penalize bins whose residual deviates from mean residual (imbalance).
    score += 0.4 * ((pr - mean_residual) / cap).abs();

    // Last-chance bin: strongly favor using it when it fits well.
    if fitting_bins_count == 1 {
        score -= 2.0 + 1.5 * tightness;
    } else {
        score -= 0.3 * (fitting_bins_count as f64).ln().max(0.0) * tightness;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 2.0 * (1.0 - gap).powi(3);
        score += 0.5 * gap;
    }

    // Mild penalty for opening a new bin when many bins are open and stream is late.
    if bin_residual == bin_capacity {
        score += 1.2 + 1.5 * progress - 0.05 * open_bins_count as f64;
        // But new bin is fine if current fit would leave large dead space.
        score += 2.0 * norm_pr_max(0.0, (bin_residual as f64 - item_size as f64) / cap) * 0.0;
    }

    // Small tie-breaker favoring fuller bins.
    score -= 0.01 * (item_size as f64 / cap);

    score
}

#[inline]
fn norm_pr_max(a: f64, b: f64) -> f64 { if a > b { a } else { b } }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor(); // 0..3 : quarters of capacity

    // Reward tight fits (small class), especially near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    }

    // Modulo arithmetic on post_residual: residues near multiples of 10 leave
    // "harmonic" gaps that typical items (multiples of 10) can still fill.
    let residue_mod = post_residual % 10;
    if residue_mod == 0 {
        score -= 6.0;
    } else {
        score += (residue_mod as f64) * 0.8; // awkward non-decade gap
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement creates a perfect chain — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 30.0;
            } else {
                score += slack as f64 * 0.15;
            }
        } else {
            // next item cannot use the leftover: leftover is likely dead space
            score += (post_residual as f64) * 0.10;
        }
    }

    // Integer-division threshold on bin_residual: bins that are already more
    // than half full should be preferred to close them out.
    let half_fill = bin_residual <= bin_capacity / 2;
    if half_fill {
        score -= 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate penalty: opening a bin wastes the aggregate residual
    // already spread across open bins. Penalize proportionally to how much
    // usable space exists elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
        // But late in the stream, a fresh bin is less costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Mild pressure to balance residuals toward the mean (avoid extreme gaps).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Small tie-breaker favoring fuller bins via capacity fraction class.
    score -= class * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are small but nonzero are
    // the worst outcome (unusable gaps). Zero residual is perfect.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += 40.0; // tiny unusable gap
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // Prefer bins whose residual is close to the item (best-fit coupling).
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 25.0 * tightness * tightness;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 * (1.0 - post / cap); // dead space blocks the known next item
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another;
    // the new-bin candidate gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Opening a new bin is only sensible if no bin fits well.
        if fitting_bins_count > 0 {
            let best_possible = mean_residual.min(cap);
            if best_possible - item_size as f64 <= 5.0 {
                score -= 20.0; // existing bins are all near-full anyway
            }
        }
    } else {
        // Mild preference for fuller bins among open candidates.
        score += 0.1 * (bin_residual as f64 / cap) * open_bins_count as f64;
    }

    // Late-stream consolidation: as the stream progresses, prefer closing
    // bins out (zero residual) even harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits exactly into remaining space after a near-perfect split.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize leaving a gap slightly larger than next item.
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 * (gap / 20.0).min(1.0);
    }

    // Reward tight fits relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let best_open = if fitting_bins_count == 0 {
            0.0
        } else {
            mean_residual
        };
        let pressure = (item_size as f64) / bin_capacity as f64;
        // Open a new bin if open bins are crowded (high mean residual usage).
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0 + 10.0 * pressure;
        } else {
            score += 40.0;
        }
        let _ = best_open;
    }

    // Mild late-stream conservatism: consolidate into fewer bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Penalize creating dead space that no future item (min size 1..10 typical) can use.
    if post_residual > 0 && post_residual < item_size {
        score += 5.0; // residual smaller than current item: likely dead space
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 200.0;
        } else {
            score -= 40.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here after placement; mild penalty for wasting this bin's future.
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer the tightest — already handled by tightness,
        // but add mild congestion term to spread load.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Global state: many open bins with large mean residual → prefer filling existing bins
    // rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when existing bins are roomy or many bins open.
        score += 25.0 + mean_residual * 0.5 + open_bins_count as f64 * 3.0;
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If next item is large and no bin likely fits it, opening a fresh bin is fine.
        if next_item_size > 50 {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward filling bins with high residual (large waste potential).
        score -= (bin_residual as f64 - mean_residual) * 0.3;
        // Late in stream, consolidate aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    // Slight preference for bins whose residual is close to item_size (snug fit).
    let snug = 1.0 - ((bin_residual as f64 - item_size as f64) / bin_capacity as f64);
    score -= snug * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Non-linear polynomial coupling: waste penalty grows quadratically with
    // post_residual and is amplified as the stream progresses.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * cap * (0.5 + 1.5 * progress * progress);

    // Reward tight fits: subtract a smooth term when post_residual is small
    // relative to item size.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (item_size as f64) * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only bin that can fit the item,
    // scaled smoothly by progress.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead coupling: if the next item exactly fits the post_residual,
    // this is a perfect chain; reward it heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            // Reward closeness of next item to post_residual (smooth, non-linear)
            score -= 25.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
        } else {
            // Penalize post_residuals that are just slightly too small for the
            // next item (dead space trap), quadratic in the shortfall.
            let shortfall = nxt - post_residual as f64;
            score += 0.35 * shortfall * shortfall / cap;
        }
    }

    // Mild penalty for spreading across many open bins; encourage consolidation
    // early, relax later (smooth interaction with progress).
    score += (open_bins_count as f64).sqrt() * (1.5 - 1.0 * progress);

    // Prefer bins whose residual is below mean residual (filling emptier bins
    // of similar fill level), smooth polynomial coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev - 3.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 18.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 (capacity fractions).
    let pr = post_residual;
    let residue = (pr % 10) as f64;
