    // Reward exact / near-exact fills (small post_residual).
    if pr == 0 {
        score -= 200.0;
    } else if pr <= 5 {
        score -= 100.0;
    } else if pr <= 10 {
        score -= 40.0;
    }

    // Penalize "dead zone" residuals that few item sizes can fill.
    // Items are 1..100, but small residuals are hard to reuse; scale by residue class.
    if pr > 0 && pr < 10 {
        score += 60.0 - residue * 5.0; // residue 9 slightly better than residue 1
    }

    // Harmonic tier: residuals in [10,30) are moderately reusable, [30,60) good.
    if pr >= 10 && pr < 30 {
        score += 8.0;
    } else if pr >= 30 && pr < 60 {
        score -= 6.0;
    } else if pr >= 60 {
        score -= 12.0;
    }

    // Integer-division threshold coupling with next item: if the next item
    // fits exactly into post_residual, strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0;
        } else if next_item_size <= pr {
            score -= 15.0;
        } else {
            // Next item won't fit here; mild penalty proportional to overflow.
            score += ((next_item_size - pr) as f64) * 0.3;
        }
        // Modulo harmony: if pr and next item share a residue class mod 10
        // and next fits, packing is more likely later.
        if next_item_size <= pr && (pr % 10) == (next_item_size % 10) {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight.
    if bin_residual == bin_capacity {
        let waste = 100.0 - item_size as f64;
        score += waste * 1.2;
        // Early in stream, opening bins is fine; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // If mean residual is large, discourage new bins.
        score += mean_residual * 0.5;
    } else {
        // Prefer tighter bins (best-fit reinforcement) beyond raw post_residual.
        score += (bin_residual as f64 - item_size as f64) * 0.1;
        // Many open bins: encourage filling existing ones.
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

