}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are nearly worthless. Penalize unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead gap: worst outcome
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    } else if post_residual < 35 {
        score += 10.0 * (1.0 - (post_residual as f64 - 20.0) / 15.0);
    }

    // Reward tight fits: how much of the bin's usable space the item consumes.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count == 2 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post-residual, this placement
    // chains nicely; reward it. If next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 5 {
            score += 8.0; // near-miss creates likely dead space
        }
    }

    // New-bin candidate handling: an empty bin has large post_residual,
    // which is naturally good, but discourage spreading items thin when
    // open bins already have low mean residual (good fits exist).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64).min(1.0);
    }

