    // the mean (they are outliers with lots of trapped space).
    let resid = bin_residual as f64;
    if mean_residual > 0.0 {
        let deviation = resid - mean_residual;
        score += deviation.max(0.0) * 0.08;
        score -= (-deviation).max(0.0) * 0.04;
    }

    // New-bin candidate handling: brand-new empty bin (residual == capacity).
    // Prefer it only when the item fits very poorly in every open bin context
    // (large item relative to typical residuals) or late in the stream.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let poor_fit = if mean_residual > 0.0 {
            (item_size as f64 - mean_residual).max(0.0) / bin_capacity as f64
        } else {
            1.0
        };
        // Default cost of a fresh bin, discounted when fit is poor or stream is late.
        let new_bin_cost = 40.0 - 35.0 * poor_fit - 15.0 * progress - 10.0 * item_frac;
        score += new_bin_cost.max(2.0);
    }

    // Reward near-perfect fills: residual of 0..=2 is golden.
    if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Slight time-horizon scaling: early on, be more exploratory (flatter scores);
    // late, sharpen the tight-fit preference.
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let sz = item_size as f64;

    // Base: post-residual with non-linear decay favoring tight fits.
    let mut score = pr * (1.0 + 0.8 * (pr / cap).powi(2));

    // Smooth interaction: as the stream progresses, penalize larger leftovers more strongly.
    score += 6.0 * progress * (pr / cap) * (pr / cap) * cap;

    // Reward using a nearly-full bin (small post residual) via smooth saturating term.
    score -= 4.0 * (-pr / 12.0).exp() * (1.0 + 2.0 * progress);

    // Last-chance bin: strongly favor it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr / cap);
    }

    // Penalize bins whose residual is far above the mean (wasteful placement).
    score += 0.5 * (res - mean_residual).max(0.0);

    // Lookahead: reward leaving room for the next item, smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 3.0 * (1.0 - (gap / cap).powi(2)) * (1.0 + progress);
        } else {
            score += 2.0 * (-gap / cap);
        }
    }

    // Mild penalty for opening a new bin when many bins already exist.
    if res == cap {
        score += 3.0 + 0.05 * open_bins_count as f64 - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Harmonic class of post_residual: small residuals are "dead space" classes.
    let class = post_residual / 10; // 0..=10 harmonic bucket
    // Penalize tiny residual classes (unusable slivers), reward mid classes.
    match class {
        0 => score += 30.0,               // residual < 10: dead space
        1 => score += 18.0,               // 10..19
        2 => score += 8.0,                // 20..29
        3 => score -= 6.0,                // 30..39: useful for typical items
        4 => score -= 10.0,               // 40..49
        5 => score -= 8.0,
        6 => score -= 4.0,
        7 => score += 3.0,
        8 => score += 6.0,
        9 => score += 10.0,
        _ => {}                            // near-full bin: neutral
    }

    // Exact-fill reward: perfect packing.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 12.0 * (1.0 - gap as f64 / cap).min(1.0);
        } else {
            // next item cannot use this residual: mild penalty proportional to overshoot
            score += 4.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize unless current fit is poor.
    if bin_residual == bin_capacity {
        score = cap * 0.55; // base cost of opening a bin
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        } else if pr > 40.0 && (fitting_bins_count as f64) > 0.0 {
            // opening new bin may be fine if all fits leave big residuals
            score -= 15.0;
        }
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - pr / cap);

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean.
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1..100 domain -> use a small threshold) are wasted.
    // Penalize "unusable" gaps super-linearly.
    let dead_threshold: u32 = 5;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }

    // Perfect fits are gold: reward strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: the item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 6.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading; penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 4.0 + open_bins_count as f64 * 0.5;
    } else {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement (sets up a perfect follow-up).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // If next item could fit in post residual, mild reward.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.3;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (fewer items left to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    // Prefer bins with residual close to the item (best-fit character),
    // scaled against the mean residual of open bins.
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 12.0 * (1.0 - tightness.min(1.0));

    // 2-step lookahead: reward when next item fits the post residual exactly/well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            let match_quality = 1.0 - gap / bin_capacity as f64;
            score -= 18.0 * match_quality; // strong reward for chainable residual
        } else {
            // Next item cannot fit: residual is likely dead space, but if next
            // item fits into a smaller residual it's still fine; penalize large
            // unchainable residuals.
            let excess = (next_item_size - post_residual) as f64;
            score += 0.08 * excess;
        }
        // Perfect 2-step chain: residual exactly equals next item size
        if next_item_size == post_residual {
            score -= 10.0;
        }
    } else {
        // Last item: any residual is pure waste; minimize it hard.
        score += 20.0;
    }

    // Penalize residuals that deviate from mean (keep bin pool balanced),
    // unless this is a very tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 30.0;
        // If several bins fit, discourage opening a new one.
        if fitting_bins_count >= 1 {
            score += 10.0 * fitting_bins_count as f64;
        }
        // If item is large relative to mean residual, open bins are fragmented;
        // a new bin becomes more attractive.
        let frag = mean_residual - item_size as f64;
        if frag > 0.0 {
            score -= frag.min(60.0);
        }
        // Lookahead: new empty bin can always chain the next item.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 8.0;
        }
        // Early in stream: slightly cheaper to open bins (build capacity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Mild bonus for using bins with many fitting alternatives less eagerly
    // (save flexible bins for harder items).
    if !is_new_bin && fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Penalize leaving residuals in the awkward 1..10 dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

