pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate large residuals (favor new bins / flexibility);
    // late in the stream, strongly penalize leftover space.
    let progress_sq = progress * progress;
    let progress_cu = progress_sq * progress;
    let coupling = pr_norm * pr_norm * (1.0 + 6.0 * progress) + pr_norm * (2.0 + 8.0 * progress_cu);
    score += coupling * cap;

    // Reward tight fits via smooth saturating term on fill ratio
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill * (1.0 - progress * 0.5);

    // Penalize bins whose residual deviates from mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        // penalize creating residuals too small for the next item
        score += 4.0 * (1.0 - progress);
    }

    // New-bin candidate: mild penalty early, discount late
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress) - 10.0 * progress;
    }

    // Slight preference for consolidating into fewer bins
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes.
    let pr = post_residual;
    let class = pr % 10; // decile residue class
    match class {
        0 => score -= 6.0,   // perfectly divisible residual -> highly reusable
        5 => score -= 3.0,   // half-capacity fraction classes
        2 | 4 | 6 | 8 => score -= 1.5, // even residuals pack better
        _ => score += 1.0,   // odd residuals create awkward fits
    }

    // Integer-division thresholds: residual in "slots" of common item sizes
    let slot10 = pr / 10;
    if slot10 >= 8 {
        score -= 4.0; // large residual is valuable
    } else if slot10 <= 1 && pr > 0 {
        score += 5.0; // tiny dead space is waste
    }

    // Perfect-fit reward
    if pr == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        if pr % next_item_size == 0 {
            score -= 8.0;
        } else {
            score -= (next_item_size as f64) / (1.0 + pr as f64 / 50.0);
        }
    }
    // Penalize leaving residual smaller than next item but larger than min size
    if next_item_size > pr && pr > 0 {
        score += 3.0;
    }

    // New-bin candidate: neutral baseline anchored on mean residual pressure
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + mean_residual * 0.4 - progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 4.0; // bigger item coming, fresh bin helps
        }
    }

    // Slight preference for tight fills relative to mean residual
    score -= (bin_capacity as f64 - pr as f64 - item_size as f64).abs() * 0.05;
    score += (mean_residual - pr as f64).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

