    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Lookahead: bonus if the next item can still fit in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
