    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Penalize opening new bins when good fitting bins exist
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Early in stream: be slightly conservative, keep bins flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits (small post_residual relative to item)
    score -= 5.0 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
