        score += post_residual as f64 * 0.5;
    }

    // Global state: when many bins are open, prefer consolidation into emptier bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score += (bin_residual as f64 - mean_residual) * 0.15 * progress;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
