        let mut new_bin_cost = 22.0;
        new_bin_cost -= 10.0 * progress;
        new_bin_cost -= (mean_residual / bin_capacity as f64) * 10.0;
        if open_bins_count == 0 {
            new_bin_cost = -100.0; // must open a bin
        }
        // If the next item is large and this fresh bin can hold item + next,
        // opening is more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_cost -= 15.0;
        }
        score += new_bin_cost;
    }

