    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: prefer it only when item is large and fits poorly elsewhere
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 12.0 - 10.0 * fill * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: bins whose post_residual
    // lies in "useful" modular classes (multiples of small sizes) should be favored.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward post_residuals that are multiples of common item sizes (harmonic classes).
    let mut harmony = 0.0f64;
    for m in [10u32, 20, 25, 50].iter() {
        if m > 0 && pr % m == 0 && pr > 0 {
            harmony += 1.0;
        }
    }
    score -= harmony * 6.0;

    // Penalize tiny unusable slivers: post_residual below the minimum item size.
    if pr < 10 && pr > 0 {
        score += 25.0;
    }

    // Exact fill is perfect.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item exactly matches post_residual,
    // strongly favor this bin (perfect chained fit).
    if next_item_size > 0 && next_item_size == pr {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // Reward if next item still fits with a harmonically-classed leftover.
        let next_left = pr - next_item_size;
        if next_left % 10 == 0 {
            score -= 8.0;
        }
        score += (next_left as f64) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64) * (mean_residual / cap);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in the stream with crowded bins, opening a new bin is fine;
        // early on with few bins, prefer filling existing ones.
        let new_bin_penalty = 30.0 - 15.0 * progress - crowd.min(20.0);
        score += new_bin_penalty.max(-10.0);
        // If no open bin is a good fit (post_residual of others would be tiny), allow new bin.
        if item_size > 70 {
            score -= 10.0;
        }
    }

    // Fraction-of-capacity class penalty: leave at least a quarter bin when possible.
    let quarter = bin_capacity / 4;
    if pr > 0 && pr < quarter {
        score += 5.0;
    }

    // Mild tie-break toward bins tighter than the mean residual.
    score += ((mean_residual - post_residual as f64) * 0.05).max(-5.0).min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100, assume min ~10).
    let min_item = 10.0f64;
    if (post_residual as f64) < min_item && post_residual > 0 {
        // Perfect fill or near-perfect fill: strong reward.
        score -= 60.0;
    } else if post_residual == 0 {
        score -= 100.0;
    } else {
        // Non-linear penalty: small gaps that no future item (incl. lookahead) can use are costly.
        let usable_by_next = (next_item_size > 0) && ((post_residual as u32) >= next_item_size);
        if !usable_by_next {
            // Gap too small even for the lookahead item: dead space penalty grows as gap shrinks.
            let gap = post_residual as f64;
            score += (min_item - gap).max(0.0) * 3.0;
        }
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: with many open bins, prefer closing bins out (lower post_residual),
    // and discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    score += bin_pressure * 2.0;

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to residual
    // left behind in all open bins. Penalize new-bin option when open bins exist and
    // mean residual is small (bins are nearly full already).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let waste = mean_residual * open_bins_count as f64;
        score += 30.0 + waste * 0.5;
    }

    // If lookahead item fits in post_residual, this placement chains nicely: reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        // Lookahead won't fit here after placement; mild penalty unless residual is dead anyway.
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins),
    // leaving looser bins for future items.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) but penalize near-zero unusable slivers.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0; // dead space of 1-4 is nearly unusable
    }

    // 2-step lookahead: reward when the NEXT item exactly matches the post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 25.0; // perfect 2-chain: next item fills this bin completely
        } else if (diff as u32) <= 5 {
            score -= 12.0;
        } else if (post_residual as i64) > (next_item_size as i64) {
            score -= 4.0; // next item still fits here, keeps chain alive
        } else {
            score += (diff as f64) * 0.3; // next item won't fit; residual likely wasted
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious tight fits.
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize opening a new bin
    // unless the current item is large and no good fit exists.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 70 && (fitting_bins_count == 0 || mean_residual < item_size as f64) {
            score -= 35.0; // big item with no decent home: open fresh bin
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 5.0; // pairing impossible anyway
        }
    }

    // Late-stream pressure: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: favor filling existing ones over spreading.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residuals.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Exact-fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: reward if the next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            let gap_frac = gap / bin_capacity as f64;
            // Reward pairing, strongest when gap is tiny.
            score -= 45.0 * (1.0 - gap_frac) * (1.0 - gap_frac);
            if gap == 0.0 {
                score -= 80.0; // perfect chain
            }
        } else {
            // Post-residual too small for the next item: penalize stranded slivers
            // proportional to how unusable the leftover is.
            let sliver = post_residual as f64;
            if next_item_size > sliver {
                let unusable = 1.0 - (sliver / next_item_size as f64).min(1.0);
                score += 25.0 * unusable * (sliver / 100.0);
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
        if post_residual <= 10 {
            score -= 60.0; // near-perfect fill on the last chance
        }
    }

    // Penalize bins whose residual is far below the mean (already heavily filled
    // bins should still be preferred for tight fits, but avoid starving diverse bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Time horizon: early in the stream, keep bins balanced (favor moderate residuals);
    // late in the stream, aggressively close out bins (favor smallest post-residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress * tight;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln() * tight;
    }

    // New-bin candidate handling: empty bin should only win when no open bin offers
    // a decent fit. Penalize opening a new bin, more so when good fits exist.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count > 0 {
            score += 25.0 + 10.0 * (1.0 - tight);
        }
        // Late in stream, opening new bins is cheaper than scattering leftovers.
        score -= 35.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can host a chain
        }
    }

    // Small global noise-free tie-breaker scaled by item size to break exact ties
    // toward larger items entering fuller bins.
    score += 0.01 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: best-fit signal (lower post_residual => better fit)
    let mut score = pr;

    // Smooth non-linear coupling of tightness with stream progress:
    // late in the stream, reward tight fits more aggressively.
    let tightness = 1.0 - pr / cap; // in (0,1], 1 = perfect fit
    score -= tightness * tightness * (0.5 + 2.5 * progress) * cap * 0.1;

    // Penalize large-but-not-tight residuals quadratically (dead space risk)
    let waste = pr / cap;
    score += waste * waste * 20.0 * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - slack) * (0.5 + progress);
    } else if next_item_size > 0 {
        // penalize leaving residual that cannot fit next item but is too big to waste
        score += 5.0 * waste;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no bin fits, or the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // discourage opening new bins when decent fits exist;
            // relax late in the stream (fewer future items to balance)
            let desperation = (it / cap) * (1.0 - progress);
            score += 25.0 * (1.0 - desperation) + 10.0 * (mean_residual / cap);
        }
    }

    // Mild preference for fuller bins among many open bins
    score += (open_bins_count as f64).ln().max(0.0) * pr * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "reusable" residue classes (multiples of 10 and mid-range chunks)
    // are favored; tiny dead-space residues are penalized.
    let r = post_residual;
    let class = (r / 10) % 10; // decade class 0..9
    match class {
        0 => score -= 6.0,            // exact / near-exact fill: excellent
        1 => score -= 3.0,            // small but still usable
        2 | 3 => score -= 1.5,        // mid-small chunk
        4 | 5 => score -= 2.5,        // half-capacity-like: very reusable
        6 | 7 => score -= 1.0,
        _ => {}                        // large residual: barely used bin
    }

    // Penalize dead space that no plausible item (>=1) can exploit:
    // post_residual == 0 is perfect; post_residual == 1..3 is dead.
    if r == 0 {
        score -= 8.0;
    } else if r <= 3 {
        score += 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post-residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 10.0;
        } else if next_item_size <= r {
            score -= (r - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; slight penalty scaled by overflow
            score += (next_item_size - r) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish baseline
    // so that any reasonably good existing fit beats it, but a poor
    // fit (large post_residual waste) does not.
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits: new bin is necessary
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0; // pairing big items together
        }
    }

    // Mild stream-position adaptation: late in the stream, prefer
    // closing bins tightly (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (r % 7) as f64 * 0.3;

    // Prefer bins with residual below mean (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Threshold tuned around smallest item (1..100).
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            60.0 // unusable tiny gap
        } else if post_residual < 20 {
            25.0 // only fits very small items
        } else {
            0.0
        };
        score += dead;
    }

    // Reward near-perfect fits (waste <= 5).
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // gap too small for the upcoming item: dead space
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    if bin_residual == bin_capacity {
        // Opening new bins is costly; penalize when decent alternatives exist.
        if fitting_bins_count > 0 {
            score += 30.0 + 5.0 * open_bins_count as f64;
        } else {
            score = -100.0; // must open a bin
        }
        // Late in stream, prefer filling existing bins even more.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 20.0;
        }
    }

    // Open-bin pressure: with many open bins, favor consolidating into
    // tighter (smaller-residual) bins to close them out sooner.
    score += (open_bins_count as f64) * (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // perfect two-step chain: this bin will be exactly filled next step
        } else if post_residual >= next_item_size {
            // next item fits here too; the closer the chain, the better
            score -= 18.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // next item won't fit here; penalize leaving dead space
            score += 8.0 + 0.25 * (post_residual as f64);
        }
    } else {
        // Last item: strongly prefer minimal residual
        score += 2.0 * post_residual as f64;
    }

    // Tightness reward: small post_residual relative to mean residual is good
    let tight = 1.0 - (post_residual as f64 / (mean_residual + 1.0)).min(2.0) * 0.5;
    score -= 10.0 * tight;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly worse than a good fit
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * post_residual as f64;
    }

    // Penalize very large leftovers that become unusable (min item size ~1, but waste is waste)
    if post_residual > bin_capacity / 2 {
        score += 6.0;
    }

    // Progress-aware: early in stream, keep bins flexible (prefer moderate residual spread)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post-residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Reward filling a bin completely (exact or near-exact fit).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: mildly good, scaled by leftover slack.
            let slack_after_next = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder: slight penalty
            // proportional to wasted potential.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    } else {
        // Last item: prioritize any fit, prefer emptiest residual.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin, more strongly when
    // existing bins fit well and many bins are already open.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 40.0 + 3.0 * open_bins_count as f64;
        // If item leaves a large unusable gap in a new bin relative to
        // typical item sizes, penalize more.
        if post_residual > 0 && post_residual < 10 {
            new_bin_penalty += 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += 25.0 * progress;
        // If mean residual across open bins is high, opening a new bin wastes capacity.
        if mean_residual > item_size as f64 {
            new_bin_penalty += 0.3 * (mean_residual - item_size as f64);
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: small reward for using bins with larger residuals first
        // (best-fit with tie-break toward consolidating big holes).
        score -= 0.05 * bin_residual as f64;
    }

    // Global balance: prefer bins whose residual is above the mean
    // (keeps a spread of usable holes).
    if bin_residual != bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear coupling: small residuals become more valuable as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize mid-range dead space with a smooth bump
    let bump = norm_pr * (1.0 - norm_pr) * 4.0;
    score += 12.0 * bump * bump;

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - ((pr - nx) / cap)).abs();
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Prefer bins with residuals below mean (pack tighter bins first)
    score += 0.15 * (mean_residual - pr);

    // Late stream: discourage leaving many half-empty bins
    score += progress * 5.0 * norm_pr;

    // New-bin candidate: penalize mildly so it only wins when open bins are hopeless
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit any future item
    // (min item size is 1, but practically gaps < ~10 are near-unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits: post_residual small relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 40.0 * tightness;

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }
    // If next item would be blocked by leaving this dead space, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 20.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Prefer bins with residual below mean residual (more fragmented bins get emptied first).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // New-bin candidate: default moderate score; only wins when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64;
        // If no existing bin fits, new bin should win outright.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post_residual can fit the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: reward tighter coupling (less leftover after two items).
            let two_step_left = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - two_step_left / bin_capacity as f64);
            // Extra reward for near-perfect 2-step packing.
            if two_step_left < 5.0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral baseline, slightly discouraged unless open bins are poor.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.1 * open_bins_count as f64;
        // Encourage opening a new bin when mean residuals are large (open bins too empty).
        score -= 0.05 * mean_residual;
    }

    // Progress-aware tightening: later in the stream, favor tighter fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}
